t.guides["forever/alliance/02-westfall"] = (function() return {
		["Back north past {area:918} to the mine: Kobold Diggers work inside."] = "De regreso al norte, más allá de {area:918}, hasta la mina: los Cavadores kóbold trabajan adentro.",
		["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore."] = "Los Zahoríes bribones de Defias acampan en las orillas de {area:86}; también sueltan los Pañuelos de lino rojo. {object:56} está en la aldea múrloc de la orilla noreste.",
		["Fill the vial at the farm's well"] = "Llena el vial en el pozo de la granja",
		["Fill the vial at the well"] = "Llena el vial en el pozo",
		["Follow the hills south to the tower."] = "Sigue las colinas hacia el sur hasta la torre.",
		["For {npc:266} in {area:69}, Redridge"] = "Para {npc:266} en {area:69}, Montañas Crestagrana",
		["Gnoll Paws"] = "Garras gnoll",
		["Harvest Watchers"] = "Vigías de la cosecha",
		["Head to {zone:1453}. It has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back for the boat."] = "Ve a {zone:1453}. No tiene instructor de chamán: toma el {area:2257} desde el {object:28027} hasta {zone:1455}, entrena con {npc:258098}, luego toma el tren de vuelta para el barco.",
		["It lies by the river north-west of the logging camp."] = "Está junto al río, al noroeste del campamento maderero.",
		["Kobold Diggers"] = "Cavadores kóbold",
		["Level 12, 14 and 16 spells"] = "Hechizos de nivel 12, 14 y 16",
		["Longshore Murloc Gills"] = "Agallas de múrloc de Playa Larga",
		["Only if you looted a {item:1972} in Elwynn: right-click it"] = "Solo si saqueaste {item:1972} en Elwynn: haz clic derecho en ella",
		["Red Linen Bandanas"] = "Pañuelos de lino rojo",
		["Riverpaw Miners"] = "Mineros Zarparrío",
		["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "Los gnolls Zarparrío acampan en las colinas al oeste de {area:86}; {quest:91725} están en sus campamentos.",
		["Shaman training"] = "Instrucción de chamán",
		["South along the road, past the fork. {npc:233} stands outside, {npc:235} in the house, {npc:253395} in the barn to the west. Young Goretusks and Fleshrippers roam the fields around the farm: start on livers and the stew's meat on the way."] = "Al sur por el camino, más allá del cruce. {npc:233} está fuera, {npc:235} en la casa, {npc:253395} en el granero al oeste. Jóvenes Colmillos y Desgarradores merodean los campos de la granja: empieza con los hígados y la carne del guiso de camino.",
		["South-west to the coast, west of {area:918}. Riverpaw Miners work the quarry."] = "Al suroeste, hacia la costa, al oeste de {area:918}. Los Mineros Zarparrío trabajan la cantera.",
		["The bridge"] = "El puente",
		["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it."] = "El campamento está al noreste del puente. Los Fardos de madera están alrededor del campamento y en el bosque al norte.",
		["The gnoll camps"] = "Los campamentos gnoll",
		["The gnoll hills"] = "Las colinas de los gnolls",
		["The mine is south-west of the gnoll camps. {item:247816} lie near the entrance; Kobold Geomancers hold the tunnels.\nCareful: {npc:471} (7-10), the Mine Spiders (7-9) and {npc:248474} (7) are elites deep in the mine: pull the kobolds one at a time near the entrance and back out if an elite comes; they're easier with a friend."] = "La mina está al suroeste de los campamentos gnoll. {item:247816} están cerca de la entrada; los Geománticos kóbold ocupan los túneles.\nCuidado: {npc:471} (7-10), las Arañas de mina (7-9) y {npc:248474} (7) son élites en lo profundo de la mina: atrae a los kóbolds de uno en uno cerca de la entrada y retírate si viene un élite; son más fáciles con un amigo.",
		["The {area:113}"] = "{area:113}",
		["The {area:88}"] = "{area:88}",
		["The {area:91}"] = "{area:91}",
		["{item:2449} for Gathering the Cure (6123) in {zone:1439}: {npc:1313}, Alchemy Supplies; herbalists pick it there instead"] = "{item:2449} para Reunir los ingredientes del remedio (6123) en {zone:1439}: {npc:1313}, suministros de alquimia; los herboristas la recogen allá",
		["{item:6529}, from {npc:5494}"] = "{item:6529}, de {npc:5494}",
		["{item:729}: Fleshrippers"] = "{item:729}: Desgarradores",
		["{item:814}: keep five for {npc:392} at the {area:115}, later on the route"] = "{item:814}: guarda cinco para {npc:392} en {area:115}, más adelante en la ruta",
		["{npc:1416}: his package for {npc:1343} in {zone:1432}, later on the route"] = "{npc:1416}: su paquete para {npc:1343} en {zone:1432}, más adelante en la ruta",
		["{npc:234} and {npc:821} stand at the top of the stone tower. {npc:491} is in the tower, {npc:878} on the south side of the hill, next to the inn and {npc:523} the gryphon master."] = "{npc:234} y {npc:821} están en lo alto de la torre de piedra. {npc:491} está en la torre; {npc:878}, en el lado sur de la colina, junto a la posada y {npc:523}, el maestro de grifos.",
		["{npc:237}: Humans may have it already from {npc:963} in Elwynn"] = "{npc:237}: puede que los Humanos ya la tengan de {npc:963} en Elwynn",
		["{npc:253092}, beside {npc:878}"] = "{npc:253092}, junto a {npc:878}",
		["{npc:5480} trains warriors in {object:2100}, near {npc:1323}'s shop; the tram from {zone:1455} arrives in the {object:28027}, north of it. {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "{npc:5480} entrena a los guerreros en {object:2100}, cerca de la tienda de {npc:1323}; el tranvía de {zone:1455} llega a {object:28027}, al norte. {npc:6089} y {npc:6090} están juntos ahí, junto a {object:2152}. {npc:6090} pelea contigo por su tarro. Si {npc:5480} no te ofrece {quest:1638}, ve directo con {npc:6089}: te da {quest:1639} sin ella.",
		["{npc:5494} sells fishing supplies along the canal just west of the {object:2096}; {npc:267118} fishes at the harbor, on the way to the boat."] = "{npc:5494} vende suministros de pesca junto al canal, justo al oeste de {object:2096}; {npc:267118} pesca en el puerto, de camino al barco.",
		["{npc:5497}, Wizard's Sanctum: {quest:1861}"] = "{npc:5497}, Wizard's Sanctum: {quest:1861}",
} end)()
t.guides["forever/alliance/03-darkshore"] = (function() return {
		["At the {area:2362}"] = "En {area:2362}",
		["Back north-east into the mountains to the crystal."] = "Vuelve al noreste, a las montañas, hasta el cristal.",
		["Bears and the Blackwood camp"] = "Osos y el campamento Bosque Negro",
		["Blackwood Pathfinders and Windtalkers hold the camp south-east of {area:442}."] = "Los abrecaminos y soplavientos Bosque Negro ocupan el campamento al sureste de {area:442}.",
		["Blackwood furbolgs"] = "Fúrbolgs Bosque Negro",
		["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "Sube a las montañas al este de {area:447}; el {object:175524} está en una cornisa.",
		["Crawler Legs"] = "Patas de reptador",
		["East of Buzzbox 323, {npc:3661} hides at the foot of the tower among the Dark Strand Fanatics. Keep his letter for Delgren in {zone:1440}.\nCareful: Dark Strand Voidcallers (28-29) with their voidwalkers and {npc:3660} (31) stand in the tower itself: take the parchments from the Fanatics south of it and keep away from the tower."] = "Al este de la Caja mecánica 323, {npc:3661} se esconde al pie de la torre entre las fanáticas de la Facción Oscura. Guarda su carta para Delgren el Purificador en {zone:1440}.\nCuidado: los Llamacíos de la Facción Oscura (28-29) con sus abisarios y {npc:3660} (31) están en la torre misma: consigue los pergaminos de las fanáticas al sur de ella y mantente lejos de la torre.",
		["Fill the tube at the moonwell in the village"] = "Llena el tubo en el pozo de la luna del pueblo",
		["Follow the hills north to the {area:456} and up to the falls. Two more beached remains lie on the north shore: near the {area:443} and north of {quest:954}."] = "Sigue las colinas hacia el norte hasta {area:456} y sube a las cascadas. Hay dos restos varados más en la costa norte: cerca de {area:443} y al norte de {quest:954}.",
		["Grell Earrings"] = "Pendientes grell",
		["Highborne Relics"] = "Reliquias de Altonato",
		["Kill Rabid Thistle Bears in the hills east of {area:442}, then walk up to the furbolg camp south-east of them: nothing to kill yet."] = "Mata osos cardo rabiosos en las colinas al este de {area:442} y luego sube al campamento fúrbolg al sureste de ellos: aún no hay que matar nada.",
		["Moonstalker Fangs"] = "Colmillos de Acechalunas",
		["Moonstalkers prowl the hills between {quest:954} and the tower. {quest:1002} stands on the hill west of the tower."] = "Los Acechalunas merodean por las colinas entre {quest:954} y la torre. {quest:1002} está en la colina al oeste de la torre.",
		["Night Elves fly from {area:442} to {area:702}; Skyborne take the boat from the {area:442} dock and learn the Rut'theran flight path. Then take the portal up to {npc:4217} in the {area:1658}."] = "Los elfos de la noche vuelan de {area:442} a {area:702}; los Cielonatos toman el barco desde el muelle de {area:442} y aprenden la ruta de vuelo de la Aldea Rut'theran. Luego toma el portal para subir con {npc:4217} en {area:1658}.",
		["North along the hills. {npc:3650} waits in the ruins of {quest:954}; Wild Grells and Vile Sprites fill them, Deth'ryll Satyrs the eastern edge. {quest:1001} stands by the road west of the ruins; a {quest:4723} lies on the shore on the way to him."] = "Ve al norte por las colinas. {npc:3650} espera en las ruinas de {quest:954}; están llenas de grells salvajes y duendes viles, y los sátiros Deth'ryll ocupan el borde este. {quest:1001} está junto al camino al oeste de las ruinas; un {quest:4723} yace en la orilla de camino hacia él.",
		["Plagued bears"] = "Osos apestados",
		["Rabid Thistle Bears roam the hills just east of {area:442}. Use {quest:2139} on one and lead it back to him."] = "Los osos cardo rabiosos rondan las colinas justo al este de {area:442}. Usa {quest:2139} en uno y llévalo de vuelta con él.",
		["Read the {object:17188}"] = "Lee {object:17188}",
		["Read the {object:17189}"] = "Lee {object:17189}",
		["The WANTED poster outside the inn"] = "El cartel de SE BUSCA fuera de la posada",
		["The bay wrecks"] = "Los naufragios de la bahía",
		["The beach"] = "La playa",
		["The cave and the {npc:6788}"] = "La cueva y la {npc:6788}",
		["The cave lies south of the falls: Scaber Stalks grow all through it, the {item:5270} at the very back. The {npc:6788} lairs in the hills south of the falls."] = "La cueva está al sur de las cascadas: los Boletos rudos ({item:5271}) crecen por toda ella y {item:5270}, al fondo. {npc:6788} tiene su guarida en las colinas al sur de las cascadas.",
		["The flame burns in the south of {area:447}."] = "La llama arde en el sur de {area:447}.",
		["The half pendants lie in {zone:1439} and {zone:1436}: later on the route"] = "Los medios colgantes están en {zone:1439} y {zone:1436}: más adelante en la ruta",
		["The red crystal"] = "El cristal rojo",
		["The skeletal turtle"] = "La tortuga esquelética",
		["The {object:16393}"] = "{object:16393}",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Los Reptadores de marea ({npc:2232}) corretean por la orilla bajo el pueblo; {quest:983} está en la playa, justo al sur de los muelles. Los Trilladores de Costa Oscura ({npc:2185}) nadan en los bajíos. {object:175207} yace en la orilla, justo al sur del pueblo.",
		["{item:12238}: fish from the pier"] = "{item:12238}: pesca desde el muelle",
		["{item:12349}, at the waterfall"] = "{item:12349}, en la cascada",
		["{item:12355}, in {object:177624}"] = "{item:12355}, en {object:177624}",
		["{item:15845}: at the mouth of the cave by the falls"] = "{item:15845}: en la entrada de la cueva junto a las cascadas",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, de un {object:177785} en el lago",
		["{item:5338}: Deth'ryll Satyrs"] = "{item:5338}: sátiros Deth'ryll",
		["{item:5348}: Dark Strand Fanatics"] = "{item:5348}: fanáticas de la Facción Oscura",
		["{npc:3639} stands at the north edge of the ruins. Cursed, Writhing and {npc:2178} haunt them; {npc:3667}'s ghost walks among them, {npc:270196} the owl circles east of them. The two tablets lie in the ruins; a {quest:4722} lies on the shore west of them."] = "{npc:3639} está en el borde norte de las ruinas. Altonatos malditos, Altonatos en pena y {npc:2178} las rondan; el fantasma de {npc:3667} camina entre ellos y la lechuza {npc:270196} vuela en círculos al este. Las dos tablillas están en las ruinas; {quest:4722} yace en la orilla al oeste de ellas.",
		["{npc:3644}, on the pier"] = "{npc:3644}, en el muelle",
		["{npc:3649}, north end of the village"] = "{npc:3649}, en el extremo norte del pueblo",
		["{npc:3649}: for {npc:1646} in {zone:1453}"] = "{npc:3649}: para {npc:1646} en {zone:1453}",
		["{quest:6122}: fill the sampler at {area:445}"] = "{quest:6122}: llena el muestreador en {area:445}",
} end)()
t.guides["forever/alliance/03-darkshore-return"] = (function() return {
		["Back south"] = "De vuelta al sur",
		["Back to {npc:11802}"] = "Regresa con {npc:11802}",
		["Escort her out of the glaive; Therysil takes the turn-in in {zone:1440}"] = "Escóltala fuera de la guja; la entrega se hace a Therysil en {zone:1440}",
		["Fine Moonstalker Pelts"] = "Pelambres de Acechalunas refinadas",
		["Follow the coast north-east to the {area:443}. {quest:951} lie among the ruins; Stormscale Myrmidons, Sorceresses and Warriors hold them, and Stormscale Beastmistresses walk the shore."] = "Sigue la costa al noreste hasta {area:443}. {quest:951} están entre las ruinas; las ocupan myrmidones, hechiceras y guerreros Escama Tormentosa, y las maestras de bestias Escama Tormentosa recorren la orilla.",
		["Follow the road north."] = "Sigue el camino al norte.",
		["Grizzled Scalps"] = "Cueros cabelludos grisáceos",
		["Grizzled Thistle Bears roam the hills around the Grove; {quest:1003} stands west of it among them."] = "Los osos cardo grisáceos rondan por las colinas alrededor de la Arboleda; {quest:1003} está al oeste de ella, entre ellos.",
		["Moonstalker Sires prowl the woods around the glaive. The {object:12666} sits at the bottom of the crater; {npc:3584} stands on its north side. For {quest:948}'s quest, use the {item:5251} at the bottom of the crater: it makes the {object:10076}, and you hand the quest in to the bowl."] = "Los patriarcas Acechalunas merodean por el bosque alrededor de la guja. {object:12666} está en el fondo del cráter; {npc:3584} está en su lado norte. Para la misión de {quest:948}, usa {item:5251} en el fondo del cráter: así aparece {object:10076}, y la misión se entrega al cuenco.",
		["Night Elves fly from {area:442} to {area:702}; Skyborne take the boat from the {area:442} dock and learn the Rut'theran flight path there. Take the portal up to {npc:4217} in the {area:1658}."] = "Los elfos de la noche vuelan de {area:442} a {area:702}; los Cielonatos toman el barco desde el muelle de {area:442} y aprenden allí la ruta de vuelo de la Aldea Rut'theran. Toma el portal para subir con {npc:4217} en {area:1658}.",
		["Only if a Disciple or Thug dropped {item:5352}: right-click it"] = "Solo si un discípulo o matón soltó {item:5352}: haz clic derecho en él",
		["She gives you the {item:15826}"] = "Ella te da el {item:15826}",
		["The Lunar Fungal Blooms grow in the moonkin caves in the hills just east of {area:442}; the moonkin there are irritable. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else brings it from {zone:1453} ({npc:1313}) or the Auction House."] = "Las flores de hongo lunar crecen en las cuevas de lechúcicos de las colinas justo al este de {area:442}; los lechúcicos de allí son irritables. {item:2449} requiere {skill:182}: los herboristas la recogen por todo {zone:1439}; los demás la traen de {zone:1453} ({npc:1313}) o de la casa de subastas.",
		["The WANTED poster"] = "El cartel de SE BUSCA",
		["The naga"] = "Los naga",
		["The relics of the Barrow Dens"] = "Las reliquias de los Túmulos",
		["The {area:443}"] = "{area:443}",
		["The {object:10076}"] = "{object:10076}",
		["The {object:12666}"] = "{object:12666}",
		["{item:15851} and {item:2449}"] = "{item:15851} y {item:2449}",
		["{item:15883}: the {object:177792} under the water off the north coast, west of the ruins"] = "{item:15883}: {object:177792}, bajo el agua frente a la costa norte, al oeste de las ruinas",
		["{item:279279}: Twilight Disciples and Thugs"] = "{item:279279}: discípulos y matones Crepusculares",
		["{npc:10323}'s beach"] = "La playa de {npc:10323}",
		["{npc:11802}: the welcome from Sheldras"] = "{npc:11802}: la bienvenida de Sheldras Árbol Lunar",
		["{npc:12298}: use the {item:15826} on them; they roam all of {zone:1439}"] = "{npc:12298}: usa el {item:15826} en ellos; rondan por todo {zone:1439}",
		["{npc:3616}, at the Grove"] = "{npc:3616}, en el Páramo de los Ancianos",
		["{npc:6667} hides on the little island off the ruins. The key pieces drop from Giant Foreststriders (top), Greymist murlocs (middle) and Raging Reef Crawlers (bottom)."] = "{npc:6667} se esconde en la islita frente a las ruinas. Las piezas de la llave las sueltan los zancudos del bosque gigantes (parte superior), los múrlocs Brumagris (parte central) y los reptadores de arrecife enfurecidos (parte inferior).",
		["{quest:87760}: {npc:10219} offers it once all nine beached remains are handed in"] = "{quest:87760}: {npc:10219} la ofrece cuando hayas entregado los nueve restos varados",
		["{quest:98394} (Night Elves) and the {npc:272054} (Skyborne) wait in southern {area:493}. The three relics lie in the {area:2363}, east of them. Reports from the first weeks say a relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98394} (elfos de la noche) y {npc:272054} (Cielonato) esperan en el sur de {area:493}. Las tres reliquias están en {area:2363}, al este de ellos. Según informes de las primeras semanas, una reliquia no da botín mientras otro jugador la saquea: espera un momento y vuelve a intentarlo.",
} end)()
t.guides["forever/alliance/03-loch-modan"] = (function() return {
		["Back down to the east shore below the boars' hills: {npc:270693}, a crocolisk, patrols it among the Loch Crocolisks."] = "Baja de nuevo a la orilla este, debajo de las colinas de los jabalíes: {npc:270693}, un crocolisco, la patrulla entre los crocoliscos del lago.",
		["Boat to {area:150}"] = "Barco a {area:150}",
		["Elder Mountain Boars"] = "Jabalíes monteses mayores",
		["Fly to {area:1537}"] = "Vuela a {area:1537}",
		["Fly to {zone:1453}"] = "Vuela a {zone:1453}",
		["The Elder Mountain Boars roam the hills north-west of the lodge, along the east shore. {quest:258} runs for 12 minutes: kill five and go straight back to Daryl; the crocolisks come after."] = "Los jabalíes monteses mayores recorren las colinas al noroeste del pabellón, a lo largo de la orilla este. {quest:258} dura 12 minutos: mata cinco y regresa directo con Daryl; los crocoliscos van después.",
		["Through the South Gate tunnel and west along the road to {zone:1455}. Know the {zone:1455} flight path already? Fly from {area:144} instead: these two waypoints drop once you are in the city."] = "Atraviesa el túnel de la Puerta Sur y sigue el camino al oeste hasta {zone:1455}. ¿Ya conoces la ruta de vuelo de {zone:1455}? Mejor vuela desde {area:144}: estos dos puntos de ruta desaparecen en cuanto estés en la ciudad.",
		["Use the {item:6866} on {npc:6172}"] = "Usa {item:6866} en {npc:6172}",
		["You have the {area:1537} flight path from {zone:1426}: back north to {area:144}'s gryphons, quicker than walking through the tunnel and across {zone:1426}."] = "Ya tienes la ruta de vuelo de {area:1537} desde {zone:1426}: regresa al norte a los grifos de {area:144}, es más rápido que caminar por el túnel y atravesar {zone:1426}.",
		["{area:144} flight master"] = "Maestro de vuelo de {area:144}",
		["{area:20} and the Defias hills"] = "{area:20} y las colinas Defias",
		["{item:254676}, from the crates around {area:20}"] = "{item:254676}, de las cajas alrededor de {area:20}",
		["{item:280911}: Redridge Thrashers"] = "{item:280911}: Descarnadores de Crestagrana ({npc:712})",
		["{item:6846}: Defias Rogue Wizards"] = "{item:6846}: Zahoríes bribones de Defias",
		["{npc:1343}: {npc:1416}'s package"] = "{npc:1343}: el paquete de {npc:1416}",
		["{npc:1573}, in the {object:32372}"] = "{npc:1573}, en {object:32372}",
