		["Fly to {zone:1453}"] = "Vuela a {zone:1453}",
		["For King Magni in {zone:1455}, at the end of this guide"] = "Para el rey Magni en {zone:1455}, al final de esta guía",
		["For {npc:2916} in {zone:1455}, at the end of this guide"] = "Para {npc:2916} en {zone:1455}, al final de esta guía",
		["Level 30 and 32 spells"] = "Hechizos de nivel 30 y 32",
		["Murloc heads"] = "Cabezas de múrloc",
		["Snapjaws"] = "Quijafortes",
		["Syndicate camp"] = "Campamento de la Hermandad",
		["The Snapjaw turtles bask along the river east of {area:271}, south of {area:272} (Horde)."] = "Las tortugas Quijaforte toman el sol a lo largo del río al este de {area:271}, al sur de {area:272} (Horda).",
		["The cheese shop in the {object:2096}."] = "La quesería de {object:2096}.",
		["The naga hold the shore south-east of {area:271}."] = "Los nagas ocupan la costa al sureste de {area:271}.",
		["The yetis live in the cave in the hills north of {area:271}, on the way north to the Syndicate camp.\nStay in the {area:277}: the cave further north has Mountain and Giant Yetis (32-34) in pairs and {npc:13602}, a level 36 elite."] = "Los yetis viven en la cueva de las colinas al norte de {area:271}, de camino al norte hacia el campamento de la Hermandad.\nQuédate en {area:277}: la cueva más al norte tiene Yetis monteses y Yetis gigantes (32-34) en parejas y a {npc:13602}, un élite de nivel 36.",
		["Torn Fin murlocs"] = "Múrlocs Rompeanca",
		["West along the road to Menethil."] = "Al oeste por el camino hasta Menethil.",
		["Yeti cave"] = "Cueva de los yetis",
		["{item:3713}, from {npc:2381}"] = "{item:3713}, de {npc:2381}",
		["{npc:2366}, in the inn: for {area:35} (04-stranglethorn-vale)"] = "{npc:2366}, en la posada: para {area:35} (04-stranglethorn-vale)",
		["{npc:2382}: the lions come later"] = "{npc:2382}: los leones vienen después",
		["{npc:2695}: for King Magni, on the same {zone:1455} stop"] = "{npc:2695}: para el rey Magni, en la misma parada de {zone:1455}",
		["{npc:2711}: his trail leads to Arathi"] = "{npc:2711}: su rastro lleva a Tierras Altas de Arathi",
		["{npc:2784}, the {object:171709}"] = "{npc:2784}, {object:171709}",
		["{npc:4961} waits in the Pig and Whistle tavern in {object:2100}; he and his two thugs fight you, but stop once beaten."] = "{npc:4961} espera en la taberna El Cerdo Borracho, en {object:2100}; él y sus dos matones pelean contigo, pero se detienen al ser derrotados.",
		["{npc:5479} trains warriors in {object:2100}, beside the Pig and Whistle. {npc:6236} waits on {area:720} in the {zone:1413}, on the way to {area:392} much later (40-50/01)."] = "{npc:5479} instruye a los guerreros en {object:2100}, junto a El Cerdo Borracho. {npc:6236} espera en {area:720}, en {zone:1413}, de camino a {area:392} mucho más tarde (40-50/01).",
		["{object:671518}: for {npc:2104}"] = "{object:671518}: para {npc:2104}",
} end)()
t.guides["forever/alliance/30-40/02-desolace"] = (function() return {
		["Escort {npc:5644}"] = "Escolta a {npc:5644}",
		["Follow the road west past {area:460} (Horde) and south-west through the {area:465} into {zone:1443}; {area:608} stands at the top of the pass."] = "Sigue el camino hacia el oeste pasando por {area:460} (Horda) y hacia el suroeste por {area:465} hasta {zone:1443}; {area:608} está en lo alto del paso.",
		["For {npc:5638}, at the end of this guide"] = "Para {npc:5638}, al final de esta guía",
		["Lead {npc:5644} out of the fortress; she walks off once you are clear of it. {npc:5642} takes the turn-in at {area:608} at the end of the guide."] = "Saca a {npc:5644} de la fortaleza; se va por su cuenta una vez fuera. {npc:5642} recibe la entrega en {area:608} al final de la guía.",
		["Malem chest"] = "Cofre de los Malem",
		["Out of Thunder Axe Fortress"] = "Fuera de la Fortaleza del Hacha de Trueno",
		["The Kolkar roam the plains around {area:609}; their ears are for {npc:5752}."] = "Los Kolkar recorren las llanuras alrededor de {area:609}; sus orejas son para {npc:5752}.",
		["The chest lies in the ruins south-west of {area:608}."] = "El cofre está en las ruinas al suroeste de {area:608}.",
		["The wrecked ship lies just south-west of {npc:11863}'s tower; its chest sits beside {object:177787}."] = "El barco naufragado está justo al suroeste de la torre de {npc:11863}; su cofre está junto a {object:177787}.",
		["{npc:11596}'s camp is on the road south of {area:609}, by the {area:596}."] = "El campamento de {npc:11596} está en el camino al sur de {area:609}, junto a {area:596}.",
		["{npc:11863}'s tower stands on the hill west of {area:599}: take his quest first, the sceptre he wants is in the fortress."] = "La torre de {npc:11863} está en la colina al oeste de {area:599}: acepta primero su misión; el cetro que quiere está en la fortaleza.",
		["{npc:5396}, beside {npc:5752}"] = "{npc:5396}, junto a {npc:5752}",
		["{npc:5638}: the satchel lies off the north-west coast, on the south loop at the end of 30-40 (06-badlands): keep it"] = "{npc:5638}: la mochila está frente a la costa noroeste, en el circuito sur al final de 30-40 (06-badlands): consérvala",
		["{npc:5638}: the wreck's chest lies below {npc:11863}'s tower, on the way to {area:599}"] = "{npc:5638}: el cofre del naufragio está debajo de la torre de {npc:11863}, de camino a {area:599}",
		["{npc:5643} and the Seer"] = "{npc:5643} y el vidente",
		["{npc:5644} hides inside the Burning Blade's fortress south-west of {area:608}."] = "{npc:5644} se esconde dentro de la fortaleza del Filo Ardiente, al suroeste de {area:608}.",
} end)()
t.guides["forever/alliance/30-40/03-ashenvale"] = (function() return {
		["Boat to {area:150}"] = "Barco a {area:150}",
		["East through the canyons. {area:484}, a Horde camp with guards, sits on the mesa here: keep to the canyon floor and give the foot of its lifts a wide berth."] = "Al este por los cañones. {area:484}, un campamento de la Horda con guardias, está sobre la meseta: quédate en el fondo del cañón y mantente bien lejos de la base de sus elevadores.",
		["Fly to Theramore"] = "Vuela a Isla Theramore",
		["Follow the canyons east to the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "Sigue los cañones al este hasta El Desierto de Sal. Los goblins y gnomos de {area:2240} son neutrales y dan misiones a ambas facciones.",
		["For {quest:1132} in Theramore's inn, where this guide's boat goes"] = "Para {quest:1132} en la posada de Theramore, adonde va el barco de esta guía",
		["For {quest:5762} in Stranglethorn, later"] = "Para {quest:5762} en Tuercespina, más adelante",
		["On the road south through the {zone:1413}, {npc:6244} camps east of the road, north-east of {area:378}; come in from the east and keep clear of the Horde guards."] = "En el camino al sur por {zone:1413}, {npc:6244} acampa al este del camino, al noreste de {area:378}; llega desde el este y mantente lejos de los guardias de la Horda.",
		["The Bluegill murlocs on the beach south-west of Menethil carry the ingots."] = "Los múrlocs Branquiazul de la playa al suroeste de Menethil llevan los lingotes.",
		["The flight master stands by the gate of {area:514}; {npc:5083} and {npc:4964} are inside the citadel."] = "El maestro de vuelo está junto a la puerta de {area:514}; {npc:5083} y {npc:4964} están dentro de la ciudadela.",
		["The wreck of the Flying Osprey lies in the shallows south of the keep."] = "El naufragio del Flying Osprey está en los bajíos al sur del Castillo de Menethil.",
		["Theramore"] = "Theramore",
		["{npc:1217} stands in the {area:2104}, south of the keep, where {npc:4963} and {npc:5082} wait too."] = "{npc:1217} está en {area:2104}, al sur del castillo, donde también esperan {npc:4963} y {npc:5082}.",
		["{npc:4455} stands by {area:2103}'s door, just north of the flight master."] = "{npc:4455} está junto a la puerta de {area:2103}, justo al norte del maestro de vuelo.",
		["{quest:1132}, inside the inn in the north of town"] = "{quest:1132}, dentro de la posada en el norte del pueblo",
		["{quest:1738}: in {zone:1440}, on the way to {zone:1443}"] = "{quest:1738}: en {zone:1440}, de camino a {zone:1443}",
		["{quest:65602}: the incubus, beside the succubus; the {item:190309} is near the {quest:1738}"] = "{quest:65602}: el íncubo, junto a la súcubo; {item:190309} está cerca de {quest:1738}",
} end)()
t.guides["forever/alliance/30-40/04-stranglethorn-vale"] = (function() return {
		["Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west."] = "De vuelta al sur pasando a Nesingwary: las panteras y los raptores de Tuercespina corren por los claros al oeste del campamento hacia la costa; los tigres mayores ocupan las colinas del suroeste.",
		["Both roam the grass around the camp and along the road north."] = "Ambos deambulan por la hierba alrededor del campamento y a lo largo del camino al norte.",
		["Down to {area:35}"] = "Baja a {area:35}",
		["Druid training"] = "Entrenamiento de druida",
		["Fly to {area:42}"] = "Vuela a {area:42}",
		["Fly to {zone:1453}"] = "Vuela a {zone:1453}",
		["Follow the main road south the length of the jungle, past the {object:3202} turn-off, to {area:35} on the southern cape."] = "Sigue el camino principal al sur a lo largo de toda la jungla, pasando el desvío a {object:3202}, hasta {area:35}, en el cabo sur.",
		["From {zone:1431} take the road south into Stranglethorn; the hunters' tents stand just west of the road past the {area:99} turn-off."] = "Desde {zone:1431} toma el camino al sur hacia Tuercespina; las tiendas de los cazadores están justo al oeste del camino, pasado el desvío a {area:99}.",
		["Gluggle, a rare murloc on the coast west of camp, drops the {item:4614}: take it if you meet him"] = "Gluggle, un múrloc raro en la costa al oeste del campamento, suelta {item:4614}: tómalo si te lo encuentras",
		["Panthers, raptors and elder tigers"] = "Panteras, raptores y tigres mayores",
		["River Crocolisks swim the river by the {area:99}."] = "Los crocoliscos fluviales nadan en el río junto a {area:99}.",
		["River crocolisks"] = "Crocoliscos fluviales",
		["Stranglethorn Tigers"] = "Tigres de Tuercespina",
		["Take the road north; the camp sits in the hills to the west.\n{npc:738} offers {quest:215} only while he is out of the camp: about every half hour he walks down the path to the road, where two Kurzen's Agents ambush him. Help him kill them and take the quest at once, before he walks back up. He isn't there? Leave it: the guide passes {quest:200}, which follows from it, as well."] = "Toma el camino al norte; el campamento está en las colinas al oeste.\n{npc:738} solo ofrece {quest:215} mientras está fuera del campamento: más o menos cada media hora baja por el sendero hasta el camino, donde dos Agentes de Kurzen le tienden una emboscada. Ayúdalo a matarlos y toma la misión de inmediato, antes de que vuelva a subir. ¿No está? Déjala: la guía también omite {quest:200}, que viene de ella.",
		["The adult tigers prowl the hills just south and west of the camp."] = "Los tigres adultos merodean por las colinas justo al sur y al oeste del campamento.",
		["The elder tigers come later, on the way back from the {area:99}"] = "Los tigres mayores vienen después, al regresar de {area:99}",
		["The haunted island"] = "La isla embrujada",
		["Young tigers and panthers"] = "Tigres jóvenes y panteras",
		["{item:190309}, north of {area:413}"] = "{item:190309}, al norte de {area:413}",
		["{item:2634}, from a {object:263} crate"] = "{item:2634}, de una caja de {object:263}",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, en el piso de arriba de la taberna",
		["{npc:469}, in the hut"] = "{npc:469}, en la cabaña",
		["{npc:715}, from {zone:1441}"] = "{npc:715}, de {zone:1441}",
		["{npc:716} collects the {item:2755}: the pages drop from almost every humanoid in the jungle. Turn the pages into chapters as you go."] = "{npc:716} colecciona {item:2755}: las páginas las sueltan casi todos los humanoides de la jungla. Convierte las páginas en capítulos sobre la marcha.",
		["{npc:729} and the Lashtail raptors"] = "{npc:729} y los raptores colazote",
		["{npc:729}, the great tiger, lairs on the hilltop south-west of the camp; Lashtail Raptors run south of it, along the way to {area:35}."] = "{npc:729}, el gran tigre, tiene su guarida en la cima de la colina al suroeste del campamento; los raptores colazote corren al sur de ella, por el camino a {area:35}.",
		["{npc:737}, in the tavern"] = "{npc:737}, en la taberna",
		["{npc:738}, at the foot of the path"] = "{npc:738}, al pie del sendero",
		["{quest:201}: just look around the hunters' camp"] = "{quest:201}: solo echa un vistazo al campamento de los cazadores",
} end)()
t.guides["forever/alliance/30-40/04b-stranglethorn-vale"] = (function() return {
		["East to the {area:99}, on the way back to Nesingwary's camp."] = "Al este hacia el {area:99}, de camino de vuelta al campamento de Nesingwary.",
		["East to {area:101}: Herod's records lie in a hut on its west side."] = "Al este hacia {area:101}: los registros de Herod están en una choza en su lado oeste.",
		["Fly to {area:42}"] = "Vuela a {area:42}",
		["For Archmage Ansirem in {zone:1416}"] = "Para el archimago Ansirem en {zone:1416}",
		["For characters of 35 to 36, but several quests here are level 37-41: on purpose, for their experience. {quest:205}'s Skullsplitter trolls are 39-42, so pull them one at a time."] = "Para personajes de nivel 35 a 36, pero varias misiones de aquí son de nivel 37-41: a propósito, por su experiencia. Los trols Machacacráneos de {quest:205} son de nivel 39-42, así que atráelos de uno en uno.",
		["North along the coast to the ruins on the hill: the last two tablets lie there. Pick up Green Hills pages as they drop."] = "Al norte por la costa hasta las ruinas de la colina: allí están las dos últimas tablillas. Recoge las páginas de Colinas Verdes cuando caigan.",
		["Skullsplitter trolls"] = "Trols Machacacráneos",
		["Snapjaw Crocolisks"] = "Crocoliscos Quijaforte",
		["South from the compound to {area:37}: the Venture Co. Geologists in the camps on its shore carry the Tumbled Crystals, and the Shadowmaw Panthers prowl stealthed in the jungle south and east of it."] = "Al sur del recinto hacia el {area:37}: los geólogos de Ventura y Cía. en los campamentos de su orilla llevan los cristales caídos, y las panteras Faucesombría merodean en sigilo por la jungla al sur y al este del lago.",
		["The Skullsplitter trolls hold the ruins east of the road between Nesingwary and {object:3202}."] = "Los trols Machacacráneos ocupan las ruinas al este del camino entre Nesingwary y {object:3202}.",
		["The haunted island lies just off the shore west of the second tablet: the Lesser Water Elementals rise from the water around it."] = "La isla embrujada está justo frente a la costa, al oeste de la segunda tablilla: los elementales de agua menores surgen del agua a su alrededor.",
		["The jungle ruins"] = "Las ruinas de la jungla",
		["The {area:102}"] = "Las {area:102}",
		["West across the jungle to the troll ruins: each holds one stone tablet of the troll legends, the first two in the ruins south-west of Nesingwary's camp, the last two on the hill in the north-west."] = "Al oeste a través de la jungla hacia las ruinas trol: cada una guarda una tablilla de piedra de las leyendas trol; las dos primeras en las ruinas al suroeste del campamento de Nesingwary, las dos últimas en la colina del noroeste.",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, en el piso de arriba de la taberna",
		["{npc:718}: the Shadowmaw Panthers prowl around {area:37}, after {area:101}"] = "{npc:718}: las panteras Faucesombría merodean alrededor del {area:37}, después de {area:101}",
		["{npc:770}: for {npc:773} in {area:35}"] = "{npc:770}: para {npc:773} en {area:35}",
		["{npc:773}, upstairs: this optional quest needs four {item:4278}. Mine Lesser Bloodstone Deposits in {zone:1417} with {skill:186} 75, or buy the ore at the Auction House or ask a miner friend. The kobolds do not drop it; skip this quest if you cannot get the ore."] = "{npc:773}, en el piso de arriba: esta misión opcional pide cuatro {item:4278}. Extrae de depósitos de sangrita inferior en {zone:1417} con {skill:186} 75, o compra el mineral en la casa de subastas o pídeselo a un amigo minero. Los kóbolds no lo sueltan; omite esta misión si no puedes conseguir el mineral.",
} end)()
t.guides["forever/alliance/30-40/05-arathi-highlands"] = (function() return {
		["A {npc:2434} lurks stealthed on the edge of {area:271}, and few players find him. If you spot him, kill him and read the contract he carries: {npc:2276} takes it. Don't wait for him: the rest of this step doesn't need him."] = "Un {npc:2434} acecha en sigilo en las afueras de {area:271}, y pocos jugadores lo encuentran. Si lo ves, mátalo y lee el contrato que lleva: se lo queda {npc:2276}. No lo esperes: el resto de este paso no lo necesita.",
		["Back west through {zone:1430} to {area:42}."] = "De vuelta al oeste por {zone:1430} hasta {area:42}.",
		["Below ground"] = "Bajo tierra",
		["Crushridge ogres"] = "Ogros Aplastacresta",
		["East along the road to the {area:76}. {npc:256028} mobs drop the crystals. {quest:1392} walks a long path through the ruins: if you meet him, kill him, his cudgel starts a quest for {npc:1776}. Don't wait for him."] = "Al este por el camino hasta {area:76}. Los enemigos {npc:256028} sueltan los cristales. {quest:1392} recorre un largo camino por las ruinas: si te lo encuentras, mátalo; su garrote inicia una misión para {npc:1776}. No lo esperes.",
		["East from {quest:681} across the north of the Highlands; the shards glitter on the hill by the {area:333}, north of {area:314}."] = "Al este desde {quest:681}, por el norte de las Tierras Altas; los fragmentos brillan en la colina junto a {area:333}, al norte de {area:314}.",
		["Fly to {area:271}"] = "Vuela a {area:271}",
		["Fly to {area:42}"] = "Vuela a {area:42}",
		["Fly to {zone:1453}"] = "Vuela a {zone:1453}",
		["Follow the road east out of {area:287} over {area:1057} to {area:320}."] = "Sigue el camino al este, saliendo de {area:287}, por {area:1057} hasta {area:320}.",
		["Follow the road north out of {area:271} into the mountains. Mountain lions roam the slopes; the Syndicate in {area:280} wear the signet rings. {npc:2306} (40) turns up in one spot at a time: the cellar of {area:280}'s inn, or one of the Syndicate tent camps in the uplands north and north-west of the village."] = "Sigue el camino al norte, saliendo de {area:271}, hacia las montañas. Los leones de montaña rondan las laderas; la Hermandad de {area:280} lleva los anillos de sello. {npc:2306} (40) aparece en un solo lugar a la vez: el sótano de la posada de {area:280}, o uno de los campamentos de tiendas de la Hermandad en las tierras altas al norte y noroeste del pueblo.",
		["Follow the road north to the draenei of the {area:657}."] = "Sigue el camino al norte hasta los draenei de {area:657}.",
		["For {npc:1440} in {zone:1453}: keep it"] = "Para {npc:1440} en {zone:1453}: guárdalo",
		["For {npc:2487} in {area:35}: keep it"] = "Para {npc:2487} en {area:35}: guárdalo",
		["For {npc:2542} in {area:35}: keep it"] = "Para {npc:2542} en {area:35}: guárdalo",
		["For {npc:2711} in {area:271}"] = "Para {npc:2711} en {area:271}",
		["From {zone:1455} take the tunnel east through {zone:1426} into {zone:1432} and follow the road to {area:144}."] = "Desde {zone:1455} toma el túnel al este por {zone:1426} hasta {zone:1432} y sigue el camino hasta {area:144}.",
		["North-west out of the Witherbark valley; {npc:2712} and {npc:2713} camp in the hills just north of {area:314}."] = "Al noroeste, saliendo del valle Secacorteza; {npc:2712} y {npc:2713} acampan en las colinas justo al norte de {area:314}.",
		["Only if Gluggle gave you the pendant in Stranglethorn"] = "Solo si Gluggle te dio el colgante en Tuercespina",
		["Phizzlethorpe"] = "Fiseltor",
		["South from the {object:2691}, past {area:314}, to {area:317} in the hills: the Witch Doctors stand among the huts and the Shadow Hunters guard the far end of the valley. Every troll can drop a tusk."] = "Al sur desde {object:2691}, pasando {area:314}, hasta {area:317} en las colinas: los Médicos brujos están entre las chozas y los Cazadores de las Sombras vigilan el fondo del valle. Cualquier trol puede soltar un colmillo.",
		["South-east along the loch to the dig site."] = "Al sureste por la orilla del lago hasta la excavación.",
		["South-west to the Kirin Tor camp on the lake shore west of {area:279}, just over the border into {zone:1421}: the {npc:269127} stands there. Archmage Ansirem stands south-east of it, by the dome."] = "Al suroeste hasta el campamento del Kirin Tor en la orilla del lago al oeste de {area:279}, justo al cruzar la frontera de {zone:1421}: ahí está {npc:269127}. El archimago Ansirem está al sureste, junto a la cúpula.",
		["The Drywhisker kobolds dig in the gorge east of {area:321} (Horde); skirt the town to the north. They drop the Motes of Myzrael, not Krazek's ore. Lesser Bloodstone Deposits need {skill:186} 75: mine four ore, buy them at the Auction House, or ask a miner friend. The ore goal is optional; continue with Myzrael if you cannot get it. Careful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them."] = "Los kóbolds Mostacho Seco excavan en el desfiladero al este de {area:321} (Horda); rodea el pueblo por el norte. Sueltan las Motas de Myzrael, no el mineral de Krazek. Los depósitos de sangrita inferior requieren {skill:186} 75: extrae cuatro de mineral, cómpralos en la casa de subastas o pídeselos a un amigo minero. El objetivo del mineral es opcional; sigue con Myzrael si no puedes conseguirlo. Cuidado: todos los tipos de kóbold huyen en busca de ayuda cuando tienen poca salud (los kóbolds al 30%, los peritos y los cavadores al 15%), lo que puede atraer a más.",
		["The courier walks the road from {area:314} west across the Highlands, as far as about 24,45, and back, with two guards: the arrow follows the road west until you meet him. Pull them off the road."] = "El mensajero recorre el camino desde {area:314} hacia el oeste a través de las Tierras Altas, hasta aproximadamente 24,45, y de regreso, con dos guardias: la flecha sigue el camino al oeste hasta que lo encuentres. Atráelos fuera del camino.",
		["The shards lie at the far end of {area:318}."] = "Los fragmentos están al fondo de {area:318}.",
		["The two wrecks lie in the bay west of the cove. The charts and logs are inside them; the gems lie on the sea floor around them. Daggerspine naga swim the whole bay."] = "Los dos naufragios están en la bahía al oeste de la cala. Las cartas y los diarios están dentro; las gemas están en el fondo del mar a su alrededor. Los naga Espinadaga nadan por toda la bahía.",
		["The western swamp"] = "El pantano del oeste",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2417} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:2417} walks from the arrow north-east through the ruins to about 40,47 and back: if he isn't at the arrow, follow his path."] = "Estos son enemigos élite: se recomienda agruparse, busca gente con quien hacerlo. {npc:2417} es un élite de nivel 40: la mayoría de las clases lo derrotan en solitario a nivel 42, pero quizá necesites ayuda. Sáltalo si vas solo: la ruta te hace recuperar la experiencia matando enemigos.\n{npc:2417} camina desde la flecha al noreste a través de las ruinas hasta aproximadamente 40,47 y de regreso: si no está en la flecha, sigue su recorrido.",
		["Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road."] = "Crocoliscos jóvenes, Hilapenas ({npc:858}) y Jaguares del pantano ({npc:767}) recorren el pantano alrededor del camino.",
		["from {quest:1392}: he walks a path through the ruins"] = "de {quest:1392}: recorre un camino por las ruinas",
		["{item:3658}: Crushridge ogres"] = "{item:3658}: ogros Aplastacresta",
		["{npc:1141}, {area:17203} road"] = "{npc:1141}, camino de {area:17203}",
		["{npc:12336}, Cathedral of Light"] = "{npc:12336}, en la catedral",
		["{npc:1440}, the Royal Library in the keep"] = "{npc:1440}, la biblioteca real del castillo",
		["{npc:185335}, at the same circle"] = "{npc:185335}, en el mismo círculo",
		["{npc:217412}: three critters to catch in Arathi, {zone:1443} and Stranglethorn"] = "{npc:217412}: tres alimañas que atrapar en Arathi, {zone:1443} y Tuercespina",
		["{npc:2434}, if you spot him"] = "{npc:2434}, si lo ves",
		["{npc:2712} and {npc:2713}"] = "{npc:2712} y {npc:2713}",
		["{npc:2713}'s errand"] = "El encargo de {npc:2713}",
		["{npc:5391} is caged at the north end of the sanctuary. Free him and keep him alive on the walk out; his strongbox waits by the road afterwards."] = "{npc:5391} está enjaulado en el extremo norte del santuario. Libéralo y mantenlo con vida durante la salida; después, su caja fuerte espera junto al camino.",
		["{npc:6122} binds the incubus to you"] = "{npc:6122} vincula al íncubo contigo",
		["{npc:6122} waits in the {object:2164}'s cellar, in the {object:2101}. Use the {item:6913} at the summoning circle there and defeat the succubus it calls. If you took {quest:65602}, hand him the {item:190309} too, place it at the same circle and defeat the incubus."] = "{npc:6122} espera en el sótano de {object:2164}, en {object:2101}. Usa el {item:6913} en el círculo de invocación de allí y derrota a la súcubo que aparece. Si aceptaste {quest:65602}, dale también la {item:190309}, colócala en el mismo círculo y derrota al íncubo.",
		["{quest:65602}, if you took it"] = "{quest:65602}, si la aceptaste",
} end)()
t.guides["forever/alliance/30-40/06-badlands"] = (function() return {
		["A {npc:217590} crawls about the {area:596}: catch one with the tool from {npc:217412}'s Entomology Starter Kit."] = "Un {npc:217590} se arrastra por {area:596}: atrapa uno con la herramienta del Entomology Starter Kit de {npc:217412}.",
		["Fly to Theramore"] = "Vuela a Isla Theramore",
		["Follow the road north to {area:608}: {npc:5396} stands at its south end, {npc:5638} in the middle, {npc:1182} to the north."] = "Sigue el camino hacia el norte hasta {area:608}: {npc:5396} está en el extremo sur, {npc:5638} en el centro y {npc:1182} al norte.",
		["Follow the road south to {area:2407}."] = "Sigue el camino hacia el sur hasta {area:2407}.",
		["Follow the road west across the north of {zone:1443} to the ruins of {area:2405}. {npc:11863}'s tower stands on the hill there, on the way to the wreck."] = "Sigue el camino hacia el oeste por el norte de {zone:1443} hasta las ruinas de {area:2405}. La torre de {npc:11863} está en la colina de ahí, de camino al naufragio.",
		["Lesser Rock Elementals"] = "Elementales de roca inferiores",
		["Maraudine centaurs"] = "Centauros Maraudine",
		["Rackmore's chest lies just south-east of the {object:177673}."] = "El cofre de Rackmore está justo al sureste de {object:177673}.",
		["Rock Elementals"] = "Elementales de roca",
		["Ryedol's next errand goes into {area:1517}: skip it."] = "El siguiente encargo de Ryedol es en {area:1517}: omítelo.",
		["The Maraudine centaurs hold the {area:607} west of the graveyard; every kind drops the totems."] = "Los centauros Maraudine ocupan {area:607}, al oeste del cementerio; todos sueltan los tótems.",
		["The Rock Elementals roam south-east of {npc:2921}; Giant Buzzards and Elder Crag Coyotes share the plain to their west."] = "Los Elementales de roca ({npc:92}) recorren el sureste de {npc:2921}; {npc:2831} y {npc:2729} comparten la llanura al oeste.",
		["The Shadowforge dwarves camp just north of the digsite; the crumpled map lies among their tents. Tunnelers and Darkweavers carry Ryedol's pick. Crag Coyotes roam the slopes around it."] = "Los enanos Forjatiniebla acampan justo al norte de la excavación; el mapa arrugado está entre sus tiendas. Los Tuneladores y los Tejeoscuros llevan el pico de Ryedol. Los Coyotes del risco recorren las laderas de alrededor.",
		["The Slitherblade naga hold the north-west coast north of {npc:11863}'s tower; Karnitol's satchel lies on the sea floor off it, and any naga can drop Rackmore's golden key. Swim out to {area:2406} off the far northern tip and use the {item:15766} on the {object:177673}: {npc:12369} (38) rises; kill him for the {quest:6027}."] = "Los nagas Filozante ocupan la costa noroeste, al norte de la torre de {npc:11863}; la cartera de Karnitol está en el fondo del mar frente a ella, y cualquier naga puede soltar la llave dorada de Rackmore. Nada hasta {area:2406}, frente a la punta más al norte, y usa {item:15766} en {object:177673}: surge {npc:12369} (38); mátalo para {quest:6027}.",
		["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "El esqueleto maltrecho está justo al este de los ogros, en el borde del campamento de troggs Grutacanto; los Cascahuesos y los chamanes de alrededor sueltan las escamas. Theldurin está sentado junto al campamento en ruinas, más al sur.",
		["The clams lie on Stranglethorn's north-west coast, in the next guide: keep it"] = "Las almejas están en la costa noroeste de Vega de Tuercespina, en la siguiente guía: guárdala",
		["The excavation crate"] = "La caja de la excavación",
		["The next guide starts in Theramore."] = "La siguiente guía empieza en Isla Theramore.",
		["The wrecked ship's chest lies just south-west of {npc:11863}'s tower."] = "El cofre del barco naufragado está justo al suroeste de la torre de {npc:11863}.",
		["The {area:2657}"] = "{area:2657}",
		["The {object:126260}"] = "{object:126260}",
		["To {area:2101}"] = "A {area:2101}",
		["Undead Ravagers roam the bone fields south of the Magram village, east of the Coven; at the far south-east, use the {item:15848} to draw the Magrami Spectres."] = "Los Devastadores no-muertos recorren los campos de huesos al sur de la aldea Magram, al este del Aquelarre; en el extremo sureste, usa {item:15848} para atraer a los Espectros Magrami.",
		["escort {npc:12277} back toward the graveyard"] = "escolta a {npc:12277} de vuelta hacia el cementerio",
		["for {npc:2786} in {zone:1455}: keep it"] = "para {npc:2786} en {zone:1455}: guárdala",
		["for {npc:3980} in {area:271}: keep it"] = "para {npc:3980} en {area:271}: guárdala",
		["for {npc:5637} in {zone:1455}: keep it"] = "para {npc:5637} en {zone:1455}: guárdala",
		["{area:144} flight master"] = "Maestro de vuelo de {area:144}",
		["{item:15766}, on the {object:177673}"] = "{item:15766}, en {object:177673}",
		["{item:15881}, from the Slitherblade naga"] = "{item:15881}, de los nagas Filozante",
		["{npc:2920}, beside {npc:2921}"] = "{npc:2920}, junto a {npc:2921}",
		["{npc:4618} and {npc:2817} camp together in the {area:1877}, in the middle of the {zone:1418}."] = "{npc:4618} y {npc:2817} acampan juntos en {area:1877}, en el centro de {zone:1418}.",
		["{npc:5638}, if 30-40/02 didn't take it: the wreck lies below {npc:11863}'s tower"] = "{npc:5638}, si 30-40/02 no la aceptó: el naufragio está debajo de la torre de {npc:11863}",
		["{npc:6019} stands at the edge of the {area:596}, south-west of {area:2407}; {object:176751} lie among the skeletons."] = "{npc:6019} está en el borde de {area:596}, al suroeste de {area:2407}; {object:176751} están entre los esqueletos.",
		["{object:177787} lies beside {object:35251}. His silver key drops from the Drysnap crabs around the wreck; the golden one comes from the Slitherblade naga on the north-west coast, next."] = "{object:177787} está junto a {object:35251}. Su llave de plata la sueltan los cangrejos Quebrantaseco alrededor del naufragio; la dorada viene de los nagas Filozante de la costa noroeste, a continuación.",
} end)()
t.guides["forever/alliance/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Stinky\" Ignatz"] = "\"Apestoso\" Ignatz",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4732} teaches Humans at {area:88} in eastern {zone:1429}, beside {npc:384}'s horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "A nivel 40 y con 100 de oro puedes aprender a montar, y al aprenderlo recibes una montura. {npc:4732} enseña a los humanos en {area:88}, en el este de {zone:1429}, junto a los caballos de {npc:384}. Forever podría dejar que cualquier raza aprenda con cualquier instructor de equitación (sin confirmar). Coleccionables, Monturas · Nivel 40 muestra todos los colores.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4753} teaches Night Elves in {zone:1457}, beside {npc:4730}'s sabers: the boat from {area:17203} to {area:442}, then the flight to {area:702}. Forever may let any race learn from any riding trainer (unconfirmed), such as {npc:4732} at {area:88} in {zone:1429}. Collectibles, Mounts · Level 40 lists every colour."] = "A nivel 40 y con 100 de oro puedes aprender a montar, y al aprenderlo recibes una montura. {npc:4753} enseña a los elfos de la noche en {zone:1457}, junto a los sables de {npc:4730}: el barco de {area:17203} a {area:442} y luego el vuelo a {area:702}. Forever podría dejar que cualquier raza aprenda con cualquier instructor de equitación (sin confirmar), como {npc:4732} en {area:88}, en {zone:1429}. Coleccionables, Monturas · Nivel 40 muestra todos los colores.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4772} teaches Dwarves at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}'s rams. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "A nivel 40 y con 100 de oro puedes aprender a montar, y al aprenderlo recibes una montura. {npc:4772} enseña a los enanos en {area:803}, al este de {area:131}, en el camino a {zone:1432}, junto a los carneros de {npc:1261}. Forever podría dejar que cualquier raza aprenda con cualquier instructor de equitación (sin confirmar). Coleccionables, Monturas · Nivel 40 muestra todos los colores.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:7954} teaches Gnomes at {area:189}, just east of {area:131}, beside {npc:7955}'s mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "A nivel 40 y con 100 de oro puedes aprender a montar, y al aprenderlo recibes una montura. {npc:7954} enseña a los gnomos en {area:189}, justo al este de {area:131}, junto a los mecazancudos de {npc:7955}. Forever podría dejar que cualquier raza aprenda con cualquier instructor de equitación (sin confirmar). Coleccionables, Monturas · Nivel 40 muestra todos los colores.",
		["Bloodsail camp"] = "Campamento Velasangre",
		["Boat to {area:150}"] = "Barco a {area:150}",
		["Boat to {area:35}"] = "Barco a {area:35}",
		["Cortello's scroll"] = "El pergamino de Cortello",
		["Defeat the challengers and {npc:6238}"] = "Derrota a los retadores y a {npc:6238}",
		["Every Bloodsail drops Snuff and one of them carries {npc:2493}'s eye; the Swashbucklers walk the shore just north of town. The charts and orders lie in the pirate camp on the {area:43}, south of {area:35}."] = "Todos los Velasangre sueltan tabaco rapé y uno de ellos lleva el ojo de {npc:2493}; los espadachines recorren la orilla justo al norte del pueblo. Las cartas y las órdenes están en el campamento pirata de {area:43}, al sur de {area:35}.",
		["Every Zanzil follower can drop the mixture; {npc:2537} walks the south of the camp."] = "Cualquier seguidor de Zanzil puede soltar la mezcla; {npc:2537} recorre el sur del campamento.",
		["Fly to {area:35}"] = "Vuela a {area:35}",
		["Fly to {area:42}"] = "Vuela a {area:42}",
		["Fly to {zone:1453}"] = "Vuela a {zone:1453}",
		["Follow the road east back to Theramore. The officers are in {area:514}."] = "Sigue el camino al este de vuelta a Theramore. Los oficiales están en {area:514}.",
		["Follow the road north-west out of Theramore to the watchtower at {area:503}. Mudrock Burrowers roam the marsh around it.\n{npc:4967} waits at the foot of the tower: once you have looked around, hand the quest in to him there, not in Theramore."] = "Sigue el camino al noroeste desde Theramore hasta la atalaya de {area:503}. Los hurgadores Fangorroca deambulan por el pantano a su alrededor.\n{npc:4967} espera al pie de la torre: cuando hayas echado un vistazo, entrégale la misión ahí mismo, no en Theramore.",
		["Gorilla hills"] = "Colinas de los gorilas",
		["Hand in the fangs and stay: three waves of gorillas come, {npc:1514} last. Fight at full health."] = "Entrega los colmillos y quédate: llegan tres oleadas de gorilas, {npc:1514} al final. Pelea con la salud completa.",
		["Jungle Stalkers"] = "Acechadores de la selva",
		["Leave town by the tunnel and follow the coast north; the letter lies in the Bloodsail camp on the beach, where \"Pretty Boy\" Duncan walks."] = "Sal del pueblo por el túnel y sigue la costa al norte; la carta está en el campamento Velasangre de la playa, donde camina \"El Guapo\" Duncan.",
		["MacKinley's next task sends you after elite ogres: skip it."] = "La siguiente tarea de MacKinley te envía tras ogros élite: omítela.",
		["Mirefin murlocs"] = "Múrlocs Ancalodo",
		["Naga Explorers"] = "Expedicionarios naga",
		["On the ride north to {area:392}, {area:720} lies off the {area:391} south of the town: wade over the sand bar shallows. {npc:6236} sends four challengers and then {npc:6238} (level 33) at you, one at a time."] = "De camino al norte a {area:392}, {area:720} está frente a {area:391}, al sur del pueblo: cruza vadeando los bajíos del banco de arena. {npc:6236} te envía cuatro retadores y luego a {npc:6238} (nivel 33), de uno en uno.",
		["Optional: Cortello's scroll lies inside one of the three Bloodsail ships anchored off the coast just south of {area:35}, on a middle or lower deck, and is not always on the same ship. Their crews are 42-45 pirates: clear your way from the edge, one at a time, and leave the captains (45-48), whom the route comes back for at 48."] = "Opcional: el pergamino de Cortello está dentro de uno de los tres barcos Velasangre anclados frente a la costa, justo al sur de {area:35}, en una cubierta media o inferior, y no siempre en el mismo barco. Sus tripulaciones son piratas de nivel 42-45: ábrete paso desde el borde, uno a uno, y deja a los capitanes (45-48), a quienes la ruta vuelve a buscar a nivel 48.",
		["Paladin: {quest:1661}"] = "Paladín: {quest:1661}",
		["Ride back down to town; Shaky stands at the tunnel mouth."] = "Cabalga de vuelta al pueblo; el Trémulo está en la boca del túnel.",
		["Ride east; the Tangled Horrors along the way also drop the essays. Search the edge of the {area:74}, where the temple's ruins break the water."] = "Cabalga al este; los horrores enredados del camino también sueltan los ensayos. Busca en el borde de {area:74}, donde las ruinas del templo asoman del agua.",
		["Ride inland to the Mistvale gorilla hills. Elder Mistvale Gorillas drop the giblets; {npc:1449} sits among them."] = "Cabalga tierra adentro hasta las colinas de gorilas del Valle del Velo de Bruma. Los gorilas Velo de Bruma ancianos sueltan las menudencias; {npc:1449} está sentado entre ellos.",
		["Ride north to the hills west of the road. {npc:2535} and {npc:2536} stand together just north of Zanzil's village."] = "Cabalga al norte hasta las colinas al oeste del camino. {npc:2535} y {npc:2536} están juntos justo al norte del poblado de Zanzil.",
		["Ride north-west from the mine to the bay on the north-west coast. The Giant Clams lie on its floor and hold the pearls; {npc:2624} swims among them and drops the {item:4034}."] = "Cabalga al noroeste desde la mina hasta la bahía de la costa noroeste. Las almejas gigantes ({object:2744}) están en su fondo y guardan las perlas; {npc:2624} nada entre ellas y suelta {item:4034}.",
		["Ride south out of {zone:1432} through the pass into the {zone:1418}; {npc:2860} camps at the dig."] = "Cabalga hacia el sur, fuera de {zone:1432}, por el paso hasta {zone:1418}; {npc:2860} acampa en la excavación.",
		["Ride south to the giant's hut in the middle of the marsh."] = "Cabalga al sur hasta la choza del gigante en medio del pantano.",
		["Riding at 40"] = "Equitación a nivel 40",
		["Seahorn's next errand goes back to Arathi: skip it."] = "El siguiente encargo de Seahorn vuelve a Arathi: omítelo.",
		["Stinky waits west of the manor, in the marsh below {area:504}. Lead him to his Bogbean leaves and keep the swamp creatures off him."] = "Apestoso espera al oeste de la mansión, en el pantano bajo {area:504}. Llévalo hasta sus hojas de frijol de pantano y mantén a las criaturas del pantano lejos de él.",
		["The Mirefin murlocs crowd the north coast past {area:497}."] = "Los múrlocs Ancalodo llenan la costa norte pasada {area:497}.",
		["The burned inn stands on the road west, toward the {zone:1413}; the guard's badge lies in the ashes."] = "La posada quemada está en el camino al oeste, hacia {zone:1413}; la insignia del guardia está entre las cenizas.",
		["The deserters camp south of the road, west of {npc:4503}'s hut."] = "Los desertores acampan al sur del camino, al oeste de la choza de {npc:4503}.",
		["The driftwood washes up along the eastern shore."] = "La madera a la deriva llega a lo largo de la orilla este.",
		["The naga comb the beaches north of the Bloodsail camp; they drop the reeds."] = "Los nagas recorren las playas al norte del campamento Velasangre; sueltan los juncos.",
		["The north-west coast"] = "La costa noroeste",
		["The scroll lies in the marsh north of Biggs. The Swampwalkers north of it can drop Khadgar's essays."] = "El pergamino está en el pantano al norte de Biggs. Los caminalodos al norte de él pueden soltar los ensayos de Khadgar.",
		["The sunken temple"] = "El templo sumergido",
		["Theramore"] = "Theramore",
		["Unbagwa's ritual"] = "El ritual de Unbagwa",
		["Upstairs"] = "Arriba",
		["Warlock: {quest:3631}"] = "Brujo: {quest:3631}",
		["Zanzil's village"] = "Poblado de Zanzil",
		["for the flight back to {npc:6251} at 43"] = "para el vuelo de vuelta con {npc:6251} a nivel 43",
		["for the {zone:1435} later"] = "para {zone:1435}, más adelante",
		["for {area:1438}: keep it"] = "para {area:1438}: guárdalo",
		["for {npc:2616} in Theramore: keep it"] = "para {npc:2616} en Theramore: guárdalo",
		["for {npc:5635} at {area:348}: keep it"] = "para {npc:5635} en {area:348}: guárdalo",
		["for {npc:770} at the {area:99}, on the northern loop"] = "para {npc:770} en {area:99}, en el circuito norte",
		["only if you carry a {item:3853} (a blacksmith's craft)"] = "solo si llevas una {item:3853} (una creación de herrero)",
		["with the spices from Theramore"] = "con las especias de Theramore",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}, para \"Ojolodo\" Jarl",
		["{npc:1141} cooks in the {object:2169}; {npc:5384} is in the {object:28027}."] = "{npc:1141} cocina en {object:2169}; {npc:5384} está en {object:28027}.",
		["{npc:1261}: other colours, 20g"] = "{npc:1261}: otros colores, 20g",
		["{npc:1440}, the Royal Library in {object:2117}"] = "{npc:1440}, en la Biblioteca Real de {object:2117}",
		["{npc:217412}: {quest:93176}, from 30-40/05-arathi-highlands"] = "{npc:217412}: {quest:93176}, de 30-40/05-arathi-highlands",
		["{npc:2487}, top floor"] = "{npc:2487}, piso superior",
		["{npc:2498}'s next Zanzil errand starts in {zone:1441}: skip it."] = "El siguiente encargo de {npc:2498} sobre Zanzil empieza en {zone:1441}: omítelo.",
		["{npc:2535} and {npc:2536}"] = "{npc:2535} y {npc:2536}",
		["{npc:2624} swims off the north-west coast, on the northern loop"] = "{npc:2624} nada frente a la costa noroeste, en el circuito norte",
		["{npc:2888} camps by himself in {area:1898}, south-east of the digsite."] = "{npc:2888} acampa solo en {area:1898}, al sureste de la excavación.",
		["{npc:384}: other colours, 20g"] = "{npc:384}: otros colores, 20g",
		["{npc:461}, in the {object:2164}: {npc:6251} in {area:392} takes it at the end of the next guide"] = "{npc:461}, en {object:2164}: {npc:6251} en {area:392} la recibe al final de la siguiente guía",
		["{npc:4730}: other colours, 20g"] = "{npc:4730}: otros colores, 20g",
		["{npc:4966} holds the tower with a few deserters. He turns on you: beat him until he yields.\nCareful: Hendel has two guards who join the fight when he turns hostile. The guards flee once he surrenders.\n{npc:4967} and {npc:4968} wait beside the tower: once he yields, hand in to both on the spot."] = "{npc:4966} ocupa la torre con unos cuantos desertores. Se vuelve contra ti: golpéalo hasta que se rinda.\nCuidado: Hendel tiene dos guardias que se unen a la pelea cuando se vuelve hostil. Los guardias huyen en cuanto él se rinde.\n{npc:4967} y {npc:4968} esperan junto a la torre: cuando se rinda, entrega a ambos ahí mismo.",
		["{npc:4967}, at the tower"] = "{npc:4967}, en la torre",
		["{npc:6171}, in the Cathedral of Light"] = "{npc:6171}, en la Catedral de la Luz",
		["{npc:6236} offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon."] = "{npc:6236} ofrece después El Vigía del viento (1791): la cadena del arma de Torbellino, con un élite al final, está en la guía de clase de guerrero Arma Torbellino.",
		["{npc:773}: for {quest:2864} in {zone:1446}, keep it"] = "{npc:773}: para {quest:2864} en {zone:1446}, guárdalo",
		["{npc:7955}: other colours, 20g"] = "{npc:7955}: otros colores, 20g",
		["{quest:1260} stands near the inn; {npc:4897}, a trade supplier a few steps south, sells the spices Jarl wants."] = "{quest:1260} está cerca de la posada; {npc:4897}, una proveedora de comercio a pocos pasos al sur, vende las especias que quiere Jarl.",
		["{zone:1453} has no shaman trainer"] = "{zone:1453} no tiene instructor de chamanes",
} end)()
t.guides["forever/alliance/40-50/02-badlands"] = (function() return {
		["Fly to {area:271}"] = "Vuela a {area:271}",
		["Raleigh's next errand is in the {area:796}: skip it."] = "El siguiente encargo de Raleigh es en {area:796}: omítelo.",
		["Ride back east to {area:1898}."] = "Cabalga de vuelta al este hasta {area:1898}.",
		["Ride back north to Ironband's camp."] = "Cabalga de vuelta al norte hasta la Excavación de Vetaferro.",
		["Ride north-east out of {area:271} on the road into the {zone:1425}; {area:348} sits just past the border. {npc:5635} holds court at the top, {quest:1450} tends the aviary and {npc:7884} stands by the inn."] = "Cabalga hacia el noreste fuera de {area:271} por el camino hacia {zone:1425}; {area:348} está justo pasando la frontera. {npc:5635} recibe en la cima, {quest:1450} cuida el aviario y {npc:7884} está junto a la posada.",
		["Talonaxe's next task waits for a later {zone:1425} guide."] = "La siguiente tarea de Talonaxe espera a una guía posterior de {zone:1425}.",
		["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "Las Crías hirvientes anidan en el barranco al este de {npc:2888}; deja en paz a los Guardianes abrasados (élite). {item:4612} cae rara vez: tómalo si aparece mientras cazas.",
		["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace."] = "Las dos primeras jaulas están juntas en la aldea Secacorteza al sur de {npc:5634}; la tercera está en la siguiente aldea al este. Cualquier trol Secacorteza puede soltar un collar.",
		["The {area:1517} dig"] = "La excavación de {area:1517}",
		["Theramore"] = "Isla Theramore",
		["Warlock: {quest:3631}"] = "Brujo: {quest:3631}",
		["Witherbark villages"] = "Aldeas Secacorteza",
		["{area:144} flight master"] = "Maestro de vuelo de {area:144}",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616} está en los muelles donde llega el barco.",
		["{npc:2817}'s next quest pays no experience: skip it."] = "La siguiente misión de {npc:2817} no da experiencia: omítela.",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "La siguiente tarea de {npc:2888} es una cacería de élite: omítela.",
		["{npc:2944} does not stay at {area:342}: he walks a long loop around the {zone:1418} with his guards, from the camp in the west along the south of the zone to about 61,69, north to about 49,49 and back west to the camp. The arrow follows his loop west from here until you meet him."] = "{npc:2944} no se queda en {area:342}: recorre un largo circuito por {zone:1418} con sus guardias, desde el campamento en el oeste por el sur de la zona hasta aproximadamente 61,69, al norte hasta aproximadamente 49,49 y de vuelta al oeste hasta el campamento. La flecha sigue su circuito hacia el oeste desde aquí hasta que lo encuentres.",
		["{npc:5634} camps on the road east of {area:348}."] = "{npc:5634} acampa en el camino al este de {area:348}.",
		["{npc:7744}; below ground"] = "{npc:7744}; bajo tierra",
} end)()
t.guides["forever/alliance/40-50/03-feralas"] = (function() return {
		["Back to the {area:1117}. Every Hatecrest naga there can drop scales."] = "Vuelve a {area:1117}. Cualquier naga Crestafuria de allí puede soltar escamas.",
		["Gordunni ogres"] = "Ogros Gordunni",
		["Grimtotem camp"] = "Campamento Tótem Siniestro",
		["Grimtotem tauren"] = "Taurens Tótem Siniestro",
		["Grind to 45"] = "Sube a nivel 45 matando",
		["Hatecrest naga"] = "Nagas Crestafuria",
		["Ride back to the {area:1108}; the goblin stands by the dock."] = "Cabalga de vuelta a {area:1108}; el goblin está junto al muelle.",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north."] = "Cabalga al este hasta el campamento Gordunni en las colinas al sureste del valle de los yetis: brujos y chamanes ocupan el campamento, y toscos rondan las laderas a su alrededor y más al norte.",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "Cabalga al norte hacia el valle de los yetis. Cualquier yeti Cicatriz Feral puede soltar una piel gruesa; {npc:5346} (nivel 48) merodea por el centro.",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "Cabalga al noreste hasta el puesto de los elfos de la noche en la frontera de {zone:1441}.",
		["Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to {area:489}. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out."] = "Cabalga al sureste hasta los gnolls Zarpaleña; las mochilas del mensajero están en su campamento del sur, y un paquete dentro de ellas inicia una entrega a {area:489}. La colmena Zukk'ash está justo al sur: abre paso hasta la vaina que retiene a Raschal, libéralo y mantenlo con vida al salir.",
		["Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with {item:18904} and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf."] = "Los zancaorillas, zancaprofundas y asaltaolas (gigantes élite) vadean la costa al norte del muelle: dispárale a uno con {item:18904} y mata al gigante encogido. Los elementales de mar y rocíos del mar flotan en el mismo oleaje.",
		["Take the boat to the {area:1108} and follow the shore south to the wrecked row boat on the beach."] = "Toma el barco a {area:1108} y sigue la orilla al sur hasta el bote de remos destrozado en la playa.",
		["The courier's boat"] = "El bote del mensajero",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "Camina al sur por la isla hasta las ruinas naga; el cenador está entre ellas.",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "para Tyrande Susurravientos en {zone:1457}: la ruta te lleva allí a nivel 47",
		["grind on {npc:5292} at {area:1105}, {zone:1444}"] = "mata {npc:5292} en {area:1105}, {zone:1444}",
		["{item:11463}, from the backpacks"] = "{item:11463}, de las mochilas",
		["{npc:14637}'s refills are level 55: skip them."] = "Las recargas de {npc:14637} son de nivel 55: omítelas.",
		["{npc:3936} then asks you to carry news to {zone:1457}: skip it, {area:976} sends you there instead."] = "Luego {npc:3936} te pide llevar noticias a {zone:1457}: omítela, {area:976} te envía allí en su lugar.",
		["{npc:3936}, beside him"] = "{npc:3936}, a su lado",
		["{npc:7764}: his answer waits in {area:702}, later"] = "{npc:7764}: su respuesta espera en {area:702}, más adelante",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}, en lo alto del bastión",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136} espera hasta el final de la vuelta por el continente.",
} end)()
t.guides["forever/alliance/40-50/04-tanaris"] = (function() return {
		["Boat to {area:150}"] = "Barco a {area:150}",
		["Fly to Theramore"] = "Vuela a Isla Theramore",
		["Gives the {item:8585}"] = "Da el {item:8585}",
		["Pool by {area:979}"] = "Estanque junto a {area:979}",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "Cabalga al este por las dunas hasta el puerto goblin de la costa noreste.",
		["Ride north-west to the Sandfury troll camp at {area:979}. Use the {item:8584} at the edge of its pool; the trolls stand close, so pull the nearest first."] = "Cabalga al noroeste hasta el campamento trol Furiarena en {area:979}. Usa el {item:8584} al borde de su estanque; los trols están cerca, así que atrae primero al más cercano.",
		["Ride south to the dig camp at the {area:1938}. {npc:7771} hands you a detector helm: wear it to see the {quest:3161} mounds, which lie thick in the sand around the camp and south-west toward the ogres."] = "Cabalga al sur hasta el campamento de excavación en {area:1938}. {npc:7771} te da un yelmo detector: póntelo para ver los montículos de {quest:3161}, abundantes en la arena alrededor del campamento y al suroeste, hacia los ogros.",
		["Ride south-east off the {area:439} into {zone:1446}. {area:976} is just inside the border."] = "Cabalga al sureste desde {area:439} hacia {zone:1446}. {area:976} está justo al cruzar la frontera.",
		["Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "Cabalga al suroeste hasta la base ogra. La llenan toscos y déspotas (46-48); {npc:12046} (49) está en el centro rodeado de guardias: elimínalos primero.",
		["The Wanted poster beside him"] = "El cartel de Se busca a su lado",
		["The little turtle {npc:5955} hides at the north end of the valley. Lead him home to his wife {npc:6015}, by the water just east of {area:977}: he walks slowly and the desert's beasts go for him, so keep him alive."] = "La pequeña tortuga {npc:5955} se esconde en el extremo norte del valle. Llévalo a casa con su esposa {npc:6015}, junto al agua justo al este de {area:977}: camina despacio y las bestias del desierto lo atacan, así que mantenlo con vida.",
		["The pool by {area:979}"] = "El estanque junto a {area:979}",
		["The same poster: {npc:7847} comes much later, after {area:976}"] = "El mismo cartel: {npc:7847} llega mucho más tarde, después de {area:976}",
		["The {area:1938}"] = "{area:1938}",
		["The {area:2240} lies on the {area:439} in south-east {zone:1441}: {npc:4454} is in the gnomes' camp beside the track, Zamek by the goblin camp."] = "{area:2240} está en {area:439}, al sureste de {zone:1441}: {npc:4454} está en el campamento de los gnomos junto a la pista, y Zamek, junto al campamento goblin.",
		["for {zone:1457}: the route takes you there at 47"] = "para {zone:1457}: la ruta te lleva allí a nivel 47",
		["{npc:5955}'s escort"] = "La escolta de {npc:5955}",
		["{npc:7407}, by the water tower"] = "{npc:7407}, junto a la torre de agua",
		["{npc:7408}, next to him"] = "{npc:7408}, a su lado",
		["{npc:7763}: his crate goes to {area:702}, later"] = "{npc:7763}: su caja va a {area:702}, más adelante",
		["{quest:2864}, north side of town"] = "{quest:2864}, en el lado norte del pueblo",
} end)()
