		["South down the road to {area:144}, finishing the ears, meat and ichor on the way. {npc:1340} walks the road through town."] = "Ve al sur por el camino hasta {area:144} y termina las orejas, la carne y el icor de camino. {npc:1340} recorre el camino que atraviesa el pueblo.",
		["Stonesplinter Seers (level 13) stand among the troggs in the south of {area:923}, south of {npc:257808}; Tunnel Rat Geomancers (level 12) work the {area:149} at the north end of the loch. The troggs come in packs and some throw from range: pull one at a time."] = "Los Videntes Rompecantos ({npc:1166}, nivel 13) están entre los troggs del sur de {area:923}, al sur de {npc:257808}; los Geománticos Ratatúnel ({npc:1174}, nivel 12) trabajan en {area:149}, en el extremo norte del lago. Los troggs vienen en grupos y algunos atacan a distancia: atráelos de uno en uno.",
		["Subdue the voidwalker"] = "Somete al abisario",
		["The Fire Spirit Stone"] = "La piedra espiritual del fuego",
		["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "La bebida caliente dura cinco minutos: ve directo al norte con {npc:836}, dentro de {area:77}.",
		["The boars"] = "Los jabalíes",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "La leña está en la nieve alrededor del lago helado junto al refugio.",
		["The quarry troggs"] = "Los troggs de la cantera",
		["The troggs"] = "Los troggs",
		["The troll cave"] = "La cueva de los trols",
		["The tunnel"] = "El túnel",
		["The {area:2257}"] = "{area:2257}",
		["The {object:269} in the basement"] = "{object:269}, en el sótano",
		["Upstairs"] = "Arriba",
		["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "Empiezas frente a {area:77}, el salón de piedra del extremo norte del valle. {npc:658} espera fuera de la puerta.",
		["Young wolves"] = "Lobos jóvenes",
		["talk to the trainer"] = "habla con el instructor",
		["{area:131} and the depot"] = "{area:131} y el almacén",
		["{area:77} is on the way north from {npc:786}'s camp to the tunnel: {npc:837}, the priest trainer inside, sends priests of level 5 to {npc:1226} in {area:131}."] = "{area:77} queda de camino al norte desde el campamento de {npc:786} hacia el túnel: {npc:837}, el instructor de sacerdotes que está dentro, envía a los sacerdotes de nivel 5 con {npc:1226} en {area:131}.",
		["{item:13850}: the {object:176785}"] = "{item:13850}: {object:176785}",
		["{item:277976}, in the camp"] = "{item:277976}, en el campamento",
		["{item:286325} is by the frozen lake, among the ice elementals."] = "{item:286325} está junto al lago helado, entre los elementales de hielo.",
		["{item:3083}: Leper Gnomes"] = "{item:3083}: gnomos parias",
		["{item:3084}: Leper Gnomes"] = "{item:3084}: gnomos parias",
		["{item:5026} and the {item:6652}"] = "{item:5026} y la {item:6652}",
		["{item:5026}: Tunnel Rat Geomancers"] = "{item:5026}: Geománticos Ratatúnel ({npc:1174})",
		["{item:6635}, beside the Spirit Stone"] = "{item:6635}, junto a la piedra espiritual",
		["{item:6636}, beside the Spirit Stone"] = "{item:6636}, junto a la piedra espiritual",
		["{item:6652}: Stonesplinter Seers"] = "{item:6652}: Videntes Rompecantos ({npc:1166})",
		["{npc:1226}, upstairs: {item:16605}"] = "{npc:1226}, en el piso de arriba: {item:16605}",
		["{npc:1226}: heal {npc:12427} south of {area:131}"] = "{npc:1226}: sana a {npc:12427} al sur de {area:131}",
		["{npc:1226}: {npc:258785} in {zone:1455} takes it"] = "{npc:1226}: la recibe {npc:258785} en {zone:1455}",
		["{npc:1241}, in the cellar west of the distillery"] = "{npc:1241}, en el sótano al oeste de la destilería",
		["{npc:12427} kneels wounded on the ridge between two low walls just south of {area:131}, across the road from the hunter pet trainer, on the walk back from Rumbleshot's camp. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Rank 1 of {spell:613} does not count."] = "{npc:12427} está arrodillado y herido en la cresta entre dos muros bajos justo al sur de {area:131}, al otro lado del camino del instructor de mascotas de cazador, de regreso del campamento de Rumbleshot. Lánzale {spell:613} (rango 2) y luego {spell:1243}: el rango 1 de {spell:613} no cuenta.",
		["{npc:12738}, next to him"] = "{npc:12738}, a su lado",
		["{npc:12738}: timed, five minutes to reach {npc:836} in {area:77}"] = "{npc:12738}: con tiempo límite, cinco minutos para llegar con {npc:836} en {area:77}",
		["{npc:1698}: blacksmiths only"] = "{npc:1698}: solo herreros",
		["{npc:1702}, beside {npc:5392}"] = "{npc:1702}, junto a {npc:5392}",
		["{npc:1965} guards the tunnel out of the valley, east of {area:77}; {npc:6782} stands beside him at its mouth."] = "{npc:1965} vigila el túnel de salida del valle, al este de {area:77}; {npc:6782} está a su lado en la entrada.",
		["{npc:1977}, in the quarry"] = "{npc:1977}, en la cantera",
		["{npc:2326}, inside the distillery"] = "{npc:2326}, dentro de la destilería",
		["{npc:257446}, inside {area:77}"] = "{npc:257446}, dentro de {area:77}",
		["{npc:257446}: {npc:5873} and your {item:5175}"] = "{npc:257446}: {npc:5873} y tu {item:5175}",
		["{npc:257597} waits in a cave above the farm north-west of the {area:806}; the path up starts behind the farm."] = "{npc:257597} espera en una cueva sobre la granja al noroeste de {area:806}; el sendero de subida empieza detrás de la granja.",
		["{npc:257597}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:257597}: {npc:2523}, tu {item:5176} y el {item:263412}",
		["{npc:257808} gives you the {item:6636}. Climb to the peak above his camp, drink the Sapta beside the Spirit Stone and defeat the {npc:5893}, then place its {item:6655} in the {object:61934}, atop the Shrine of Eternal Flame."] = "{npc:257808} te da la {item:6636}. Sube a la cima sobre su campamento, bebe la sapta junto a la piedra espiritual y derrota a {npc:5893}; luego pon su {item:6655} en {object:61934}, en lo alto del santuario de la Llama Eterna.",
		["{npc:258113}: {npc:257597} by the South Gate takes it"] = "{npc:258113}: la recibe {npc:257597}, junto a la puerta sur",
		["{npc:265813}: for {npc:1241}, in the cellar west of the distillery"] = "{npc:265813}: para {npc:1241}, en el sótano al oeste de la destilería",
		["{npc:265813}: for {npc:1702} at {area:189}"] = "{npc:265813}: para {npc:1702} en {area:189}",
		["{npc:265813}: for {npc:2326} in the {area:2102}"] = "{npc:265813}: para {npc:2326} en {area:2102}",
		["{npc:265813}: for {npc:5392} at {area:189}"] = "{npc:265813}: para {npc:5392} en {area:189}",
		["{npc:2756} stands by {npc:8416} at the door of {area:77}. Gozwin's camp is in the hills just north-west; the {npc:269075} prowls around it."] = "{npc:2756} está junto a {npc:8416} en la puerta de {area:77}. El campamento de Gozwin está en las colinas justo al noroeste; {npc:269075} merodea a su alrededor.",
		["{npc:460}, inside {area:77}"] = "{npc:460}, dentro de {area:77}",
		["{npc:5392}, at the depot"] = "{npc:5392}, en el almacén",
		["{npc:5480} trains warriors in {object:2100}, near Osric's shop; the tram from {zone:1455} arrives in the {object:28027}, north of it. {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "{npc:5480} entrena guerreros en {object:2100}, cerca de la tienda de Osric; el tranvía de {zone:1455} llega a {object:28027}, al norte. {npc:6089} y {npc:6090} están juntos junto a {object:2152}, allí. {npc:6090} pelea contigo por su jarra. Si {npc:5480} no te ofrece {quest:1638}, ve directo con {npc:6089}: te da {quest:1639} sin ella.",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "{npc:5497} está en la torre de {object:2101}; te da un frasco para la cascada de {quest:1861}.",
		["{npc:6120}: {npc:6122} in {zone:1453} takes it"] = "{npc:6120}: la recibe {npc:6122} en {zone:1453}",
		["{npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "{npc:6122} espera en el sótano de {object:2164}, en {object:2101}.",
		["{npc:713}, next to {npc:658}"] = "{npc:713}, junto a {npc:658}",
		["{npc:714}'s camp is at the west end of the valley. {item:10438} lies in the snow south of it, his Chest by the troll cave and his Bucket of Bolts east of the cave: grab them as you pass."] = "El campamento de {npc:714} está en el extremo oeste del valle. {item:10438} está en la nieve al sur de él, su cofre junto a la cueva de los trols y su cubo de tornillos al este de la cueva: tómalos al pasar.",
		["{npc:786} and {npc:12738} camp at the south-west edge of the valley, below the troll cave."] = "{npc:786} y {npc:12738} acampan en el borde suroeste del valle, debajo de la cueva de los trols.",
		["{npc:808} is inside the troll cave east of {npc:786}'s camp, not on the hill above it: go in at the mouth and follow the tunnel to the back."] = "{npc:808} está dentro de la cueva de los trols al este del campamento de {npc:786}, no en la colina de encima: entra por la boca y sigue el túnel hasta el fondo.",
		["{npc:837}, inside {area:77}"] = "{npc:837}, dentro de {area:77}",
		["{npc:837}, the priest trainer"] = "{npc:837}, el instructor de sacerdotes",
		["{npc:912}, the warrior trainer"] = "{npc:912}, el instructor de guerreros",
		["{npc:916}, the rogue trainer"] = "{npc:916}, el instructor de pícaros",
		["{npc:944}, the mage trainer, inside {area:77}"] = "{npc:944}, el instructor de magos, dentro de {area:77}",
		["{object:660964}, by the mailbox in {object:171524}"] = "{object:660964}, junto al buzón de {object:171524}",
} end)()
t.guides["forever/alliance/human/01-elwynn-forest"] = (function() return {
		["\"Auntie\" Bernice Stonefield"] = "\"Tita\" Bernice Pedregosa",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls."] = "Regresa con {npc:6122}. Usa {item:6928} en el círculo de invocación del sótano de {object:2164} y derrota al abisario que convoca.",
		["Billy plays in the {area:64}, east of the mine."] = "Billy juega en {area:64}, al este de la mina.",
		["Chunks of Boar Meat"] = "Trozos de carne de jabalí",
		["Class trainer"] = "Instructor de clase",
		["Crystal Kelp Fronds"] = "Hojas de alga de cristal",
		["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore."] = "Los Zahoríes bribones de Defias acampan en las orillas de {area:86}; también sueltan los Pañuelos de lino rojo. {object:56} está en la aldea múrloc de la orilla noreste.",
		["Defias Thugs camp in the clearing east of the Abbey and along the valley's east side."] = "Los Matones Defias acampan en el claro al este de la abadía y a lo largo del lado este del valle.",
		["Follow the hills south to the tower, on the road west."] = "Sigue las colinas hacia el sur hasta la torre, en el camino al oeste.",
		["Follow the hills south to the tower."] = "Sigue las colinas hacia el sur hasta la torre.",
		["Follow the path north to the mine. Kobold Workers swarm outside it; every kobold in the valley can drop the {object:83763}."] = "Sigue el sendero hacia el norte hasta la mina. Los Trabajadores kóbold pululan afuera; cualquier kóbold del valle puede soltar {object:83763}.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "Sigue el camino hacia el norte desde {area:87} hasta {zone:1453}. {npc:5497} está en el Wizard's Sanctum, la torre de {object:2101}; te da un frasco para la cascada de {quest:1861}.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "Sigue el camino hacia el norte desde {area:87} hasta {zone:1453}. {npc:6122} espera en el sótano de {object:2164}, en {object:2101}.",
		["Follow the road south out of {area:87} to the {area:64}. {npc:251} waits by the house."] = "Sigue el camino hacia el sur fuera de {area:87} hasta {area:64}. {npc:251} espera junto a la casa.",
		["Fun with Elementals: {npc:248464}"] = "Diversión con elementales: {npc:248464}",
		["He stands by the river west of the farm."] = "Está junto al río, al oeste de la granja.",
		["Head back out through {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "Regresa por {area:87} y hacia el este por el camino hasta {area:62}. {npc:881} (nivel 9) está junto a la granja.",
		["Heal and fortify {npc:12423}"] = "Sana y fortalece a {npc:12423}",
		["Inside {area:34}"] = "Dentro de {area:34}",
		["It lies by the river north-west of the logging camp."] = "Está junto al río, al noroeste del campamento maderero.",
		["Kobold Laborers work the tunnels inside the mine. {npc:248362} waits down the second turn on the right.\nCareful: {npc:248362} (3) is elite: leave him unless you have a friend."] = "Los Obreros kóbold trabajan en los túneles dentro de la mina. {npc:248362} espera al fondo de la segunda curva a la derecha.\nCuidado: {npc:248362} (3) es élite: déjalo a menos que tengas un amigo.",
		["Large Candles"] = "Velas grandes",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Sal de {zone:1453} por la puerta principal. La cascada de {quest:1861} está al suroeste de las puertas, de camino al oeste hacia {zone:1436}: llena {item:7207} en su base.",
		["Lost Books: Kobold Miners and Tunnelers"] = "Libros perdidos: Mineros kóbold y Tuneladores kóbold",
		["Murlocs and Murloc Streamrunners hold the east shore; the Junk Piles lie in their camp. Careful: the murlocs stand close together, so a fight easily pulls two or three at once: pull them one at a time from the edge of the camp, and don't chase one into the next group."] = "Los Múrlocs y los Correcorrientes múrloc ocupan la orilla este; los Junk Piles están en su campamento. Cuidado: los múrlocs están muy juntos, así que un combate fácilmente atrae a dos o tres a la vez: atráelos de uno en uno desde el borde del campamento y no persigas a uno hasta el siguiente grupo.",
		["North-east of the logging camp. Defias Rogue Wizards camp on the shores of the lake."] = "Al noreste del campamento maderero. Los Zahoríes bribones de Defias acampan en las orillas del lago.",
		["Painted Gnoll Armbands"] = "Bandas gnoll pintadas",
		["Red Burlap Bandanas"] = "Pañuelos de arpillera roja",
		["Red Linen Bandanas"] = "Pañuelos de lino rojo",
		["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "Los gnolls Zarparrío acampan en las colinas al oeste de {area:86}; {quest:91725} están en sus campamentos.",
		["She stands by her cart at the vineyard east of the Abbey."] = "Está junto a su carreta en el viñedo al este de la abadía.",
		["She stands outside the mine entrance. {npc:248362}, inside, is elite: grouping up is advised."] = "Está afuera de la entrada de la mina. {npc:248362}, adentro, es de élite: se recomienda ir en grupo.",
		["Shiny Red Apples, from {npc:894}, for the {quest:91736}"] = "Manzanas rojas lustrosas, de {npc:894}, para {quest:91736}",
		["Sit (/sit) by his campfire until you have {spell:1229451}"] = "Siéntate (/sit) junto a su fogata hasta tener {spell:1229451}",
		["South down the road to the {area:64}."] = "Al sur por el camino hasta {area:64}.",
		["Subdue the voidwalker"] = "Somete al abisario",
		["The Defias camp"] = "El campamento Defias",
		["The Fishing Traps sit along the west shore of the lake."] = "Las trampas ({object:694772}) están a lo largo de la orilla oeste del lago.",
		["The bridge"] = "El puente",
		["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it."] = "El campamento está al noreste del puente. Los Fardos de madera están alrededor del campamento y en el bosque al norte.",
		["The crates of grapes lie in the vineyards behind the Defias. {npc:103} waits by the cabin at the east end of the valley."] = "Las cajas de uvas están en los viñedos detrás de los Defias. {npc:103} espera junto a la cabaña en el extremo este del valle.",
		["The gnoll camps"] = "Los campamentos gnoll",
		["The kobold camp"] = "El campamento kóbold",
		["The lake shore"] = "La orilla del lago",
		["The mine is south-west of the gnoll camps. {item:247816} lie near the entrance; Kobold Geomancers hold the tunnels.\nCareful: {npc:471} (7-10), the Mine Spiders (7-9) and {npc:248474} (7) are elites deep in the mine: pull the kobolds one at a time near the entrance and back out if an elite comes; they're easier with a friend."] = "La mina está al suroeste de los campamentos gnoll. {item:247816} están cerca de la entrada; los Geománticos kóbold ocupan los túneles.\nCuidado: {npc:471} (7-10), las Arañas de mina (7-9) y {npc:248474} (7) son élites en lo profundo de la mina: atrae a los kóbolds de uno en uno cerca de la entrada y retírate si viene un élite; son más fáciles con un amigo.",
		["The mine is west of the vineyards. Kobold Miners and Tunnelers fill both levels; {npc:248464}, a named kobold, holds the picture book in the lower tunnels. {npc:248464} is elite: grouping up is advised."] = "La mina está al oeste de los viñedos. Los Mineros kóbold ({npc:40}) y los Tuneladores kóbold llenan ambos niveles; {npc:248464}, un kóbold con nombre, tiene el libro ilustrado en los túneles inferiores. {npc:248464} es de élite: se recomienda ir en grupo.",
		["The murlocs on the east shore drop the kelp. Skinners: Gray Forest Wolves roam the woods between the lake and the {area:91}; Prowlers further east give pelts too."] = "Los múrlocs de la orilla este sueltan el alga. Desolladores: los Lobos grisáceos del bosque recorren el bosque entre el lago y {area:91}; los Merodeadores, más al este, también dan pieles.",
		["The vineyards and {npc:103}"] = "Los viñedos y {npc:103}",
		["The {area:88}"] = "{area:88}",
		["The {area:91}"] = "{area:91}",
		["The {quest:91736}"] = "{quest:91736}",
		["Walk into the mine"] = "Entra en la mina",
		["Walk through the mine"] = "Recorre la mina",
		["Wolves"] = "Lobos",
		["You start in front of the Abbey. {npc:823} stands at the foot of the steps, {npc:197} inside the hall, {npc:951} and {npc:247229} in the library to the right, {npc:196} outside the north-west corner."] = "Empiezas frente a la abadía. {npc:823} está al pie de las escaleras; {npc:197}, dentro del salón; {npc:951} y {npc:247229}, en la biblioteca a la derecha; {npc:196}, afuera, en la esquina noroeste.",
		["Young Wolves and Timber Wolves roam the fields right around the Abbey."] = "Los Lobos jóvenes y los Lobos grises recorren los campos justo alrededor de la abadía.",
		["his kobold tracker shows the kobolds to click on the road to {area:87}"] = "su rastreador de kóbolds muestra los kóbolds en los que debes hacer clic en el camino a {area:87}",
		["talk to the trainer"] = "habla con el instructor",
		["{item:247824}, from the still"] = "{item:247824}, del alambique",
		["{item:286215}: Stonetusk Boars"] = "{item:286215}: Jabalíes Colmipétreos",
		["{item:6785}: the {object:83763} in the Defias camp"] = "{item:6785}: {object:83763} en el campamento Defias",
		["{npc:12423} kneels wounded by a tree on the west shore of {area:18}, among the Fishing Traps. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Rank 1 of {spell:613} does not count. He walks off once both land and is back in about 3 minutes."] = "{npc:12423} está arrodillado y herido junto a un árbol en la orilla oeste de {area:18}, entre las trampas de pesca. Lánzale {spell:613} (rango 2) y luego {spell:1243}: el rango 1 de {spell:613} no cuenta. Se va cuando recibe ambos y regresa en unos 3 minutos.",
		["{npc:1632}, beside {npc:6306}"] = "{npc:1632}, junto a {npc:6306}",
		["{npc:1922}: tame it with the {item:15908}"] = "{npc:1922}: domestícalo con {item:15908}",
		["{npc:198}, the mage trainer, inside the Abbey"] = "{npc:198}, el instructor de magos, dentro de la abadía",
		["{npc:2329}, in the Lion's Pride Inn"] = "{npc:2329}, en la Lion's Pride Inn",
		["{npc:248242} and {npc:248248} stand at the foot of the tower."] = "{npc:248242} y {npc:248248} están al pie de la torre.",
		["{npc:248415}, by the Abbey"] = "{npc:248415}, junto a la abadía",
		["{npc:251507} stands with the {area:87} trainers. Each of her quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her. Rockhide Boars and Young Forest Bears roam the hills south of the {area:64}, Gray Forest Wolves the woods east of {area:18}."] = "{npc:251507} está con los instructores de {area:87}. Cada una de sus misiones te da {item:15908}: úsala en la bestia que indica y luego devuélvele la vara. Los Jabalíes Pielroca y los Osos del bosque jóvenes recorren las colinas al sur de {area:64}; los Lobos grisáceos del bosque, el bosque al este de {area:18}.",
		["{npc:253}, back in the inn"] = "{npc:253}, de vuelta en la posada",
		["{npc:258930}, beside her: {spell:5149}"] = "{npc:258930}, a su lado: {spell:5149}",
		["{npc:261} guards the bridge on the road east; {npc:248265} stands just across it."] = "{npc:261} vigila el puente en el camino al este; {npc:248265} está justo al otro lado.",
		["{npc:263399} camps north-east of the inn. With a profession learned, he also offers its Camping 101, which its trainer takes: skinning, leatherworking and fishing on the lake shore, {skill:129} and blacksmithing in {area:87}."] = "{npc:263399} acampa al noreste de la posada. Si ya aprendiste una profesión, también ofrece su Camping 101, que recibe el instructor de esa profesión: desuello, peletería y pesca en la orilla del lago; {skill:129} y herrería en {area:87}.",
		["{npc:263399}: for {npc:1632} on the lake shore"] = "{npc:263399}: para {npc:1632} en la orilla del lago",
		["{npc:263399}: for {npc:1651} on the lake shore"] = "{npc:263399}: para {npc:1651} en la orilla del lago",
		["{npc:263399}: for {npc:2329} in the Lion's Pride Inn"] = "{npc:263399}: para {npc:2329} en la Lion's Pride Inn",
		["{npc:263399}: for {npc:514} at the {area:87} smithy"] = "{npc:263399}: para {npc:514} en la herrería de {area:87}",
		["{npc:263399}: for {npc:6306} on the lake shore"] = "{npc:263399}: para {npc:6306} en la orilla del lago",
		["{npc:279} in {zone:1453} takes it (02-westfall)"] = "{npc:279} en {zone:1453} la recibe (02-westfall)",
		["{npc:328}: {npc:5497} in {zone:1453} takes it"] = "{npc:328}: la recibe {npc:5497} en {zone:1453}",
		["{npc:375}, the priest trainer"] = "{npc:375}, la instructora de sacerdotes",
		["{npc:375}, the priest trainer: {npc:377} in {area:87} takes it"] = "{npc:375}, la instructora de sacerdotes: la recibe {npc:377} en {area:87}",
		["{npc:377}, upstairs"] = "{npc:377}, arriba",
		["{npc:377}, upstairs: {item:16605}"] = "{npc:377}, arriba: {item:16605}",
		["{npc:377}: heal {npc:12423} at {area:18}"] = "{npc:377}: sana a {npc:12423} en {area:18}",
		["{npc:459}, outside the Abbey"] = "{npc:459}, afuera de la abadía",
		["{npc:514}, at the smithy across the road"] = "{npc:514}, en la herrería al otro lado del camino",
		["{npc:514}, at the smithy beside Dughan: {npc:1416} in {zone:1453} takes it (02-westfall)"] = "{npc:514}, en la herrería junto a Dughan: la recibe {npc:1416} en {zone:1453} (02-westfall)",
		["{npc:524}: tame it with the {item:15908}"] = "{npc:524}: domestícalo con {item:15908}",
		["{npc:6121}: {npc:6122} in {zone:1453} takes it"] = "{npc:6121}: la recibe {npc:6122} en {zone:1453}",
		["{npc:6306}, on the lake shore east of town; inside"] = "{npc:6306}, en la orilla del lago al este del pueblo; adentro",
		["{npc:6306}, {npc:383} and {npc:1651} stand on the shore of {area:18} east of town."] = "{npc:6306}, {npc:383} y {npc:1651} están en la orilla de {area:18}, al este del pueblo.",
		["{npc:6774}, by the stables south of the Abbey"] = "{npc:6774}, junto a los establos al sur de la abadía",
		["{npc:6} dig in the vineyards north-east of the Abbey. Now and then one drops a {quest:91741}: right-click it."] = "Los {npc:6} excavan en los viñedos al noreste de la abadía. De vez en cuando uno suelta {quest:91741}: haz clic derecho en él.",
		["{npc:822}: tame it with the {item:15908}"] = "{npc:822}: domestícalo con {item:15908}",
		["{npc:823}, back at the Abbey steps"] = "{npc:823}, de vuelta en las escaleras de la abadía",
		["{npc:915}, the rogue trainer"] = "{npc:915}, el instructor de pícaros",
		["{npc:925}, the paladin trainer"] = "{npc:925}, el instructor de paladines",
		["{npc:952}, upstairs"] = "{npc:952}, arriba",
		["{npc:963}: for {npc:234} at {area:108}"] = "{npc:963}: para {npc:234} en {area:108}",
		["{quest:76}'s entrance"] = "La entrada de {quest:76}",
		["{quest:87} is inside the {area:57}, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a {item:1972} now and then: right-click it.\nCareful: {npc:248464} (6), a kobold deep in the mine, is elite, and {npc:79} (10, rare) walks the tunnels: pull the kobolds one at a time."] = "{quest:87} está dentro de {area:57}, no en la colina de arriba: entra por la boca y mantente a la izquierda hasta el fondo de la mina; no subas las escaleras. Los Bandidos Defias de los viñedos sueltan {item:1972} de vez en cuando: haz clic derecho en ella.\nCuidado: {npc:248464} (6), un kóbold en lo profundo de la mina, es élite, y {npc:79} (10, raro) recorre los túneles: atrae a los kóbolds de uno en uno.",
		["{quest:91733} and {npc:330}"] = "{quest:91733} y {npc:330}",
} end)()
t.guides["forever/alliance/nightelf/01-teldrassil"] = (function() return {
		["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "/sit junto a la fogata de {npc:265811} hasta obtener {spell:1229451}",
		["Back at {area:256}"] = "De vuelta en {area:256}",
		["Back to the moonwell."] = "De vuelta al pozo de la luna.",
		["Back to the top of {area:256}. The {object:654846} lies beside him."] = "De vuelta a lo alto de {area:256}. {object:654846} está a su lado.",
		["Back upstairs to {npc:3567} with the webwoods done and {npc:272116}'s moss."] = "Sube de vuelta con {npc:3567} con las tejemaderas listas y el musgo de {npc:272116}.",
		["Befouled Webwoods"] = "Tejemadera corrompidas",
		["Below ground"] = "Bajo tierra",
		["Bloodfeather harpies"] = "Arpías Sangrepluma",
		["Each of Dazalar's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him in {area:186}. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it."] = "Cada misión de Dazalar te da una {item:15908}: úsala en la bestia que nombra y luego llévale la vara a {area:186}. Los rondadores Tejemadera ({npc:1998}) se arrastran alrededor de la aldea; los acechadores sable de la noche ({npc:2043}) y los estridadores estrígidos ({npc:1996}) deambulan por el bosque al sur.",
		["Escort {npc:275744} out of the barrow; {npc:2081} in {area:186} takes the report."] = "Escolta a {npc:275744} fuera del túmulo; {npc:2081} en {area:186} recibe el informe.",
		["Fandral in {zone:1457} takes it"] = "Fandral en {zone:1457} la recibe",
		["Follow the road south-west out of {area:188}. {npc:2150} sits beside it just east of {area:186}."] = "Sigue el camino al suroeste desde {area:188}. {npc:2150} está sentado junto a él, justo al este de {area:186}.",
		["Gnarlpine Ambushers hide along the road west of {area:258}."] = "Los emboscadores Tuercepinos se esconden a lo largo del camino al oeste de {area:258}.",
		["Gnarlpine Shamans"] = "Chamanes Tuercepinos",
		["Go back down to {area:702} and fly to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "Baja de vuelta a {area:702} y vuela a {area:442}. {object:177525} está en las colinas justo al este del pueblo: usa {item:15208} allí, derrota a Garraluna y habla con {npc:12144}.",
		["Heal and fortify {npc:12429}"] = "Cura y fortalece a {npc:12429}",
		["Leave {area:188} by the path south-east of {area:256}: {npc:6780} stands beside it, where it goes down towards the road to {area:186}."] = "Sal de {area:188} por el sendero al sureste de {area:256}: {npc:6780} está junto a él, donde baja hacia el camino a {area:186}.",
		["Nightsabers"] = "Sables de la noche",
		["North to {area:257}"] = "Al norte, a {area:257}",
		["North-east from Ursal's den, back to {area:186}."] = "Al noreste desde la guarida de Ursal, de vuelta a {area:186}.",
		["North-west of Dolanaar, on the way to the {area:264}, Befouled Webwoods creep through the woods; {npc:272116} prowls at their east edge and carries the {item:281023}.\n{npc:272116} is elite (level 12): grouping up is advised. Clear the webwoods around him first and pull him on his own."] = "Al noroeste de Dolanaar, de camino a {area:264}, las Tejemadera corrompidas se arrastran por el bosque; {npc:272116} merodea por su borde este y lleva {item:281023}.\n{npc:272116} es élite (nivel 12): se recomienda ir en grupo. Primero limpia las Tejemadera a su alrededor y atráelo solo.",
		["Sentinel Arynia again"] = "Otra vez la centinela Arynia",
		["South from the glade toward Ursal: Shayla walks the road west of {area:186}, from where the path down from the glade meets it south-west to the bend at about 38,54 and back."] = "Al sur desde el claro hacia Ursal: Shayla recorre el camino al oeste de {area:186}, desde donde el sendero que baja del claro se une a él, al suroeste hasta la curva en 38,54 aproximadamente, y de regreso.",
		["South-east of Dolanaar, to {npc:2080}. Lasher Sproutlings wander around him on the shore."] = "Al sureste de Dolanaar, con {npc:2080}. Los retoños de azotador ({npc:275703}) deambulan a su alrededor en la orilla.",
		["South-west of the barrow. The moonwell sits by the pools."] = "Al suroeste del túmulo. El pozo de la luna está junto a las pozas.",
		["Speak with the {quest:5929}"] = "Habla con {quest:5929}",
		["Take the road north-west from {area:186} again; she still lies beside it, on the way to {zone:1457}."] = "Toma otra vez el camino al noroeste desde {area:186}; ella sigue tendida a su lado, de camino a {zone:1457}.",
		["The WANTED poster outside the inn"] = "El cartel de SE BUSCA fuera de la posada",
		["The moonwell"] = "El pozo de la luna",
		["The moonwell is in the middle of the glade. The {object:6752} grows at its north end."] = "El pozo de la luna está en medio del claro. {object:6752} crece en su extremo norte.",
		["The named harpies"] = "Las arpías con nombre",
		["The road to {zone:1457}"] = "El camino a {zone:1457}",
		["The {area:478}"] = "{area:478}",
		["The {object:177525}"] = "{object:177525}",
		["The {object:4406} lie at the back of {area:257}: take the central path, then left where it splits, up to the high ledge. Hyacinth Mushrooms drop from Grells, Moonpetal Lilies grow by the ponds north of {area:256}."] = "{object:4406} están al fondo de {area:257}: toma el camino central y luego a la izquierda donde se divide, hasta la cornisa alta. Los grells sueltan los champiñones jacinto; los lirios alunados crecen junto a los estanques al norte de {area:256}.",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Los Reptadores de marea ({npc:2232}) corretean por la orilla bajo el pueblo; {quest:983} está en la playa, justo al sur de los muelles. Los Trilladores de Costa Oscura ({npc:2185}) nadan en los bajíos. {object:175207} yace en la orilla, justo al sur del pueblo.",
		["Upstairs"] = "Arriba",
		["Use the {item:18152} at the moonwell"] = "Usa {item:18152} en el pozo de la luna",
		["Use the {item:5185} at the moonwell"] = "Usa {item:5185} en el pozo de la luna",
		["Use the {item:5619} at the moonwell"] = "Usa {item:5619} en el pozo de la luna",
		["Use the {item:5621} at the moonwell"] = "Usa {item:5621} en el pozo de la luna",
		["Walk Lynessa out and keep her alive"] = "Saca a Lynessa y mantenla con vida",
		["Webwood Lurkers"] = "Rondadores Tejemadera",
		["West along the road toward the city. Shayla walks this stretch of road, from the arrow south-west to the bend at about 38,54 and back: if she isn't at the arrow, follow the road south-west. Every Gnarlpine furbolg drops fangs: the ambushers on this road, the barrow's and {area:261}'s all count."] = "Al oeste por el camino hacia la ciudad. Shayla recorre este tramo del camino, desde la flecha al suroeste hasta la curva en 38,54 aproximadamente, y de regreso: si no está en la flecha, sigue el camino al suroeste. Todos los fúrbolg Tuercepinos sueltan colmillos: cuentan los emboscadores de este camino, los del túmulo y los de {area:261}.",
		["West from the webwoods to the {area:265}, then north along it to the glade: the timberlings along its banks drop the Mossy Tumors."] = "Al oeste desde las Tejemadera hasta {area:265}, y luego al norte a lo largo de él hasta el claro: los brezomaderas de sus orillas sueltan los tumores musgosos.",
		["With a profession learned, {npc:265811} also offers its Camping 101, which its trainer takes: alchemy and herbalism beside {npc:6286}, {skill:129} with {npc:6094} in the inn, skinning and leatherworking at the Maneweavers' camp on the road west."] = "Con una profesión aprendida, {npc:265811} también ofrece su Campamento 101, que recibe su instructor: alquimia y herboristería junto a {npc:6286}, {skill:129} con {npc:6094} en la posada, desuello y peletería en el campamento de los Tejecrín en el camino al oeste.",
		["You start at the foot of {area:256}, the great tree of {area:188}."] = "Empiezas al pie de {area:256}, el gran árbol de {area:188}.",
		["Young Nightsabers and Young Thistle Boars roam around {area:256}. Grells carry {item:3297} in the woods west of the tree, where the Gnarlpine Totems stand."] = "Los sables de la noche jóvenes y los jabalíes cardo jóvenes deambulan alrededor de {area:256}. Los grells llevan {item:3297} en el bosque al oeste del árbol, donde están los tótems de Tuercepinos.",
		["talk to the trainer"] = "habla con el instructor",
		["{area:186} again"] = "{area:186} otra vez",
		["{area:258}'s mouth"] = "Entrada de {area:258}",
		["{area:736}, outside the barrow"] = "{area:736}, fuera del túmulo",
		["{item:159} from {npc:6736}, for {npc:6094}"] = "{item:159} de {npc:6736}, para {npc:6094}",
		["{item:3371} from {npc:3614}, beside {npc:6094}"] = "{item:3371} de {npc:3614}, junto a {npc:6094}",
		["{npc:11401}, in the Temple of the Moon: Starshards"] = "{npc:11401}, en el Templo de la Luna: Fragmentos estelares",
		["{npc:12429} kneels wounded on the rocks at the north edge of {area:259}, on the walk back to {area:186}, with no quest mark over her. Cast {spell:613} (Rank 2) on her, then {spell:1243}: Rank 1 of {spell:613} does not count. She runs off once both land and is back in about 5 minutes."] = "{npc:12429} está arrodillada y herida en las rocas del borde norte de {area:259}, de camino de vuelta a {area:186}, sin marca de misión sobre ella. Lánzale {spell:613} (rango 2) y luego {spell:1243}: el rango 1 de {spell:613} no cuenta. Se va corriendo en cuanto recibe ambos y vuelve en unos 5 minutos.",
		["{npc:1992}, south of the tree"] = "{npc:1992}, al sur del árbol",
		["{npc:1996}: tame it with the {item:15908}"] = "{npc:1996}: domestícalo con la {item:15908}",
		["{npc:1998}: tame it with the {item:15908}"] = "{npc:1998}: domestícalo con la {item:15908}",
		["{npc:2038} waits inside the cave, at the bottom or up on the ledge; keep to the right."] = "{npc:2038} espera dentro de la cueva, abajo o arriba en la cornisa; mantente a la derecha.",
		["{npc:2043}: tame it with the {item:15908}"] = "{npc:2043}: domestícalo con la {item:15908}",
		["{npc:2077}, by the path"] = "{npc:2077}, junto al sendero",
		["{npc:2079}: a sigil for {npc:3596}"] = "{npc:2079}: un sello para {npc:3596}",
		["{npc:2080}: {quest:922} in {zone:1457} takes it"] = "{npc:2080}: {quest:922} en {zone:1457} la recibe",
		["{npc:2082}, on the tree's ramp"] = "{npc:2082}, en la rampa del árbol",
		["{npc:2151} patrols the road west of the village: if she isn't at the arrow, follow the road until you meet her."] = "{npc:2151} patrulla el camino al oeste de la aldea: si no está en la flecha, sigue el camino hasta encontrarla.",
		["{npc:2151}, on the road west of the village"] = "{npc:2151}, en el camino al oeste de la aldea",
		["{npc:265811}, by the campfire"] = "{npc:265811}, junto a la fogata",
		["{npc:265811}: for {npc:3603}, beside {npc:6286}"] = "{npc:265811}: para {npc:3603}, junto a {npc:6286}",
		["{npc:265811}: for {npc:3604}, beside {npc:6286}"] = "{npc:265811}: para {npc:3604}, junto a {npc:6286}",
		["{npc:265811}: for {npc:3605}, by the road west"] = "{npc:265811}: para {npc:3605}, junto al camino al oeste",
		["{npc:265811}: for {npc:6094} in the inn"] = "{npc:265811}: para {npc:6094} en la posada",
		["{npc:265811}: for {npc:6287}, by the road west"] = "{npc:265811}: para {npc:6287}, junto al camino al oeste",
		["{npc:272034} and {npc:272044} fly just west of the moonwell, {npc:272046} further north."] = "{npc:272034} y {npc:272044} vuelan justo al oeste del pozo de la luna; {npc:272046}, más al norte.",
		["{npc:3514}, at the top of the tree"] = "{npc:3514}, en lo alto del árbol",
		["{npc:3515}, south of the inn"] = "{npc:3515}, al sur de la posada",
		["{npc:3516}, in the {area:1658}"] = "{npc:3516}, en {area:1658}",
		["{npc:3519}, by the moonwell"] = "{npc:3519}, junto al pozo de la luna",
		["{npc:3567}: {quest:932}'s Befouled Webwoods and the elite {npc:272116}'s moss, on the walk to the {area:264}"] = "{npc:3567}: las Tejemadera corrompidas de {quest:932} y el musgo del élite {npc:272116}, de camino a {area:264}",
		["{npc:3594}, the rogue trainer"] = "{npc:3594}, el instructor de pícaros",
		["{npc:3595}, the priest trainer, on the second level of {area:256} on the way down: {npc:3600} in {area:186} takes it"] = "{npc:3595}, la instructora de sacerdotes, en el segundo nivel de {area:256} al bajar: {npc:3600} en {area:186} la recibe",
		["{npc:3596}, the hunter trainer"] = "{npc:3596}, la instructora de cazadores",
		["{npc:3597}, the druid trainer at {area:256}"] = "{npc:3597}, el instructor de druidas en {area:256}",
		["{npc:3600}: heal {npc:12429} by {area:259}"] = "{npc:3600}: cura a {npc:12429} junto a {area:259}",
		["{npc:3600}: {npc:11401} in {zone:1457} takes it"] = "{npc:3600}: {npc:11401} en {zone:1457} la recibe",
		["{npc:3602}: {npc:4217} in {zone:1457} takes it"] = "{npc:3602}: {npc:4217} en {zone:1457} la recibe",
		["{npc:3603}, beside {npc:6286}"] = "{npc:3603}, junto a {npc:6286}",
		["{npc:3604}, beside {npc:6286}"] = "{npc:3604}, junto a {npc:6286}",
		["{npc:3605}, beside {npc:6287}"] = "{npc:3605}, junto a {npc:6287}",
		["{npc:3649}, north end of the village"] = "{npc:3649}, en el extremo norte del pueblo",
		["{npc:4092}, in the Temple of the Moon"] = "{npc:4092}, en el Templo de la Luna",
		["{npc:4146} in {zone:1457} takes it"] = "{npc:4146} en {zone:1457} la recibe",
		["{npc:4146}, in the {area:1658}: {spell:5149}"] = "{npc:4146}, en {area:1658}: {spell:5149}",
		["{npc:4217}, in the {area:1658}"] = "{npc:4217}, en {area:1658}",
		["{npc:6094}, in the inn"] = "{npc:6094}, en la posada",
		["{npc:6287}, camped beside the road before Shayla"] = "{npc:6287}, acampado junto al camino antes de Shayla",
		["{npc:7999}, above {npc:4092}"] = "{npc:7999}, encima de {npc:4092}",
		["{npc:8583}, east of the tree"] = "{npc:8583}, al este del árbol",
		["{object:673378}, just west of the moonwell"] = "{object:673378}, justo al oeste del pozo de la luna",
		["{quest:917} and the antidote"] = "{quest:917} y el antídoto",
		["{quest:97979}: cast {spell:1259799} and Shadowmeld, then hand it back to {npc:3595}"] = "{quest:97979}: lanza {spell:1259799} y Fusión de las sombras, y luego entrégasela a {npc:3595}",
} end)()
t.guides["forever/alliance/nightelf/02-darkshore"] = (function() return {
		["Back north-east into the mountains to the crystal."] = "Vuelve al noreste, a las montañas, hasta el cristal.",
		["Bears and the Blackwood camp"] = "Osos y el campamento Bosque Negro",
		["Blackwood Pathfinders and Windtalkers hold the camp south-east of {area:442}."] = "Los abrecaminos y soplavientos Bosque Negro ocupan el campamento al sureste de {area:442}.",
		["Blackwood furbolgs"] = "Fúrbolgs Bosque Negro",
		["Class trainer"] = "Instructor de clase",
		["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "Sube a las montañas al este de {area:447}; el {object:175524} está en una cornisa.",
		["Fill the tube at the moonwell in the village"] = "Llena el tubo en el pozo de la luna del pueblo",
		["Follow the coast south past {area:447}: one {quest:4728} lies on the shore west of the Grove, another further south near {area:450}. Three more remains lie further south-west among Greymist Oracles and Tidehunters (18-20): the guide leaves them for the last loop, when you are closer to their level."] = "Sigue la costa hacia el sur más allá de {area:447}: un {quest:4728} yace en la orilla al oeste del Páramo de los Ancianos y otro más al sur, cerca de {area:450}. Otros tres restos yacen más al suroeste entre oráculos Brumagris y cazamareas Brumagris (18-20): la guía los deja para la última vuelta, cuando estés más cerca de su nivel.",
		["Grell Earrings"] = "Pendientes grell",
		["Highborne Relics"] = "Reliquias de Altonato",
		["Read the {object:17188}"] = "Lee {object:17188}",
		["Read the {object:17189}"] = "Lee {object:17189}",
		["The WANTED poster outside the inn"] = "El cartel de SE BUSCA fuera de la posada",
		["The beach"] = "La playa",
		["The boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street."] = "El barco atraca al oeste del pueblo. El maestro de vuelo está en la colina al sur de la posada; los asignadores de misiones están repartidos por la calle principal.",
		["The red crystal"] = "El cristal rojo",
		["The skeletal turtle"] = "La tortuga esquelética",
		["The southern beaches"] = "Las playas del sur",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Los Reptadores de marea ({npc:2232}) corretean por la orilla bajo el pueblo; {quest:983} está en la playa, justo al sur de los muelles. Los Trilladores de Costa Oscura ({npc:2185}) nadan en los bajíos. {object:175207} yace en la orilla, justo al sur del pueblo.",
		["{item:5338}: Deth'ryll Satyrs"] = "{item:5338}: sátiros Deth'ryll",
		["{npc:3639} stands at the north edge of the ruins. Cursed, Writhing and {npc:2178} haunt them; {npc:3667}'s ghost walks among them, {npc:270196} the owl circles east of them. The two tablets lie in the ruins; a {quest:4722} lies on the shore west of them."] = "{npc:3639} está en el borde norte de las ruinas. Altonatos malditos, Altonatos en pena y {npc:2178} las rondan; el fantasma de {npc:3667} camina entre ellos y la lechuza {npc:270196} vuela en círculos al este. Las dos tablillas están en las ruinas; {quest:4722} yace en la orilla al oeste de ellas.",
		["{npc:3649}, north end of the village"] = "{npc:3649}, en el extremo norte del pueblo",
} end)()
t.guides["forever/alliance/skyborne/01-zephras-isle"] = (function() return {
		["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "Usa /sit junto a la fogata de {npc:263664} hasta obtener {spell:1229451}",
		["Al'Aketh Stormchasers and Footsoldiers camp just north of {npc:257944} and drop the heirloom; the Shrieklings west of her drop the feathers and talons; the {item:265105} grows along the stream west of her."] = "Los Al'Aketh Stormchasers y Footsoldiers acampan justo al norte de {npc:257944} y sueltan la reliquia; los Shrieklings al oeste de ella sueltan las plumas y garras; el {item:265105} crece junto al arroyo al oeste de ella.",
		["Back in {quest:92529}: Stormcallers and {npc:251662} fill the village, the Stormcallers carry the stolen supplies, and {npc:251966} stands at its south end."] = "De vuelta en {quest:92529}: Stormcallers y {npc:251662} llenan el pueblo, los Stormcallers llevan los suministros robados y {npc:251966} está en el extremo sur.",
		["Back to the Hermit"] = "Regresa con el ermitaño",
		["Back to {area:16622}"] = "Regresa a {area:16622}",
		["Bandit Highwaymen"] = "Bandit Highwaymen",
		["Below ground"] = "Bajo tierra",
		["Bolvar Fordragon stands in the throne room of {object:2117}, at the north end of the city. Then leave by the main gate for {zone:1436}."] = "Bolvar Fordragon está en la sala del trono de {object:2117}, en el extremo norte de la ciudad. Luego sal por la puerta principal hacia {zone:1436}.",
		["Cast {spell:1259705} at the {object:460002}"] = "Usa tu habilidad racial {spell:1259705} en la línea ley",
		["Class trainer"] = "Instructor de clase",
		["Desperate times"] = "Tiempos desesperados",
		["Fight north to the {area:16629}. Guardians, Spiritcallers and Blademasters hold the approach; {npc:253576} waits at the shrine's door, {npc:253590} inside the inner sanctum."] = "Ábrete paso al norte hasta {area:16629}. Guardians, Spiritcallers y Blademasters defienden el acceso; {npc:253576} espera en la puerta del santuario, y {npc:253590} en el sagrario interior.",
		["Find {npc:258130}"] = "Encuentra a {npc:258130}",
		["Follow the road south to {area:16624}. {npc:263664} camps by the fire west of the village; {npc:251523} and {npc:251903} stand in its middle."] = "Sigue el camino al sur hasta {area:16624}. {npc:263664} acampa junto a la fogata al oeste del pueblo; {npc:251523} y {npc:251903} están en el centro.",
		["For {npc:234} at {area:108}"] = "Para {npc:234} en {area:108}",
		["Head north into {area:16631}. {npc:257944} camps in its east."] = "Ve al norte, a {area:16631}. {npc:257944} acampa en el este.",
		["Heal the injured druids in the Nightfang Den"] = "Cura a los druidas heridos de la guarida (Nightfang Den)",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Sal de {zone:1453} por la puerta principal. La cascada de {quest:1861} está al suroeste de las puertas, de camino al oeste hacia {zone:1436}: llena el {item:7207} en su base.",
		["Level 4 spells"] = "Hechizos de nivel 4",
		["Listen to {npc:252448}'s story"] = "Escucha la historia de {npc:252448}",
		["Listen to {npc:257554}"] = "Escucha a {npc:257554}",
		["North of the cones: the Wind Hollows drift around the refugees' camp, the {item:266433} lie between the tents, and {npc:259013} lies at its north end."] = "Al norte de las piñas: los Wind Hollows flotan alrededor del campamento de refugiados, {item:266433} están entre las tiendas y {npc:259013} yace en el extremo norte.",
		["Prideclaws and Galestriders"] = "Leozarpas y zancavientos",
		["Raw Windstones and the {npc:251404}"] = "Piedras de viento en bruto y {npc:251404}",
		["Ripe Stormapples and Hungry Bandits are in the orchard by the farm, {quest:92683} in the fields north-east of it, Ornery Galestriders all around. The {npc:250929} stands in the field north-east of the farm."] = "Las Tormanzanas maduras y los Hungry Bandits están en el huerto junto a la granja, {quest:92683} en los campos al noreste, y Ornery Galestriders por todas partes. {npc:250929} está en el campo al noreste de la granja.",
		["Search the dead cultist"] = "Registra al cultista muerto",
		["Search the wardrobe"] = "Registra el ropero",
		["Shen'dar turn-ins"] = "Entregas en Shen'dar",
		["Skyhoppers"] = "Skyhoppers",
		["Skyhoppers swarm the fields west of {area:16638}."] = "Los Skyhoppers infestan los campos al oeste de {area:16638}.",
		["Standing our ground"] = "Resistir",
		["Tame it with the {item:15908}"] = "Domestícalo con la {item:15908}",
		["Tell {npc:252800} you're ready"] = "Dile a {npc:252800} que estás listo",
		["The Bandit Highwaymen hold the hills north of the farm."] = "Los Bandit Highwaymen ocupan las colinas al norte de la granja.",
		["The Highlands Bandits camp north-east of the village. \"Badwind\" Bennic waits at the far north end of their camp."] = "Los Highlands Bandits acampan al noreste del pueblo. \"Badwind\" Bennic espera en el extremo norte de su campamento.",
		["The Raw Windstones glitter on the ground just south of the grove. {quest:92463} hovers over the meadow further east, on the way to {npc:249363}."] = "Las Piedras de viento en bruto brillan en el suelo justo al sur de la arboleda. {quest:92463} flota sobre la pradera más al este, de camino a {npc:249363}.",
		["The Windstone Formations"] = "Las Windstone Formations",
		["The Windstone Formations stand on the rise west of Fillion's camp."] = "Las Windstone Formations están en la loma al oeste del campamento de Fillion.",
		["The bounty board"] = "El tablón de recompensas",
		["The class trainers stand together in the grove"] = "Los instructores de clase están juntos en la arboleda",
		["The dead cultist"] = "El cultista muerto",
		["The eastern watchtower"] = "La atalaya oriental",
		["The missing scholar"] = "El erudito desaparecido",
		["The road to {area:16638}"] = "El camino a {area:16638}",
		["The {area:16629}"] = "{area:16629}",
		["The {item:254871}"] = "La {item:254871}",
		["The {object:581822}"] = "La {object:581822}",
		["Upstairs"] = "Arriba",
		["Village quests"] = "Misiones del pueblo",
		["With a profession learned, {npc:263664} also offers its Camping 101, which its trainer in {area:16624} takes on the village round."] = "Con una profesión aprendida, {npc:263664} también ofrece su Campismo 101, que su instructor en {area:16624} acepta durante la ronda por el pueblo.",
		["You wake in {area:16622}. {npc:251362} stands beside you; {npc:251361} is a few steps west, {npc:251368} by the south edge of the grove."] = "Despiertas en {area:16622}. {npc:251362} está a tu lado; {npc:251361} está a unos pasos al oeste, y {npc:251368} junto al borde sur de la arboleda.",
		["{area:16622} turn-ins"] = "Entregas en {area:16622}",
		["{area:16624} again"] = "{area:16624} otra vez",
		["{area:16638} turn-ins"] = "Entregas en {area:16638}",
		["{area:16638}, the fate of Zephras"] = "{area:16638}, el destino de Zephras",
		["{area:16638}, the turncoat"] = "{area:16638}, el traidor",
		["{npc:249363} keeps watch east of the grove. The {npc:251143} and Al'Aketh Converts gather just north of her; the {object:460002} rises further north: cast your {spell:1259705} racial ability at it."] = "{npc:249363} vigila al este de la arboleda. {npc:251143} y los Conversos Al'Aketh ({npc:251160}) se reúnen justo al norte de ella; la línea ley se alza más al norte: usa en ella tu habilidad racial {spell:1259705}.",
		["{npc:250873} and Pesky Cirrusflies roam the meadow just south-east of the grove."] = "{npc:250873} y Cirrovuelos molestos rondan la pradera justo al sureste de la arboleda.",
		["{npc:251361}: a note from your trainer"] = "{npc:251361}: una nota de tu instructor",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361}: lee la {item:9547}",
		["{npc:251361}: the {item:4100}"] = "{npc:251361}: la {item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "{npc:251373}, el instructor de druidas, en la planta baja del árbol detrás de {npc:251361}",
		["{npc:251379}, the mage trainer: read the {item:282416} first"] = "{npc:251379}, la instructora de magos: primero lee el {item:282416}",
		["{npc:251389}, in the watchtower"] = "{npc:251389}, en la atalaya",
		["{npc:251913}, beside {npc:251991}"] = "{npc:251913}, junto a {npc:251991}",
		["{npc:251964}, in the watchtower"] = "{npc:251964}, en la atalaya",
		["{npc:251992}, on the south edge of the village"] = "{npc:251992}, en el borde sur del pueblo",
		["{npc:252155} holds the western watch, south-west of Falaath. {npc:256966} and the fallen guards lie just south of her."] = "{npc:252155} defiende la guardia occidental, al suroeste de Falaath. {npc:256966} y los guardias caídos yacen justo al sur de ella.",
		["{npc:252373}, the mage trainer"] = "{npc:252373}, el instructor de magos",
		["{npc:252378} holds the watchtower north of {area:16638}. The Al'Aketh camp is just west of the tower, its healers around 65,68 and 65,65; {npc:252666} stands at its north end. The Al'Aketh there drop Windstone Charms."] = "{npc:252378} defiende la atalaya al norte de {area:16638}. El campamento Al'Aketh está justo al oeste de la torre, con sus sanadores cerca de 65,68 y 65,65; {npc:252666} está en el extremo norte. Los Al'Aketh de ahí sueltan Talismanes de piedra de viento Al'Aketh.",
		["{npc:252383} and {npc:252476} stand at the north end of {area:16638}, {npc:252475} and {npc:253204} at the south end."] = "{npc:252383} y {npc:252476} están en el extremo norte de {area:16638}; {npc:252475} y {npc:253204}, en el extremo sur.",
		["{npc:252475}: {npc:259084} waits by the Skyborne portal"] = "{npc:252475}: {npc:259084} espera junto al portal Cielonato",
		["{npc:252800} again"] = "{npc:252800} otra vez",
		["{npc:252800} runs the farm in the south-west lowlands."] = "{npc:252800} lleva la granja en las tierras bajas del suroeste.",
		["{npc:254589} lurks in the hills south-west of the village, on the way back. {npc:254589} is elite: grouping up is advised."] = "{npc:254589} acecha en las colinas al suroeste del pueblo, de regreso. {npc:254589} es élite: se recomienda ir en grupo.",
		["{npc:257018}, at the south side of the village"] = "{npc:257018}, en el lado sur del pueblo",
		["{npc:257019}, west of {npc:251905}"] = "{npc:257019}, al oeste de {npc:251905}",
		["{npc:257022}, beside {npc:251993}"] = "{npc:257022}, junto a {npc:251993}",
		["{npc:257065} waits at the entrance to {quest:92529}, south of Shen'dar. The {spell:1254832} lets you walk in among the faithful."] = "{npc:257065} espera en la entrada de {quest:92529}, al sur de Shen'dar. {spell:1254832} te permite entrar entre los fieles.",
		["{npc:257944} again"] = "{npc:257944} otra vez",
		["{npc:257944}, the missive"] = "{npc:257944}, la misiva",
		["{npc:258443}, in the highlands south-west of the cultist"] = "{npc:258443}, en las tierras altas al suroeste del cultista",
		["{npc:263664}: for {npc:251913}"] = "{npc:263664}: para {npc:251913}",
		["{npc:263664}: for {npc:251991}"] = "{npc:263664}: para {npc:251991}",
		["{npc:263664}: for {npc:251992}"] = "{npc:263664}: para {npc:251992}",
