} end)()
t.guides["forever/class/warlock/shard-of-the-green-flame"] = (function() return {
		["A rare off-hand for your 50s from {npc:14469} and {npc:14470} in {zone:1448}, the camp that also offers An Imp's Request."] = "Un objeto de mano izquierda raro para tus 50 de {npc:14469} y {npc:14470} en {zone:1448}, el campamento que también ofrece Pedido de un diablillo.",
		["Back to {npc:14469}"] = "Regresa con {npc:14469}",
		["{area:1763} lies just south of {area:1997}, west of the road. The guide waits for level 53 first: its Legionnaires are 55. Of its two caves, {area:1770} is the northern one, further up the hill; the other has no Legionnaires. {area:1770}'s tunnels run north under the hills, and the Jaedenar Legionnaires (level 55) stand in its deeper halls, from the first ramps on toward {npc:9516}'s chamber; they Uppercut anyone in melee. Three kills in four give the essence, but only about eleven spawn: clear your way in and wait out a five-minute respawn if you must. The cultists of {area:1763} and {area:1770} are all hostile."] = "{area:1763} está justo al sur de {area:1997}, al oeste del camino. La guía espera primero al nivel 53: sus Legionarios son de nivel 55. De sus dos cuevas, {area:1770} es la del norte, más arriba en la colina; la otra no tiene Legionarios. Los túneles de {area:1770} van hacia el norte bajo las colinas, y los Legionarios Jaedenar (nivel 55) están en sus salas más profundas, desde las primeras rampas hasta la cámara de {npc:9516}; usan Gancho contra quien esté cuerpo a cuerpo. Tres de cada cuatro muertes dan la esencia, pero solo aparecen unos once: abre camino hacia adentro y espera a que reaparezcan (cinco minutos) si hace falta. Todos los sectarios de {area:1763} y {area:1770} son hostiles.",
		["{item:18626}, at {object:179677}"] = "{item:18626}, en {object:179677}",
} end)()
t.guides["forever/class/warlock/tome-of-sacrifice"] = (function() return {
		["A rare off-hand at 60, {npc:14463}'s payment for capturing a {npc:12396} in the {zone:1419}."] = "Una pieza rara de mano izquierda a nivel 60, el pago de {npc:14463} por capturar a un {npc:12396} en {zone:1419}.",
		["Back to {npc:14463}"] = "Vuelve con {npc:14463}",
} end)()
t.guides["forever/class/warrior/brutal-armor"] = (function() return {
		["At 20, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6394} in {area:378}."] = "A nivel 20, {npc:3041}, el instructor de guerreros de {zone:1456}, te manda con {npc:6394} en {area:378}.",
		["At 20, {npc:3354} in the {object:172958} sends you to {npc:6394} in {area:378}."] = "A nivel 20, {npc:3354} en {object:172958} te manda con {npc:6394} en {area:378}.",
		["At 20, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6394} in {area:378}."] = "A nivel 20, {npc:4595}, un instructor de guerreros de {zone:1458}, te manda con {npc:6394} en {area:378}.",
		["Hillsbrad Miners"] = "Mineros de Trabalomas ({npc:2269})",
		["Iron Bars"] = "Barras de hierro",
		["Iron Bars: {npc:8673}"] = "Barras de hierro: {npc:8673}",
		["Roogug in {area:1717}"] = "Roogug en {area:1717}",
		["Roogug is an elite quilboar (level 28) inside {area:1717}, the dungeon at the south end of the {zone:1413}; a five-player dungeon: needs a group of five, his guards come with him. The guide waits for level 26 first. Inside take the left path at the first fork, cross the vine bridge over the pig pens, go past the room with the big cauldron: he waits in the room on the right. He casts {spell:403} and calls Earth Rumblers. The vial always drops."] = "Roogug es un jabaespín élite (nivel 28) dentro de {area:1717}, el calabozo del extremo sur de {zone:1413}; un calabozo para cinco jugadores: requiere un grupo de cinco, sus guardias vienen con él. La guía espera primero al nivel 26. Adentro, toma el camino de la izquierda en la primera bifurcación, cruza el puente de lianas sobre los chiqueros y pasa la sala del gran caldero: espera en la sala de la derecha. Lanza {spell:403} e invoca estruendores de tierra. El vial siempre cae.",
		["The Dragonmaw orcs (level 26-30) camp in the middle of the {zone:1437}; from {area:321} in Arathi head south over the {area:881} ({area:150} is Alliance). With {quest:1846} from {npc:6411} in your log, every Raider, Swamprunner, Centurion, Shadowwarder and Bonewarder drops a {item:7131} (without the quest they drop none): right-click it to test it, and about one in four comes out sturdy, the rest break, so expect 30 or more kills for 8. You can test while moving or fighting. The orcs run for help at 15%; Raiders net you, Centurions shield-bash, Shadowwarders cast {spell:686}, Bonewarders raise skeletons."] = "Los orcos Faucedraco (nivel 26-30) acampan en medio de {zone:1437}; desde {area:321} en Arathi, ve al sur por {area:881} ({area:150} es de la Alianza). Con {quest:1846} de {npc:6411} en tu registro, cada Asaltante, Correpantanos, Centurión, Depositario de sombras y Guardahuesos suelta una {item:7131} (sin la misión no sueltan ninguna): haz clic derecho en ella para probarla; más o menos una de cada cuatro sale robusta y las demás se rompen, así que cuenta con 30 muertes o más para conseguir 8. Puedes probarlas mientras te mueves o peleas. Los orcos huyen en busca de ayuda al 15%; los Asaltantes te lanzan redes, los Centuriones golpean con el escudo, los Depositarios de sombras lanzan {spell:686} y los Guardahuesos alzan esqueletos.",
		["You need 10 {item:7127}. The guide waits for level 25 first. The Hillsbrad Miners (level 26-27) work the mine in the hills west of {area:271} and drop the azurite four kills in five; they fight in {spell:71}, sunder your armor and run for help at 30% health. Fly to {area:272} and head south-west."] = "Necesitas 10 {item:7127}. La guía espera primero al nivel 25. Los Mineros de Trabalomas (nivel 26-27) trabajan en la mina de las colinas al oeste de {area:271} y sueltan la azurita en cuatro de cada cinco muertes; pelean en {spell:71}, te hienden la armadura y huyen en busca de ayuda al 30% de salud. Vuela a {area:272} y dirígete al suroeste.",
		["{item:6841}, from Roogug"] = "{item:6841}, de Roogug",
} end)()
t.guides["forever/class/warrior/fire-hardened-armor"] = (function() return {
		["At 20, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {quest:1698} in Redridge."] = "A nivel 20, {npc:5113}, el instructor de guerreros de {zone:1455}, te envía con {quest:1698} en las Montañas Crestagrana.",
		["At 20, {npc:7315}, the warrior trainer of {zone:1457}, sends you to {quest:1698} in Redridge."] = "A nivel 20, {npc:7315}, el instructor de guerreros de {zone:1457}, te envía con {quest:1698} en las Montañas Crestagrana.",
		["Charred and Galvanized Horns"] = "Cuernos carbonizados y galvanizados",
		["Enter the {area:98} and come back"] = "Entra en {area:98} y vuelve",
		["Fire Hardened Armor"] = "Armadura endurecida al fuego",
		["Roogug in {area:1717}"] = "Roogug en {area:1717}",
		["Scorched Spider Fangs"] = "Colmillos de araña agostados",
		["The Nightbane worgen of {zone:1431} (Dark Runners, Vile Fangs, Shadow Weavers, Worgen and Tainted Ones, level 26-31) south and west of {area:42} drop the {quest:1705} four kills in five. The Tainted Ones poison and howl; Vile Fangs cause {spell:3427}."] = "Los huargen Penumbría de {zone:1431} (Sombracechadores, Colmilloviles, Tejesombras, Huargen y Corruptos, nivel 26-31) al sur y al oeste de {area:42} sueltan la {quest:1705} en cuatro de cada cinco muertes. Los Corruptos envenenan y aúllan; los Colmilloviles causan {spell:3427}.",
		["The chimaeras live south-west of {area:460} in the {area:465}; the guide waits for level 26 first. You need 12 Charred Horns from the Fledgling (level 25-27) and Young Chimaeras (23-25), four kills in five, and the {item:6840} from the {npc:6167} (28, the big one), also four in five. Only three Fledglings, two Young and one Matriarch live there, each back in 5 minutes, so expect to wait. Fledglings and the Matriarch spit {spell:3396}, the Young cast {spell:403}. Alliance: fly to {area:467} and head south."] = "Las quimeras viven al suroeste de {area:460}, en {area:465}; la guía espera primero al nivel 26. Necesitas 12 Cuernos carbonizados de las Quimeras volantonas (nivel 25-27) y las Quimeras jóvenes (23-25), en cuatro de cada cinco muertes, y el {item:6840} de la {npc:6167} (28, la grande), también en cuatro de cada cinco. Ahí solo viven tres volantonas, dos jóvenes y una matriarca, y cada una vuelve en 5 minutos, así que prepárate para esperar. Las volantonas y la matriarca escupen {spell:3396}; las jóvenes lanzan {spell:403}. Alianza: vuela a {area:467} y dirígete al sur.",
		["{item:6841}, from Roogug"] = "{item:6841}, de Roogug",
		["{npc:6170} (level 32, not elite) carries the {item:6845}, four kills in five; the guide waits for level 30 first. He walks between the inside and the mouth of the {area:2161} mine south-east of {area:42}, so wait at the entrance and pull him outside. He poisons and howls."] = "{npc:6170} (nivel 32, no élite) lleva la {item:6845}, en cuatro de cada cinco muertes; la guía espera primero al nivel 30. Camina entre el interior y la boca de la mina de {area:2161}, al sureste de {area:42}, así que espera en la entrada y atráelo afuera. Envenena y aúlla.",
} end)()
