		["{npc:4949}: {quest:93739}, a tour of the Horde's leaders"] = "{npc:4949}: {quest:93739}, un recorrido por los líderes de la Horda",
		["{npc:7088}, the skinning trainer, stands in the {object:172958}."] = "{npc:7088}, el instructor de desuello, está en {object:172958}.",
		["{npc:7088}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:7088}: Campamento 101, de la fogata de Brakk en {zone:1411}",
		["{quest:264} is handed in at {object:24776}, a grave a few steps south of the crypt entrance, not to a person."] = "{quest:264} se entrega en {object:24776}, una tumba a pocos pasos al sur de la entrada de la cripta, no a una persona.",
} end)()
t.guides["forever/horde/04-the-barrens"] = (function() return {
		["Bael'dun fortress"] = "Fortaleza de Bael'dun",
		["East along the road from {area:2539} to {npc:4049}'s camp, on the way to {area:378}."] = "Al este por el camino desde {area:2539} hasta el campamento de {npc:4049}, camino a {area:378}.",
		["Fly to the Crossroads from the wind rider master: {npc:2995} on {zone:1456}'s central rise."] = "Vuela a El Cruce desde el maestro de jinetes del viento: {npc:2995}, en la meseta central de {zone:1456}.",
		["Fly to {area:1638}"] = "Vuela a {area:1638}",
		["Fly to {area:1638} first: two of its elders give quests worked on this guide's and the next guide's walks."] = "Vuela primero a {area:1638}: dos de sus ancianos dan misiones que se completan en los recorridos de esta guía y de la siguiente.",
		["Fly to {area:378}"] = "Vuela a {area:378}",
		["Fly to {area:392}"] = "Vuela a {area:392}",
		["Follow the road north toward {area:467}. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there."] = "Sigue el camino al norte hacia {area:467}. Los trotadores cornamentados pastan por el camino; las bestias de savia, los corredores Crepusculares y los dragones hada deambulan por el bosque bajo el Pico, y los druidas Cenarion ocupan la arboleda de allí.",
		["Follow the road west past Regthar's bunkers and {npc:4049}'s camp into Stonetalon: {npc:3995} waits below ground in {area:2539}, at the foot of the {area:1076}."] = "Sigue el camino al oeste pasando los búnkeres de Regthar y el campamento de {npc:4049} hacia Sierra Espolón: {npc:3995} espera bajo tierra en {area:2539}, al pie de {area:1076}.",
		["Follow the road west past Regthar's bunkers: {npc:4049} camps beside it at the edge of Stonetalon."] = "Sigue el camino al oeste pasando los búnkeres de Regthar: {npc:4049} acampa junto a él, en el borde de Sierra Espolón.",
		["From {area:2539} follow the road east to {npc:4049}'s camp, then south-east across the plains to {area:378}."] = "Desde {area:2539} sigue el camino al este hasta el campamento de {npc:4049} y luego al sureste a través de las llanuras hasta {area:378}.",
		["From {area:378} follow the road west through the gate into {zone:1412}, then north past {area:222} to {zone:1456}; a lift at the foot of the bluffs takes you up."] = "Desde {area:378} sigue el camino al oeste por la puerta hacia {zone:1412}, luego al norte pasando {area:222} hasta {zone:1456}; un elevador al pie de las mesetas te sube.",
		["Gaea Dirt Mounds"] = "Túmulos de Gaia",
		["Gaea Seeds"] = "Semillas de Gaia",
		["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south."] = "Al suroeste del Refugio Roca del Sol está {area:465}, quemada. Planta las semillas de Gaia ({item:16205}) en los montones de tierra del fondo del valle; los elementales de fuego sueltan {item:16312}. Las arpías y emboscadoras Furia Sangrienta anidan en el lado norte; las destripadoras y malaplumas, al sur.",
		["The dwarves' flying machine sits on its platform inside the dig site. Use the {item:5021} that {npc:3341} gave you on it."] = "La máquina voladora de los enanos está en su plataforma dentro de la excavación. Usa en ella {item:5021} que te dio {npc:3341}.",
		["The flying machine"] = "La máquina voladora",
		["The road west past {npc:4049}'s camp"] = "El camino al oeste pasando el campamento de {npc:4049}",
		["The {area:1718}"] = "{area:1718}",
		["The {object:667362} grows on the bottom of {area:464}, off the same southern shore: dive to the plants and the Dried Mirkweed Piles; both give pods. Watch your breath."] = "{object:667362} crece en el fondo de {area:464}, frente a la misma orilla sur: bucea hasta las plantas y los montones de hierba seca; ambos dan vainas. Cuida tu respiración.",
		["To {zone:1456}"] = "A {zone:1456}",
		["Up the {area:1076} past {npc:4201} and west to {area:460}; coming from {npc:4073}, back west past Ziz's hut."] = "Sube por {area:1076} pasando a {npc:4201} y al oeste hasta {area:460}; si vienes de {npc:4073}, regresa al oeste pasando la choza de Ziz.",
		["Up the {area:1076} to {npc:4201}' hut, then east along the road toward {area:461}: {npc:4074} patrols the road just east of the fork, {npc:4073} the slopes further north-east below the crag. Both are lone shredder robots; they roam, so follow the road until you meet them."] = "Sube por {area:1076} hasta la choza de {npc:4201}, luego al este por el camino hacia {area:461}: {npc:4074} patrulla el camino justo al este de la bifurcación, y {npc:4073}, las laderas más al noreste bajo el risco. Ambos son robots machacadores solitarios; deambulan, así que sigue el camino hasta encontrarlos.",
		["{item:277936}, from any Bloodfury harpy"] = "{item:277936}, de cualquier arpía Furia Sangrienta",
		["{npc:10079}, at the top of the lift"] = "{npc:10079}, en lo alto del elevador",
		["{npc:11860}: Glittering Sunstones from the Bloodfury harpies"] = "{npc:11860}: piedrasoles relumbrantes de las arpías Furia Sangrienta",
		["{npc:11861}, beside {npc:11862}"] = "{npc:11861}, junto a {npc:11862}",
		["{npc:11862}, up on the ledge"] = "{npc:11862}, arriba en la cornisa",
		["{npc:11864} stands by the bonfire inside Sun Rock: Makaba's news that Kaya is alive is for her."] = "{npc:11864} está junto a la hoguera dentro del Refugio Roca del Sol: la noticia de Makaba de que Kaya está viva es para ella.",
		["{npc:14242}, up in the tree just east of {npc:3341}"] = "{npc:14242}, arriba en el árbol justo al este de {npc:3341}",
		["{npc:2995}, the wind rider master, stands on the central rise: take his flight path if you don't have it. {npc:3024} and {npc:4721} stand a short walk east of him."] = "{npc:2995}, el maestro de jinetes del viento, está en la meseta central: consigue su ruta de vuelo si no la tienes. {npc:3024} y {npc:4721} están a poca distancia al este de él.",
		["{npc:3024}: the {object:667362} grows in {area:464}, by Sun Rock"] = "{npc:3024}: {object:667362} crece en {area:464}, junto a Roca del Sol",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}, en lo alto de la torre",
		["{npc:3430}, in the cage"] = "{npc:3430}, en la jaula",
		["{npc:3433}, at the north edge of the camp"] = "{npc:3433}, en el borde norte del campamento",
		["{npc:3442} stands beside the flight master you land at."] = "{npc:3442} está junto al maestro de vuelo donde aterrizas.",
		["{npc:3442}: {quest:1094}, from {npc:4201}"] = "{npc:3442}: {quest:1094}, de {npc:4201}",
		["{npc:4049}: {npc:4074} and {npc:4073} roam east of {npc:4201}, on the way up"] = "{npc:4049}: {npc:4074} y {npc:4073} deambulan al este de {npc:4201}, de subida",
		["{npc:4198}'s next quest, Ordanus, is on the Alliance side of {zone:1440}. Skip it."] = "La siguiente misión de {npc:4198}, Ordanus, está en el lado de la Alianza de {zone:1440}. Omítela.",
		["{npc:4198}, outside the gate"] = "{npc:4198}, fuera de la puerta",
		["{npc:4721}: the phial comes from {zone:1440}, next guide"] = "{npc:4721}: el vial viene de {zone:1440}, en la siguiente guía",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}, on the way to {area:359}."] = "La choza de {npc:5899} está en la cresta sobre el abrevadero de los jabaespines, al sur de {area:378}, camino a {area:359}.",
		["{npc:5899}: the blue waterskin is filled in {zone:1440}, next guide"] = "{npc:5899}: el odre azul se llena en {zone:1440}, en la siguiente guía",
		["{npc:5899}: the red waterskin from {area:272}"] = "{npc:5899}: el odre rojo de {area:272}",
		["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "{quest:873}, un gran trillanodonte, nada en las aguas poco profundas frente a {area:391}, al este de {npc:3388}.",
		["{zone:1454} flight master"] = "Maestro de vuelo de {zone:1454}",
		["{zone:1456} first: two of its elders give quests worked on this guide's and the next guide's walks. Fly to {area:378}; from there it is a walk west into {zone:1412} and north to the bluffs."] = "Primero {zone:1456}: dos de sus ancianos dan misiones que se completan en los recorridos de esta guía y de la siguiente. Vuela a {area:378}; desde ahí se camina al oeste hacia {zone:1412} y al norte hasta las mesetas.",
		["{zone:1456}'s central rise"] = "La meseta central de {zone:1456}",
} end)()
t.guides["forever/horde/05-stonetalon-mountains"] = (function() return {
		["Back on the road south. Where it turns east into {area:287}, {npc:2214} waits at {area:285}."] = "De vuelta en el camino al sur. Donde gira al este hacia {area:287}, {npc:2214} espera en {area:285}.",
		["Below ground"] = "Bajo tierra",
		["Down the road through Silverpine to the {area:228}: from the zeppelin towers, south through Tirisfal; from the {object:177790}, south-east from the coast to the road. {npc:2121} and {npc:1937} stand by the crypt entrance."] = "Baja por el camino a través de Bosque de Argénteos hasta {area:228}: desde las torres de zepelín, al sur a través de Tirisfal; desde {object:177790}, al sureste desde la costa hasta el camino. {npc:2121} y {npc:1937} están junto a la entrada de la cripta.",
		["Every Wrathtail naga along the strand north of the outpost drops heads."] = "Todos los nagas Colafuria de la playa al norte del puesto sueltan cabezas.",
		["Fly to {area:1637}"] = "Vuela a {area:1637}",
		["From Seereth's camp head north-east across the {zone:1413} to the road north of the Crossroads; Rogues coming from Fizzule's tower head west to it. {npc:8582} stands on the watch tower of the {area:1703} where the road enters {zone:1440}."] = "Desde el campamento de Seereth, dirígete al noreste a través de {zone:1413} hasta el camino al norte del Cruce; los pícaros que vienen de la torre de Fizzule van al oeste hasta él. {npc:8582} está en la atalaya de {area:1703}, donde el camino entra en {zone:1440}.",
		["Naga brazier"] = "Brasero naga",
		["Naga heads"] = "Cabezas de naga",
		["Out of the inn to the {area:431} flight master and fly to {area:1637}."] = "Sal de la posada hacia el maestro de vuelo de {area:431} y vuela a {area:1637}.",
		["Steer {npc:267214}'s {npc:271181} out of the ravine to the main road within four minutes; if the channel breaks, ask {npc:267214} again."] = "Guía el {npc:271181} de {npc:267214} fuera del barranco hasta el camino principal en menos de cuatro minutos; si se rompe la canalización, vuelve a pedírselo a {npc:267214}.",
		["Thistlefur Hold"] = "Bastión Piel de Cardo",
		["{area:431} is just north up the road. Coming in from the south, the flight master and {npc:12696}'s hunt board at {area:428} come first, then the vendors. {npc:12867} at the lumber camp offers Ashenvale Outrunners: leave it for the next {zone:1440} visit, at 26."] = "{area:431} está justo al norte, subiendo por el camino. Entrando desde el sur, primero están el maestro de vuelo y el tablón de caza de {npc:12696} en {area:428}, y luego los mercaderes. {npc:12867}, en el aserradero, ofrece “Avanzada de Vallefresno”: déjala para la próxima visita a {zone:1440}, a nivel 26.",
		["{item:271343}, from a {npc:1973}"] = "{item:271343}, de un {npc:1973}",
		["{npc:2214}: Darthalia in {area:272}"] = "{npc:2214}: Darthalia en {area:272}",
		["{npc:2391} in {area:272} teaches Poisons: keep it"] = "{npc:2391}, en {area:272}, enseña Venenos: guárdala",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152} entrena a los paladines en {area:159}, a poca distancia al norte por el camino desde las torres de zepelín. Regresa por el mismo camino para ir a Bosque de Argénteos.",
		["{npc:271181}, on the road"] = "{npc:271181}, en el camino",
		["{npc:5875} stands in the {object:172960}. Use {item:6626} on the summoning circle there and defeat the succubus to bind her."] = "{npc:5875} está en {object:172960}. Usa {item:6626} en el círculo de invocación de ahí y derrota a la súcubo para vincularla.",
		["{npc:6389} stands just west of the crypt entrance: hand him {item:16210} from the {zone:1458}."] = "{npc:6389} está justo al oeste de la entrada de la cripta: entrégale {item:16210} de {zone:1458}.",
} end)()
t.guides["forever/horde/06-hillsbrad-foothills"] = (function() return {
		["Back to {area:272}"] = "De vuelta a {area:272}",
		["Bears, creepers and lions"] = "Osos, trepamusgos y leones",
		["Drull and {npc:2238} are chained inside {area:275}'s courtyard buildings. Their locks need keys: {npc:2427} carries the {item:3467} and {npc:2428} the {item:3499}, both in the keep. Kill them, then open both locks.\nFrom {area:272} go south-east into the hills on the way to {area:275}. Rogues and Watchmen hold the camps along the way."] = "Drull y {npc:2238} están encadenados en los edificios del patio de {area:275}. Sus candados necesitan llaves: {npc:2427} lleva la {item:3467} y {npc:2428}, la {item:3499}, ambos en la fortaleza. Mátalos y luego abre ambos candados.\nDesde {area:272} ve al sureste por las colinas camino a {area:275}. Pícaros y Veladores ocupan los campamentos del camino.",
		["Drull's ball and chain"] = "Bola y cadena de Drull",
		["Fill the {item:7768} at the {object:107045} beside the inn"] = "Llena el {item:7768} en el {object:107045} junto a la posada",
		["Fly to the {area:1497}"] = "Vuela a {area:1497}",
		["Just south of Masoj, the {item:3502} grow on the hillsides above the river."] = "Justo al sur de Masoj, las {item:3502} crecen en las laderas sobre el río.",
		["Keep it: the {area:287} coast, later on the route"] = "Guárdala: la costa de {area:287}, más adelante en la ruta",
		["Masoj hides on the hillside above {area:290}, south-west of Durnholde, on the way down to the blossoms."] = "Masoj se esconde en la ladera sobre {area:290}, al suroeste del Castillo de Durnholde, camino abajo hacia las flores.",
		["Masoj wants an Apothecary Vial placed on three peaks. The southern one is the hilltop above {area:290}, south-east of the blossoms: use a vial at the top."] = "Masoj quiere que coloques un Vial de boticario en tres cumbres. La del sur es la cima de la colina sobre {area:290}, al sureste de las flores: usa un vial en lo alto.",
		["The farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere. {npc:2451} tends the field south of the farms."] = "Las granjas al este del pueblo de {area:287}. {npc:232} trabaja el campo junto a la granja del norte; {npc:2403}, el que está más al sureste; hay Mozos de labranza y Granjeros por todas partes. {npc:2451} cuida el campo al sur de las granjas.",
		["The smithy"] = "La herrería",
		["The smithy stands in the middle of {area:287} town. {npc:2404} and his apprentices work at the forge; the {object:1736} is stacked beside it. {npc:2449} walks the street north of it."] = "La herrería está en el centro del pueblo de {area:287}. {npc:2404} y sus aprendices trabajan en la forja; el {object:1736} está apilado al lado. {npc:2449} camina por la calle al norte.",
		["The {object:556670} poster by the inn"] = "El cartel de {object:556670} junto a la posada",
		["Train with {npc:3033}. Before you fly on, {npc:3024} and {npc:4721}, a short walk east of the wind rider master, give two quests worked on the next guides' walks; then fly on to the Crossroads, where the next guide starts."] = "Entrena con {npc:3033}. Antes de seguir volando, {npc:3024} y {npc:4721}, a poca distancia al este del maestro de jinetes del viento, te dan dos misiones que se hacen durante los recorridos de las próximas guías; luego vuela al Cruce, donde empieza la siguiente guía.",
		["West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop {item:3477} rarely; you need only one."] = "Al oeste de Molino Tarren, Osos grises ({npc:2351}), Trepamusgos del bosque ({npc:2350}) y Leones de montaña famélicos ({npc:2384}) recorren las colinas camino a las granjas. Los trepamusgos sueltan {item:3477} rara vez; solo necesitas uno.",
		["Zeppelin to {zone:1454}"] = "Zepelín a {zone:1454}",
		["{area:272} is your base for this guide: the hearth brings you back here twice. Everyone stands around the town square."] = "{area:272} es tu base en esta guía: la piedra de hogar te trae de vuelta aquí dos veces. Todos están alrededor de la plaza del pueblo.",
		["{item:15885}: use a half at the {area:2362}"] = "{item:15885}: usa una mitad en {area:2362}",
		["{item:3692}: the Peasants in the fields"] = "{item:3692}: los campesinos de los campos",
		["{npc:11798} in {area:2361} flies druids there"] = "{npc:11798}, en {area:2361}, lleva volando a los druidas ahí",
		["{npc:2055}, in the Apothecarium"] = "{npc:2055}, en la botica real",
		["{npc:2055}, in the {zone:1458}"] = "{npc:2055}, en {zone:1458}",
		["{npc:2215}: orders for {npc:270438}, on the way to Durnholde"] = "{npc:2215}: órdenes para {npc:270438}, camino al Castillo de Durnholde",
		["{npc:2238}'s ball and chain"] = "Bola y cadena de {npc:2238}",
		["{npc:2274} is {npc:232}'s dog, at the northern farmhouse in {area:286}."] = "{npc:2274} es el perro de {npc:232}, en la granja del norte de {area:286}.",
		["{npc:2391}: Poisons"] = "{npc:2391}: Venenos",
		["{npc:3024}: {quest:97538}, the Mirkweed in {area:464} by Sun Rock"] = "{npc:3024}: {quest:97538}, la hierba Mirk en {area:464}, junto a Roca del Sol",
		["{npc:4606} stands in the {object:36070}."] = "{npc:4606} está en {object:36070}.",
		["{npc:4721}: {quest:1195}, the phial from {zone:1440}'s Laughing Sisters"] = "{npc:4721}: {quest:1195}, el frasco de las Hermanas Risueñas de {zone:1440}",
} end)()
t.guides["forever/horde/07-ashenvale"] = (function() return {
		["A short walk north of the Galak camps, the cave of {area:1557} leads down to its deepest chamber, where the {object:20807} burns. Use the {item:5868} on it, then loot the {item:5869} at once: the flame only stays out briefly, and if it relights the phial is gone. Then east to {npc:2986}'s mesa.\nCareful: Two Galak Flame Guards (30) stand by the brazier and a centaur guard walks the cave: pull them away one at a time before you douse the flame."] = "A poca distancia al norte de los campamentos Galak, la cueva de {area:1557} baja hasta su cámara más profunda, donde arde {object:20807}. Usa {item:5868} en él y luego despoja {item:5869} de inmediato: la llama solo se mantiene apagada un momento, y si se vuelve a encender, pierdes el vial. Luego ve al este, a la meseta de {npc:2986}.\nCuidado: dos Guardias de llamas Galak (30) están junto al brasero y un guardia centauro recorre la cueva: atráelos de uno en uno antes de apagar la llama.",
		["Back south to the camp, then up into {zone:1456} for the flight to {area:378}."] = "Regresa al sur al campamento y luego sube a {zone:1456} para volar a {area:378}.",
		["Back to {npc:12867} at the lumber camp, on the road north to Splintertree."] = "Regresa con {npc:12867} al aserradero, en el camino al norte hacia el Puesto del Hachazo.",
		["Class trainer"] = "Instructor de clase",
		["Climb the path to the top of {area:2097}. {npc:10646} is held captive beside {npc:10896} (29): clear the guards and {npc:10896} first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way."] = "Sube por el sendero hasta la cima de {area:2097}. {npc:10646} está cautiva junto a {npc:10896} (29): primero acaba con los guardias y con {npc:10896}, luego libérala y protégela en el descenso; los emboscadores Tótem Siniestro te atacan en el camino.",
		["Felmusk satyrs"] = "Sátiros Putredor",
		["Fly to {area:1638}"] = "Vuela a {area:1638}",
		["Fly to {area:1638} from Zoram'gar. If you don't know its flight path, fly to {area:378} and walk north through {zone:1412} instead."] = "Vuela a {area:1638} desde Zoram'gar. Si no conoces su ruta de vuelo, vuela a {area:378} y camina al norte a través de {zone:1412}.",
		["Fly to {area:378}"] = "Vuela a {area:378}",
		["Follow the main road east past {area:415} (Alliance: keep to the road). {npc:12678}, a big grizzly, roams the {area:418} south of the road, west of {area:421}. His paw starts the next hunt quest."] = "Sigue el camino principal al este, pasando {area:415} (Alianza: no te salgas del camino). {npc:12678}, un gran oso pardo, ronda {area:418} al sur del camino, al oeste de {area:421}. Su pata inicia la siguiente misión de cacería.",
		["From the {area:2360} head north-east to the Warsong lumber camp on the road: {npc:12867} stands there."] = "Desde {area:2360}, ve al noreste hasta el Aserradero Grito de Guerra, junto al camino: ahí está {npc:12867}.",
		["Galak centaurs"] = "Centauros Galak",
		["Gazebo"] = "Mirador",
		["Gloomrise Toxin Samples, from the Gnawed Corpses"] = "Muestras de toxina de Alto Penumbroso ({item:273001}), de los Cadáveres roídos ({npc:264096})",
		["Keep east on the road. {npc:12858} waits south-west of the Warsong lumber camp. He and his grunts storm the {area:2360}: let them take aggro and stay with {npc:12858} until {npc:12860} is dead."] = "Sigue al este por el camino. {npc:12858} espera al suroeste del Aserradero Grito de Guerra. Él y sus bruteros asaltan {area:2360}: deja que ellos atraigan la atención de los enemigos y quédate con {npc:12858} hasta que {npc:12860} muera.",
		["Kill the {npc:10720} that comes for {npc:10638}"] = "Mata al {npc:10720} que viene por {npc:10638}",
		["Laughing Sisters"] = "Hermanas risueñas",
		["North of the camp, spiders overrun the burial ground at {area:17044}. Use {npc:264074}'s {item:273015} on the Gnawed Corpses; the Spinners drop the {item:273181}. {npc:264082} sits at the north end: her {item:273658} starts {quest:96294}."] = "Al norte del campamento, las arañas invaden el cementerio de {area:17044}. Usa {item:273015} de {npc:264074} en los Cadáveres roídos ({npc:264096}); las Tejedoras sueltan {item:273181}. {npc:264082} está en el extremo norte: su {item:273658} inicia {quest:96294}.",
		["North-west of Splintertree, the Felmusk satyrs camp in the woods. Every satyr can drop horns."] = "Al noroeste de Puesto del Hachazo, los sátiros Putredor acampan en el bosque. Cualquier sátiro puede soltar cuernos.",
		["On the way back north-east to Splintertree: {npc:12676} prowls the woods south-east of the Warsong lumber camp."] = "De regreso al noreste hacia Puesto del Hachazo: {npc:12676} merodea el bosque al sureste del Aserradero Grito de Guerra.",
		["Only if the {npc:10617} dropped his plot for you: {npc:10638} stands at {area:2237}."] = "Solo si {npc:10617} te soltó su plan: {npc:10638} está en {area:2237}.",
		["Ride the lift down, then follow the road east through the canyons to {area:484}, a Tauren village on top of the mesas. Its lift is on the north side."] = "Baja en el elevador y sigue el camino al este por los cañones hasta {area:484}, un poblado tauren en lo alto de las mesetas. Su elevador está en el lado norte.",
		["Sapphires of Aku'Mai"] = "Zafiros de Aku'Mai",
		["South from Raynewood, the moonwell sits in a hollow west of the river, hard to see from the road; {area:421} is west of it. Use the {item:5867} at the moonwell to fill it."] = "Al sur de Refugio Bosque Ralo, el pozo de la luna está en una hondonada al oeste del río, difícil de ver desde el camino; {area:421} está al oeste. Usa {item:5867} en el pozo de la luna para llenarlo.",
		["Speak with {npc:3057}, in {area:1638}: {quest:93739}"] = "Habla con {npc:3057}, en {area:1638}: {quest:93739}",
		["Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1)."] = "Baja en el elevador. El huevo está en un nido en el fondo del cañón, en uno de tres lugares: al sureste de las mesetas (52.3,55.2), al este (56.4,50.4) o al suroeste (37.6,56.1).",
		["The Earthen Ring"] = "El Anillo de la Tierra",
		["The Foulweald furbolgs hold the woods east of {area:421}, south of the road. Place {item:16972} on the {object:178206} and guard it: the furbolgs come to tear it down. {npc:12918} comes last; his totem drops in the basket."] = "Los furbolgs Maderiza ocupan el bosque al este de {area:421}, al sur del camino. Coloca {item:16972} en {object:178206} y defiéndelo: los furbolgs vienen a derribarlo. {npc:12918} llega al final; su tótem cae en la canasta.",
		["The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone {npc:10617} walks a long path between the camps: if you meet him, kill him, his note starts a quest for {area:2237}. Don't wait for him."] = "Los campamentos Galak llenan el cañón al norte de Poblado Viento Libre; Exploradores, Retadores y Cazavientos comparten cada campamento. Un {npc:10617} solitario recorre un largo camino entre los campamentos: si te lo encuentras, mátalo; su nota inicia una misión para {area:2237}. No lo esperes.",
		["The Laughing Sisters, dryads, wander {area:426} around {npc:12677}'s woods; one of them drops {npc:4721}'s {item:5867}, which can take several kills."] = "Las Hermanas risueñas, dríades, deambulan por {area:426} alrededor del bosque de {npc:12677}; una de ellas suelta {item:5867} de {npc:4721}, lo que puede requerir varias muertes.",
		["The Sapphires are blue crystals on the walls of the tunnels leading to the {area:2797} portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep."] = "Los zafiros son cristales azules en las paredes de los túneles que llevan al portal de {area:2797}, bajo tierra y fuera de la instancia: nada hacia abajo desde el foso, bajo el muro, hasta la cueva. Los sátiros y nagas de los túneles son élite: se recomienda ir en grupo. Los cristales reaparecen rápido, así que no hace falta adentrarse.",
		["The Wanted poster beside {npc:10537}"] = "El cartel de Se busca junto a {npc:10537}",
		["The night elf {quest:6503} (23-24) stalk the woods south and south-east of the lumber camp; they stealth, so watch for them."] = "Los elfos de la noche de {quest:6503} (23-24) acechan en el bosque al sur y al sureste del aserradero; usan sigilo, así que mantente atento.",
		["The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit."] = "El camino hacia los zafiros pasa por las ruinas hundidas en el extremo norte de la playa: baja las escaleras al foso.",
		["Warsong lumber camp"] = "Aserradero Grito de Guerra",
		["West of Freewind, the Grimtotem camps below {area:2097}. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps."] = "Al oeste de Poblado Viento Libre, los campamentos Tótem Siniestro bajo {area:2097}. Las Notas secretas están en Cofres de documentos ({object:176344}) en los campamentos sureste, suroeste y noroeste.",
		["West of Mystral Lake, {npc:12678}, a big grizzly, roams the {area:418}: his paw now drops for you."] = "Al oeste del Lago Mystral, {npc:12678}, un gran oso pardo, ronda {area:418}: ahora su pata sí te cae.",
		["for {npc:5901}, south of {area:392}: next guide"] = "para {npc:5901}, al sur de {area:392}: siguiente guía",
		["{area:2797} ruins"] = "Ruinas de {area:2797}",
		["{area:418} fountain"] = "Fuente de {area:418}",
		["{item:273181}, from Gloomrise Spinners"] = "{item:273181}, de las Tejedoras del Alto Penumbroso ({npc:264081})",
		["{item:5867}, at the {object:20806}"] = "{item:5867}, en {object:20806}",
		["{item:5867}, from a {npc:4054}"] = "{item:5867}, de una {npc:4054}",
		["{item:5868}, at the {object:20807}"] = "{item:5868}, en {object:20807}",
		["{item:5869}, from the {object:20807}"] = "{item:5869}, de {object:20807}",
		["{npc:10377}, by the wind rider master"] = "{npc:10377}, junto al maestro de jinetes del viento",
		["{npc:10428}'s next quest, Sacred Fire, ends in {zone:1456}, off this route. Skip it."] = "La siguiente misión de {npc:10428}, El fuego Sagrado, termina en {zone:1456}, fuera de esta ruta. Omítela.",
		["{npc:10617}'s {quest:4881}, if you meet him"] = "{quest:4881} de {npc:10617}, si te lo encuentras",
		["{npc:12676}, a big nightsaber, prowls the same woods further east, on the way north to Splintertree. Her claw starts the next hunt quest."] = "{npc:12676}, una gran sable de la noche, merodea el mismo bosque más al este, de camino al norte hacia el Puesto del Hachazo. Su garra inicia la siguiente misión de cacería.",
		["{npc:12677}, a shadow panther, stalks the woods around {area:426}, west of the Felmusk camp. Her head starts the next hunt quest."] = "{npc:12677}, una pantera de las sombras, acecha el bosque alrededor de {area:426}, al oeste del campamento Putredor. Su cabeza inicia la siguiente misión de cacería.",
		["{npc:12696} keeps the hunt board at {area:428}, by the flight master: take {quest:6383} and hand it straight back. {npc:12678}, {npc:12676} and {npc:12677} drop their trophies only after it."] = "{npc:12696} lleva el tablón de cacería en {area:428}, junto al maestro de vuelo: acepta {quest:6383} y entrégala de inmediato. {npc:12678}, {npc:12676} y {npc:12677} solo sueltan sus trofeos después de eso.",
		["{npc:12718}: only if you carry the manual pages"] = "{npc:12718}: solo si llevas las páginas del manual",
		["{npc:12736} offers a {area:2797} quest next; leave it unless you have a group."] = "{npc:12736} ofrece luego una misión de {area:2797}; déjala salvo que tengas grupo.",
		["{npc:210995}, a Forever addition, stands on the west shore of {area:421} with three quick Dragonslayer quests."] = "{npc:210995}, una adición de Forever, está en la orilla oeste de {area:421} con tres misiones rápidas de Matadragones.",
		["{npc:2986} stands on a mesa top east of the Galak camps. For the {quest:1149}, walk off the end of the planks beside him: you land safely."] = "{npc:2986} está en lo alto de una meseta al este de los campamentos Galak. Para {quest:1149}, camina hasta el final de los tablones a su lado y salta: aterrizas a salvo.",
		["{npc:3024} stands beside {npc:4721}, east of {npc:2995}."] = "{npc:3024} está junto a {npc:4721}, al este de {npc:2995}.",
		["{npc:4721} stands a short walk east of {npc:2995}."] = "{npc:4721} está a poca distancia al este de {npc:2995}.",
		["{npc:4721}: {npc:4722} at {area:484}, later in this guide"] = "{npc:4721}: {npc:4722} en {area:484}, más adelante en esta guía",
		["{npc:4722} stands in {area:484}: {npc:4721}'s filled phial is for him."] = "{npc:4722} está en {area:484}: el vial lleno de {npc:4721} es para él.",
		["{npc:4722}: the {object:20807} in {area:1557}, among the Galak camps"] = "{npc:4722}: {object:20807} en {area:1557}, entre los campamentos Galak",
		["{object:176344}, north-west camp"] = "{object:176344}, campamento noroeste",
		["{object:176344}, south-east camp"] = "{object:176344}, campamento sureste",
		["{object:176344}, south-west camp"] = "{object:176344}, campamento suroeste",
		["{zone:1456}'s central rise"] = "La meseta central de {zone:1456}",
} end)()
t.guides["forever/horde/30-40/01-hillsbrad-foothills"] = (function() return {
		["Back to the fields: the Peasants work south of the farmhouses. Careful: A fleeing peasant that reaches the town hall can bring back adds; snares or roots keep them from escaping."] = "Regresa a los campos: los Campesinos trabajan al sur de las casas de la granja. Cuidado: un campesino que huye y llega al ayuntamiento puede volver con refuerzos; las ralentizaciones o los enraizamientos evitan que escapen.",
		["Back to {area:272}"] = "De vuelta a {area:272}",
		["Back to {area:272}."] = "Regresa a {area:272}.",
		["Below ground"] = "Bajo tierra",
		["Boulderfist camp"] = "Campamento Puño de Roca",
		["Daggerspine naga"] = "Nagas Espinadaga",
		["Daggerspine shore"] = "Costa Espinadaga",
		["Drull's ball and chain"] = "Bola y cadena de Drull",
		["Fly to {area:1637}"] = "Vuela a {area:1637}",
		["Fly to {area:272}"] = "Vuela a {area:272}",
		["For characters of 29 to 33, but most quests here are level 32-34, a few up to 36: on purpose, for their experience. The Syndicate, {area:279}'s guards and the Boulderfist ogres are 31-35, so pull them one at a time."] = "Para personajes de nivel 29 a 33, pero la mayoría de las misiones de aquí son de nivel 32-34, y algunas de hasta 36: a propósito, por su experiencia. La Hermandad, los guardias de {area:279} y los ogros Puño de Roca son de nivel 31-35, así que atráelos de uno en uno.",
		["From {area:271} head north past {area:272} and follow the road on into the Alterac foothills. {quest:535} waits by the Syndicate camp. He offers his errand only while you carry {npc:2229}'s Infiltration: hand him the stout at once, and his reward is the Syndicate Missive Krusk wants. A missive from the Syndicate here does the same: with one in your bags the guide passes {quest:535}."] = "Desde {area:271}, ve al norte pasando {area:272} y sigue el camino hasta las estribaciones de Alterac. {quest:535} espera junto al campamento de la Hermandad. Solo ofrece su encargo mientras lleves “Infiltración” de {npc:2229}: dale la cerveza de inmediato, y su recompensa es la Misiva de la Hermandad que quiere Krusk. Una misiva de la Hermandad de aquí sirve igual: con una en tus bolsas, la guía omite a {quest:535}.",
		["Head back south down the road to {area:272}."] = "Regresa al sur por el camino hasta {area:272}.",
		["Head east to {area:271}'s graveyard, on the north-east edge of the town: Helcular's grave lies among the others. Come at it from the north, down the slope above the town. Southshore Guards (55) stand at the graveyard's north-west corner and south-east of the grave: walk in between them, hand the quest in and leave the way you came."] = "Ve al este hasta el cementerio de {area:271}, en el borde noreste del pueblo: la tumba de Helcular está entre las demás. Llega desde el norte, bajando por la ladera que está sobre el pueblo. Los Guardias de Costasur (55) están en la esquina noroeste del cementerio y al sureste de la tumba: pasa entre ellos, entrega la misión y vete por donde llegaste.",
		["Hillsbrad Peasants"] = "Campesinos de Trabalomas",
		["North of Southshore's graveyard"] = "Al norte del cementerio de Costasur",
		["Only if {quest:535}'s missive didn't come your way: the Syndicate Footpads and Thieves (32-34) around the camps west of the road carry missives too; about one in three drops one. Careful: at 31-32 they are still above you and stand close together, with Wizards (34-35) among them: pull one at a time from the camp's edge."] = "Solo si no conseguiste la misiva de {quest:535}: los Asaltantes de caminos de la Hermandad ({npc:2240}) y Ladrones (32-34) alrededor de los campamentos al oeste del camino también llevan misivas; uno de cada tres suelta una. Cuidado: a nivel 31-32 todavía están por encima de ti y están muy juntos, con Zahoríes (34-35) entre ellos: atráelos de uno en uno desde el borde del campamento.",
		["Shindigger keg"] = "Barril Machacacanillas",
		["South-east of Tarren Mill. Drull and {npc:2238} are chained in the keep's courtyard buildings: {npc:2427} carries the {item:3467} and {npc:2428} the {item:3499}, both in the keep. Kill them, then open both locks."] = "Al sureste del Molino Tarren. Drull y {npc:2238} están encadenados en los edificios del patio de la fortaleza: {npc:2427} lleva la {item:3467} y {npc:2428}, la {item:3499}, ambos dentro de la fortaleza. Mátalos y luego abre ambos candados.",
		["South-west, the Cave and Ferocious Yetis (30-32) fill the {area:277} in the hills west of {area:272}; about one in sixteen carries the rod. Stay in these caverns: the Mountain and Giant Yetis (32-34) of the cave further north carry it too, but at 29-30 they hit hard and come in pairs."] = "Al suroeste, los Yetis de las cuevas y los Yetis feroces (30-32) llenan {area:277}, en las colinas al oeste de {area:272}; más o menos uno de cada dieciséis lleva la vara. Quédate en estas cavernas: los Yetis monteses y Yetis gigantes (32-34) de la cueva más al norte también la llevan, pero a nivel 29-30 pegan fuerte y van en parejas.",
		["Syndicate missives"] = "Misivas de la Hermandad",
		["The smithy"] = "La herrería",
		["The third flame burns in the smaller cave up in the hills north of the caverns.\nCareful: Giant and Mountain Yetis (32-34) stand around the flame, often in pairs, and Frostmaw, a rare yeti (37), roams nearby. At 30-31 they are over your level: pull the yetis one at a time from the cave mouth before you use the Rod, and watch for Frostmaw before you go in."] = "La tercera llama arde en la cueva más pequeña, arriba en las colinas al norte de las cavernas.\nCuidado: Yetis gigantes y Yetis monteses (32-34) rodean la llama, a menudo en parejas, y Faucehielo, un yeti raro (37), deambula cerca. A nivel 30-31 están por encima de tu nivel: atrae a los yetis de uno en uno desde la boca de la cueva antes de usar la Vara, y ubica a Faucehielo antes de entrar.",
		["The {area:279} crater's eastern rim"] = "El borde oriental del cráter de {area:279}",
		["Torn Fin beach"] = "Playa Rompeanca",
		["Torn Fin murlocs"] = "Múrlocs Rompeanca",
		["Town hall"] = "Ayuntamiento",
		["Train"] = "Entrenar",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Entrena mientras estás en {zone:1458}: los instructores están en {object:36070}, {object:36073} y {object:36082} (paladines: {npc:260093}).",
		["Train your new spells."] = "Entrena tus nuevos hechizos.",
		["West across the foothills to {area:287} town: the smithy stands in the middle of it. {npc:2404} and his apprentices work at the forge; the {object:1736} is stacked beside it."] = "Al oeste por las laderas hasta el pueblo de {area:287}: la herrería está en el centro. {npc:2404} y sus aprendices trabajan en la forja; el {object:1736} está apilado a su lado.",
		["West past the hills to the farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere."] = "Al oeste, pasando las colinas, hasta las granjas al este del pueblo de {area:287}. {npc:232} trabaja el campo junto a la casa de la granja del norte, y {npc:2403}, el que está más al sureste; hay Mozos de labranza y Granjeros por todas partes.",
		["You missed Darthalia's first errands, from the 22-25 {area:287} guide: they come first now. They are a few levels below you and quick, and they open the rest of the {quest:527} in this guide."] = "No hiciste los primeros encargos de Darthalia, de la guía de {area:287} 22-25: ahora van primero. Están unos niveles por debajo de ti y son rápidos, y abren el resto de {quest:527} en esta guía.",
		["{item:3388}: auction house or an alchemist, for {quest:515}."] = "{item:3388}: casa de subastas o un alquimista, para {quest:515}.",
		["{item:3703}, for {npc:2333}"] = "{item:3703}, para {npc:2333}",
		["{npc:2229} wants his two scouts freed from {area:275} before he trusts you with Infiltration."] = "{npc:2229} quiere que liberes a sus dos exploradores de {area:275} antes de confiarte “Infiltración”.",
		["{npc:2238}'s ball and chain"] = "Bola y cadena de {npc:2238}",
		["{npc:2792}, by the gate"] = "{npc:2792}, junto a la puerta",
		["{npc:4949}, Grommash Hold, if you carry it"] = "{npc:4949}, en la fortaleza de Thrall, si la llevas",
		["{zone:1458} trainers"] = "Instructores de {zone:1458}",
} end)()
t.guides["forever/horde/30-40/02-thousand-needles"] = (function() return {
		["Back south to {npc:11863}'s tower."] = "Regresa al sur, a la torre de {npc:11863}.",
		["Clam beds"] = "Bancos de almejas",
		["Fly to {area:460}"] = "Vuela a {area:460}",
		["Fly to {area:484}"] = "Vuela a {area:484}",
		["Head north along the coast, then inland to the ruined tower of {area:2405}: {npc:11863} waits inside. The coast's clams and naga come after {area:599}, on one walk north to {area:2406}."] = "Dirígete al norte por la costa y luego tierra adentro hasta la torre en ruinas de {area:2405}: {npc:11863} espera dentro. Las almejas y los naga de la costa vienen después de {area:599}, en un solo recorrido hacia el norte hasta {area:2406}.",
		["Keep north to {area:598}. The Slitherblade Myrmidons, Naga and Sorceresses hold the beach; pull them one at a time. Any Slitherblade can drop {item:15881}."] = "Sigue al norte hasta {area:598}. Los mirmidones, naga y hechiceras Filozante dominan la playa; atráelos de uno en uno. Cualquier Filozante puede soltar {item:15881}.",
		["Swim out to {area:2406} off the far northern tip and use the {item:15766} on the {object:177673}: {npc:12369} (38) rises; kill him for the {quest:6027}. He is well above you: rest to full first. {object:177786} stands on the shore beside the statue: open it with both keys."] = "Nada hasta {area:2406}, frente al extremo norte, y usa {item:15766} en {object:177673}: aparece {npc:12369} (38); mátalo para obtener {quest:6027}. Te supera bastante en nivel: descansa hasta recuperarte por completo antes. {object:177786} está en la orilla junto a la estatua: ábrelo con ambas llaves.",
		["The zeppelin lands at the tower outside {zone:1454}'s main gate. {npc:5639} walks the Drag: if he isn't at the arrow, look along its streets to the south-west. {npc:5640} stands in the {object:172961} on the west side of the city."] = "El zepelín aterriza en la torre que está fuera de la puerta principal de {zone:1454}. {npc:5639} recorre La Calle Mayor: si no está en la flecha, búscalo por sus calles hacia el suroeste. {npc:5640} está en {object:172961}, en el lado oeste de la ciudad.",
		["West to the shore. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach: each clam you open on the sea floor, and some crawlers, give a {item:15874}. Open each one in your bags for its meat.\nThe Drysnap Crawlers and Pincers on the same beach carry {item:15878}, about one in seven."] = "Ve al oeste hasta la orilla. Las almejas gigantes de concha blanda están en las aguas poco profundas y los reptadores de arrecife enfurecidos recorren la playa: cada almeja que abras en el fondo del mar, y algunos reptadores, dan una {item:15874}. Abre cada una en tus bolsas para obtener su carne.\nLos reptadores y las pinzas Secachasquido de la misma playa llevan {item:15878}, aproximadamente uno de cada siete.",
		["Zeppelin to {zone:1454}"] = "Zepelín a {zone:1454}",
		["{item:15766}, on the {object:177673}"] = "{item:15766}, en {object:177673}",
		["{item:15878}, from the Drysnap crabs"] = "{item:15878}, de los cangrejos Secachasquido",
		["{item:15881}, from the Slitherblade naga"] = "{item:15881}, de los naga Filozante",
		["{npc:5641}'s next errand sends you after a demon lord with an elite guard: skip it."] = "El siguiente encargo de {npc:5641} te manda tras un señor demonio con una guardia élite: omítelo.",
		["{npc:5892} stands in the {object:172957}."] = "{npc:5892} está en {object:172957}.",
		["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901}: {npc:3527} y tu {item:5177}",
		["{npc:5905} also starts Elemental Aid ({area:1717}), the 33-40 chain to The Tempest's Weapons: forever/class/shaman/call-of-air-horde."] = "{npc:5905} también inicia Elemental Aid ({area:1717}), la cadena de nivel 33-40 hacia The Tempest's Weapons: forever/class/shaman/call-of-air-horde.",
		["{npc:5905}: your {item:5178}"] = "{npc:5905}: tu {item:5178}",
		["{object:177787} lies on the ground just south-west of {npc:11863}'s tower, on the way down to the shore: read it. Its two keys drop only while you have the quest."] = "{object:177787} está en el suelo justo al suroeste de la torre de {npc:11863}, de camino a la orilla: léelo. Sus dos llaves solo caen mientras tengas la misión.",
		["{zone:1454} flight master"] = "Maestro de vuelo de {zone:1454}",
} end)()
t.guides["forever/horde/30-40/03-stranglethorn-vale"] = (function() return {
		["Back north to the camp."] = "Regresa al norte, al campamento.",
		["Back to {object:3202}."] = "De vuelta a {object:3202}.",
		["Boat to {area:35}"] = "Barco a {area:35}",
		["Dizzywig's parts go back to Kravel in the {area:439}, off the route: leave them."] = "Las piezas de Dizzywig se entregan a Kravel en {area:439}, fuera de la ruta: déjalas.",
		["Fly to {area:1637}"] = "Vuela a {area:1637}",
		["Fly to {area:35}"] = "Vuela a {area:35}",
		["Fly to {area:392}"] = "Vuela a {area:392}",
		["Fly to {object:3202}"] = "Vuela a {object:3202}",
		["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. {npc:773} wants it investigated: walk among its tents. From here on, keep every page of {quest:338} you loot: {npc:716} takes them on your next Stranglethorn visit."] = "Sigue el camino al norte desde {object:3202}; el campamento de caza de Nesingwary está en la colina al noreste del río. {npc:773} quiere que lo investigues: camina entre sus tiendas. Desde aquí, guarda cada página de {quest:338} que saquees: {npc:716} las recibe en tu próxima visita a Tuercespina.",
		["Green Hills pages"] = "Páginas de Las verdes colinas",
		["Leave {area:35} through the tunnel and follow the road north to {object:3202}, the orc camp on the west side of the vale. Stay on the road: the jungle beside it is above your level."] = "Sal de {area:35} por el túnel y sigue el camino al norte hasta {object:3202}, el campamento orco en el lado oeste de la vega. No salgas del camino: la selva a los lados está por encima de tu nivel.",
		["Mosh'Ogg camp"] = "Campamento Mosh'Ogg",
		["Nesingwary's camp"] = "Campamento de Nesingwary",
		["North-west of Grom'gol the {area:104} lies under the water off the coast. The {item:4094} rests on the sea floor by the sunken ruins; watch your breath and the murlocs."] = "Al noroeste de Campamento Grom'gol, {area:104} está bajo el agua frente a la costa. El {item:4094} descansa en el fondo del mar junto a las ruinas hundidas; cuida tu respiración y a los múrlocs.",
		["River Crocolisks lie along the river below the camp. Young Stranglethorn Tigers prowl west of the camp, Young Panthers east of it. Head west past the camp. Stranglethorn Raptors (33-34) hunt the clearings, and the Bloodscalp trolls hold the ruins on the coast: every Bloodscalp can drop a tusk. A {item:4614} is a very rare drop from them: if one drops, read it. Careful: The troll camps have many patrolling mobs, so other trolls often join a fight."] = "Los Crocoliscos fluviales están a lo largo del río bajo el campamento. Los Tigres de Tuercespina jóvenes merodean al oeste del campamento y las Panteras jóvenes al este. Ve al oeste pasando el campamento. Los Raptores de Tuercespina (33-34) cazan en los claros, y los trols Sangrapellejo ocupan las ruinas de la costa: cualquier Sangrapellejo puede soltar un colmillo. El {item:4614} es un botín muy raro de ellos: si te cae, léelo. Cuidado: los campamentos trols tienen muchos enemigos patrullando, así que otros trols suelen unirse a la pelea.",
		["The Shadowmaw Panthers come much later, by {object:3202}"] = "Las panteras Faucesombría llegan mucho más tarde, junto a {object:3202}",
		["from {npc:4723}"] = "de {npc:4723}",
		["{area:2408} flight master"] = "Maestro de vuelo de {area:2408}",
		["{area:35} first: the goblins' boat sails there from {area:392}, and every {area:35} quest is for the north of the vale, which you then walk up into."] = "Primero {area:35}: el barco de los goblins zarpa hacia allá desde {area:392}, y todas las misiones de {area:35} son para el norte de la vega, hacia donde luego subes a pie.",
		["{item:5852}, in {object:20691}"] = "{item:5852}, en {object:20691}",
		["{npc:2464} stands in the middle of {object:3202}, {npc:2497} near the zeppelin tower, {npc:2465} beside the flight master."] = "{npc:2464} está en el centro de {object:3202}, {npc:2497} cerca de la torre del zepelín y {npc:2465} junto al maestro de vuelo.",
		["{npc:2495}'s shop is in the building east of the inn; {npc:2498} is on the inn's bottom floor, {npc:2496}, {npc:737} and {npc:773} upstairs beside the flight master."] = "La tienda de {npc:2495} está en el edificio al este de la posada; {npc:2498} está en la planta baja de la posada, y {npc:2496}, {npc:737} y {npc:773} arriba, junto al maestro de vuelo.",
		["{npc:2496}, upstairs"] = "{npc:2496}, arriba",
		["{npc:2496}: Cozzle's footlocker is at {area:37}, later in this guide"] = "{npc:2496}: el baúl de Cozzle está en {area:37}, más adelante en esta guía",
		["{npc:2496}: for Pozzik at the {area:2240}, on the way to {zone:1446} around level 43"] = "{npc:2496}: para Pozzik en {area:2240}, de camino a {zone:1446} alrededor del nivel 43",
		["{npc:2497}: for Arathi, later on the route"] = "{npc:2497}: para Tierras Altas de Arathi, más adelante en la ruta",
		["{npc:3391} waits upstairs in the house by the flight master; {quest:1111} stands on the docks, beside the boat."] = "{npc:3391} espera en el piso de arriba de la casa junto al maestro de vuelo; {quest:1111} está en los muelles, junto al barco.",
		["{npc:3391}, upstairs"] = "{npc:3391}, arriba",
		["{npc:3391}: for {npc:4631} in {area:35}, where the boat goes"] = "{npc:3391}: para {npc:4631} en {area:35}, adonde va el barco",
		["{npc:4631} stands on the pier where the boat docks. {npc:2495}'s shop is in the building east of the inn; {npc:2498} is on the inn's bottom floor, {npc:2496}, {npc:737} and {npc:773} upstairs, {npc:2858} the flight master on the upper deck."] = "{npc:4631} está en el muelle donde atraca el barco. La tienda de {npc:2495} está en el edificio al este de la posada; {npc:2498} está en la planta baja de la posada, {npc:2496}, {npc:737} y {npc:773} arriba, y {npc:2858}, el maestro de vuelo, en la cubierta superior.",
		["{npc:4631}, on the pier"] = "{npc:4631}, en el muelle",
		["{npc:4723} (38) is inside the Venture Co. house on {area:37}'s west shore, among the geologists: his key opens {object:20691} in the same house, which holds the blueprints for {npc:2496}."] = "{npc:4723} (38) está dentro de la casa de Ventura y Cía. en la orilla oeste de {area:37}, entre los geólogos: su llave abre {object:20691} en la misma casa, que contiene los planos para {npc:2496}.",
		["{quest:1111}, on the docks"] = "{quest:1111}, en los muelles",
		["{zone:1454} flight master"] = "Maestro de vuelo de {zone:1454}",
} end)()
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = (function() return {
