t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Back east past {area:75}: the Atal'ai artifacts lie in the water and on the banks of the {quest:1424}."] = "De vuelta al este pasando {area:75}: los artefactos Atal'ai están en el agua y en las orillas de {quest:1424}.",
		["Below ground"] = "Bajo tierra",
		["Dragon caves"] = "Cuevas de dragones",
		["Fly to {area:1099}"] = "Vuela a {area:1099}",
		["Fly to {area:75}"] = "Vuela a {area:75}",
		["Frayfeather hippogryphs"] = "Hipogrifos Plumavieja",
		["Level 45.37"] = "Nivel 45.37",
		["Murlocs of the Misty Reed"] = "Múrlocs de Juncobruma",
		["Northspring harpies"] = "Arpías Nortearroyo",
		["Onyxia's eggs"] = "Huevos de Onyxia",
		["Rage Scar yetis"] = "Yetis Cicatriz de Rabia",
		["Ride back north to Brackenwall."] = "Regresa cabalgando al norte a Poblado Murohelecho.",
		["Ride north-west to the {area:1108}; {npc:14637} waits on the dock."] = "Cabalga al noroeste hasta {area:1108}; {npc:14637} espera en el muelle.",
		["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "Cabalga al oeste por el camino; el pergamino está a la orilla del agua, en el extremo oeste del pantano.",
		["Riding at 40"] = "Equitación a nivel 40",
		["Rogue Vale screechers"] = "Estridadores del valle huido",
		["Sawtooth crocolisks"] = "Crocoliscos Denteserra",
		["Sea elementals and sea sprays wash along the shore around the dock. Zap the giants with {item:18904} first: shrunken, they lose their elite strength. Shore striders wade in the water; the land walkers and cliff giants roam the hills further north."] = "Los elementales de mar y rocíos del mar recorren la orilla alrededor del muelle. Primero dispara a los gigantes con {item:18904}: al encogerse, pierden su fuerza de élite. Los zancaorillas vadean en el agua; los caminatierras y gigantes del risco recorren las colinas más al norte.",
		["Skeletal horses: {npc:4731}, beside {npc:4773} in {area:159}."] = "Caballos esqueléticos: {npc:4731}, junto a {npc:4773} en {area:159}.",
		["South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments."] = "Al sur del valle, los hipogrifos Plumavieja anidan en las laderas; casi todos sueltan tendones y fragmentos metálicos.",
		["Sprite darters and forest walkers"] = "Duendes dardo y caminabosques",
		["The Eggs of Onyxia lie in the dragon caves in the {area:511}'s south-east, guarded by the scalebanes; smash five."] = "Los Huevos de Onyxia están en las cuevas de dragones del sureste de {area:511}, custodiados por los horrocrustos; destruye cinco.",
		["The Marsh Murlocs live on the strand south of the post; the Inkspewers are along the shore east of it and the Flesheaters further west, around the huts on the western shore."] = "Los Múrlocs de marisma ({npc:747}) viven en la playa al sur del puesto; los Vomitatintas están en la orilla al este y los Comecarnes más al oeste, alrededor de las chozas de la orilla oeste.",
		["The Northspring harpies nest on the ridges in the far north-west. They are 48-50, a few levels above you: the Windcallers heal, so kill them first and pull one at a time."] = "Las arpías Nortearroyo anidan en las lomas del extremo noroeste. Son de nivel 48-50, unos niveles más que tú: las Clamavientos curan, así que mátalas primero y atráelas de una en una.",
		["The sprite darters flit over the grove just west of the camp and carry the {item:9589}; the Wandering Forest Walkers, a little further west, carry the Splintered Logs."] = "Los duendes dardo revolotean sobre la arboleda justo al oeste del campamento y llevan {item:9589}; los Caminabosques deambulantes ({npc:7584}), un poco más al oeste, llevan los Troncos astillados ({item:9590}).",
		["Zeppelin to {object:3202}"] = "Zepelín a {object:3202}",
		["for the {npc:5598} in the {zone:1425}, around level 48"] = "para el {npc:5598} en {zone:1425}, alrededor del nivel 48",
		["for the {object:2555} in {zone:1445}, later in this guide"] = "para {object:2555} en {zone:1445}, más adelante en esta guía",
		["for the {zone:1425} owlbeasts, around level 48"] = "para los lechúcicos de {zone:1425}, alrededor del nivel 48",
		["the {object:2555}"] = "{object:2555}",
		["{npc:2934}, on the way back to Zinge"] = "{npc:2934}, de camino de regreso con Zinge",
		["{npc:4500}'s challenge, back in Brackenwall, needs a group of three. Alone, grind the Firemane scouts here on the {area:511}'s northern edge to level 45.37 before you ride back north, so you don't come back down for it. Or, with a group, run the {area:978} dungeon or the {area:1517} dungeon instead."] = "El desafío de {npc:4500}, de vuelta en Poblado Murohelecho, requiere un grupo de tres. Si vas solo, mata exploradores Pirocabello aquí, en el borde norte de {area:511}, hasta el nivel 45.37 antes de regresar cabalgando al norte, para no tener que volver por ello. O, con un grupo, haz la mazmorra de {area:978} o la mazmorra de {area:1517} en su lugar.",
		["{npc:4773}, riding trainer"] = "{npc:4773}, instructora de equitación",
		["{npc:7825}, the {object:36126}"] = "{npc:7825}, {object:36126}",
		["{quest:7738}, a rare drop"] = "{quest:7738}, botín raro",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["Back north, just south of {area:976}, use the {item:8524} now: the two-hour timer starts. The Blisterpaw Hyenas, Glasshide Basilisks and Scorpid Hunters share the dunes here. Each can drop an untested sample: use it, and it either passes as an acceptable one or is lost. Keep killing until you have eight of each."] = "De regreso al norte, justo al sur de {area:976}, usa ahora el {item:8524}: empieza el temporizador de dos horas. Las Hienas Zarpaampolla, los Basiliscos Pielvidrio y los Cazadores Escórpido comparten las dunas aquí. Cada uno puede soltar una muestra sin probar: úsala, y o bien pasa como aceptable o se pierde. Sigue matando hasta tener ocho de cada una.",
		["Below ground"] = "Bajo tierra",
		["Dark Iron Lookouts"] = "Oteadores Hierro Negro ({npc:8566})",
		["Fly to {area:976}"] = "Vuela a {area:976}",
		["His next request needs the {item:10552} from elite cultists: leave it."] = "Su siguiente petición necesita {item:10552} de sectarios élite: déjala.",
		["Keep the Model 4711-FTZ Power Source Bilgewhizzle gave you: it starts {quest:654}, a two-hour timer, so use it on the way back north from Scrimshank's hive."] = "Guarda la Fuente de energía modelo 4711-FTZ que te dio Bilgewhizzle: inicia {quest:654}, con un temporizador de dos horas, así que úsala de regreso al norte desde la colmena de Patagolpe.",
		["OOX-17/TN"] = "OOX-17/TN",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "Solo con {item:11818}: regresa al este a {object:173265} de la excavación.",
		["Ride north-west across the gorge; {area:1446} is the scaffolded camp in the north-west."] = "Cabalga al noroeste cruzando la garganta; {area:1446} es el campamento con andamios del noroeste.",
		["Scrimshank's gear"] = "Equipo de Patagolpe",
		["South of the {area:982} the Dunemaul ogres hold their compound, with {npc:12046} at its eastern end. Dig up {quest:3161} ornaments between the fights."] = "Al sur de {area:982}, los ogros Machacaduna ocupan su base, con {npc:12046} en el extremo este. Desentierra ornamentos de {quest:3161} entre peleas.",
		["The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the {item:18960}."] = "Los Oteadores Hierro Negro ({npc:8566}) están en las lomas alrededor de las torres de vigilancia al sur de La Caldera; uno de cada diez lleva {item:18960}.",
		["The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a {item:10551}, one in ten the {item:18959}. Slaves, Slavers and Taskmasters carry daggers too."] = "Los Vapoherreros Hierro Negro ({npc:5840}) trabajan los hornos en medio de La Caldera; la mitad lleva {item:10551} y uno de cada diez, {item:18959}. Los esclavos, esclavistas y capataces también llevan dagas.",
		["The Steamsmiths' furnaces"] = "Los hornos de los Vapoherreros",
		["The {area:247}"] = "{area:247}",
		["The {object:179827} board"] = "El tablón {object:179827}",
		["Use the {item:8524}"] = "Usa {item:8524}",
		["West along the road south; {npc:7771} camps by the ruins at the {area:1938}. Put on his {item:9978}: it shows the buried ornaments, here and around the {area:983}."] = "Al oeste por el camino del sur; {npc:7771} acampa junto a las ruinas de {area:1938}. Ponte su {item:9978}: muestra los ornamentos enterrados, aquí y alrededor de {area:983}.",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "Al oeste de Gadgetzan, usa {item:8584} junto al pozo de agua del campamento trol.",
		["for {npc:7010} in {zone:1454}, around level 50"] = "para {npc:7010} en {zone:1454}, alrededor del nivel 50",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "{item:8526} crece en {zone:1425}, alrededor del nivel 48",
		["the {object:173265}"] = "{object:173265}",
		["{item:11818}, a rare drop"] = "{item:11818}, botín raro",
		["{item:8623}, a rare drop"] = "{item:8623}, botín raro",
		["{npc:5955} waits in the valley. Walk him all the way to his wife {npc:6015} in {area:977}, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. {npc:8579} stands in the port too."] = "{npc:5955} espera en el valle. Acompáñalo hasta su esposa {npc:6015} en {area:977}, al noreste cruzando el desierto: quédate cerca, ve despacio por él y defiéndelo de lo que lo ataque. No montes ni uses la piedra de hogar lejos de él. {npc:8579} también está en el puerto.",
		["{npc:5955}'s escort"] = "Escolta de {npc:5955}",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, junto al maestro de jinetes del viento",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["Back west to {area:350}; rangers and marksmen stay near the lodge, scouts and outrunners on the slopes south of it."] = "De vuelta al oeste a {area:350}; los forestales y tiradores se quedan cerca del refugio, y los exploradores y avanzadas en las laderas al sur.",
		["East of the village, the violet flower grows in the hills."] = "Al este del poblado, la flor violeta crece en las colinas.",
		["Fly to {area:272}"] = "Vuela a {area:272}",
		["Fly to {area:75}"] = "Vuela a {area:75}",
		["Follow the roads east across the {zone:1425} to the troll village on the eastern coast."] = "Sigue los caminos al este cruzando {zone:1425} hasta el poblado trol de la costa este.",
		["Highvale"] = "Vallealto",
		["His next request, going on to the {area:355}, is for a group."] = "Su siguiente petición, que sigue en {area:355}, es para grupo.",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "Al norte por la costa, la canasta de picnic de {npc:14731} está en la islita; un {npc:14748} la custodia.",
		["OOX-09/HL"] = "OOX-09/HL",
		["Ride all the way west to the Wildhammer town of {area:348} and place the message by the well in its centre. The town is full of Alliance guards: get in, place it and get out."] = "Cabalga todo el camino al oeste hasta {area:348}, el pueblo de los Martillo Salvaje, y coloca el mensaje junto al pozo del centro. El pueblo está lleno de guardias de la Alianza: entra, colócalo y sal.",
		["Ride back north to the bloodmages."] = "Regresa cabalgando al norte con los magos de sangre.",
		["Ride north-east from {area:272} into the {zone:1425} and east along the road; {npc:7801} camps on the hill south of the elves' {area:350}."] = "Cabalga al noreste desde {area:272} hacia {zone:1425} y al este por el camino; {npc:7801} acampa en la colina al sur de {area:350}, de los elfos.",
		["Ride west out of {area:75} and south through the canyon into the {zone:1419}; the two bloodmages stand by the road just inside."] = "Cabalga al oeste desde {area:75} y al sur por el cañón hacia {zone:1419}; los dos magos de sangre están junto al camino, justo al entrar.",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "Al sur del refugio, los trols Secacorteza ocupan sus poblados. Todos llevan un cráneo: con veinte, usa {item:15002} para hacer la Pica cargada de Nimboya y luego clávala dentro del poblado.",
		["South-west again, the exile hides by the ruins of {area:353}."] = "De nuevo al suroeste, el exiliado se esconde junto a las ruinas de {area:353}.",
		["The bloodmages"] = "Los magos de sangre",
		["The crates of {item:8684} lie around the abandoned Horde camp at {area:351}, among the oozes."] = "Las cajas de {item:8684} están alrededor del campamento abandonado de la Horda en {area:351}, entre los mocos.",
		["The secret lies on the {area:307}, above the beach."] = "El secreto está en {area:307}, sobre la playa.",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "Sus siguientes misiones piden las mismas partes otra vez a cambio de un objeto de mejora y no dan experiencia: déjalas.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:7977} is a level 48 elite: most classes solo it at level 50, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:7977} walks the shore below the {area:307}, from the arrow south to about 75,66 and north to about 82,52: if she isn't at the arrow, follow the shore."] = "Estos son enemigos élite: se recomienda agruparse, busca gente con quien hacerlo. {npc:7977} es élite de nivel 48: la mayoría de las clases la vencen solas a nivel 50, pero quizá necesites ayuda. Sáltala si estás solo: la ruta te hace recuperar la experiencia farmeando.\n{npc:7977} recorre la orilla bajo {area:307}, desde la flecha al sur hasta cerca de 75,66 y al norte hasta cerca de 82,52: si no está en la flecha, sigue la orilla.",
		["for {npc:6986} in {zone:1454}, around level 50"] = "para {npc:6986} en {zone:1454}, alrededor del nivel 50",
		["for {npc:7825} in the {zone:1458}, around level 50"] = "para {npc:7825} en {zone:1458}, alrededor del nivel 50",
		["{area:348} well"] = "Pozo de {area:348}",
		["{item:8704}, a rare drop"] = "{item:8704}, botín raro",
		["{npc:14731}'s lunch"] = "El almuerzo de {npc:14731}",
		["{npc:14757}, at the top of {area:354}"] = "{npc:14757}, en la cima de {area:354}",
		["{npc:7801}'s camp"] = "Campamento de {npc:7801}",
} end)()
t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["Back north-east to {npc:8420}."] = "Regresa al noreste con {npc:8420}.",
		["Back to {area:1099}"] = "De vuelta a {area:1099}",
		["Back to {npc:11548} at the shrine; stay west of the {area:3137} guards."] = "Regresa con {npc:11548} al santuario; mantente al oeste de los guardias de {area:3137}.",
		["Back to {object:3202}"] = "De vuelta a {object:3202}",
		["Below ground"] = "Bajo tierra",
		["Class trainer"] = "Instructor de clase",
		["Continue south to {area:35}. {npc:7406} has his workshop on the upper ring of the bay."] = "Sigue al sur hasta {area:35}. {npc:7406} tiene su taller en el anillo superior de la bahía.",
		["Fly to {area:1099}"] = "Vuela a {area:1099}",
		["Fly to {area:1637}"] = "Vuela a {area:1637}",
		["Fly to {area:1638}"] = "Vuela a {area:1638}",
		["Fly to {area:35}"] = "Vuela a {area:35}",
		["Fly to {area:976}"] = "Vuela a {area:976}",
		["Fly to {object:3202}"] = "Vuela a {object:3202}",
		["Fly to {zone:1456}; it is on the way to {area:1099}. No flight path there yet? Fly to {area:378} and ride west through {zone:1412}. Hamuul and {npc:4046} are on the {area:1639}; Druids and Paladins train here ({npc:3033}, {npc:246344})."] = "Vuela a {zone:1456}; está camino a {area:1099}. ¿Aún no tienes esa ruta de vuelo? Vuela a {area:378} y cabalga al oeste por {zone:1412}. Hamuul y {npc:4046} están en {area:1639}; los druidas y paladines entrenan aquí ({npc:3033}, {npc:246344}).",
		["Follow the road north to {area:1237}, the Horde camp."] = "Sigue el camino al norte hasta {area:1237}, el campamento de la Horda.",
		["Frayfeather Hippogryphs"] = "Hipogrifos Plumavieja",
		["Hippogryph nests"] = "Nidos de hipogrifo",
		["Keep the deliveries for {npc:4046}, {npc:8659} and {npc:6522}: you pass {zone:1456}, {zone:1454} and the {zone:1458} later."] = "Guarda las entregas para {npc:4046}, {npc:8659} y {npc:6522}: pasas por {zone:1456}, {zone:1454} y {zone:1458} más adelante.",
		["Keep {npc:8659}'s payment and Ag'tor's {quest:3504}: they go back to {area:1237} on a later visit."] = "Guarda el pago de {npc:8659} y {quest:3504} de Ag'tor: vuelven a {area:1237} en una visita posterior.",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "Guarda {quest:3444}: el cofre de {npc:7771} se abre en una visita posterior.",
		["On the way through {zone:1454} to the flight master, step into the Drag: {npc:7010} takes the insect report from {zone:1446}, and its experience shortens the top-up to 50 in {zone:1447}."] = "De camino por {zone:1454} hacia el maestro de vuelo, pasa por la Calle Mayor: {npc:7010} recibe el informe de insectos de {zone:1446}, y su experiencia acorta lo que falta para llegar a 50 en {zone:1447}.",
		["Ride east along the road out of Splintertree. {npc:11548} waits at the {area:1235} just off the road, a few steps west of the Alliance's {area:3137}: come in from the west and keep clear of the Azshara Sentinels and Jarrodenus (elite)."] = "Cabalga al este por el camino desde Puesto del Hachazo. {npc:11548} espera en {area:1235}, a un lado del camino, a unos pasos al oeste de {area:3137} de la Alianza: llega desde el oeste y mantente lejos de los Centinelas de Azshara ({npc:11276}) y de Jarrodenus (élite).",
		["Ride into {zone:1447}"] = "Cabalga hacia {zone:1447}",
		["Ride north-east to the goblin's camp on the cliffs above the {area:1227}."] = "Cabalga al noreste hasta el campamento del goblin en los acantilados sobre {area:1227}.",
		["Ride south along the road to the {area:1938}; {npc:7771} camps beside it. From here the road west leads down into {zone:1449}, where the next guide starts."] = "Cabalga al sur por el camino hasta {area:1938}; {npc:7771} acampa al lado. Desde aquí, el camino al oeste baja a {zone:1449}, donde empieza la siguiente guía.",
		["Ride south-west to the ruins. The four tablets lie among the ruins, guarded by Spitelash naga; any Siren or Myrmidon can carry {npc:8420}'s rune."] = "Cabalga al suroeste hasta las ruinas. Las cuatro tablillas están entre las ruinas, custodiadas por nagas Látigo de Ira; cualquier Sirena o Mirmidón puede llevar la runa de {npc:8420}.",
		["Ride west back to {area:1237}."] = "Cabalga al oeste de vuelta a {area:1237}.",
		["Sprite Darters"] = "Duendes dardo",
		["The Bloodsail ships"] = "Los barcos Velasangre",
		["The Droffers' shop is a few steps further into the Drag."] = "La tienda de los Droffers está unos pasos más adentro de la Calle Mayor.",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "Los fantasmas Altonato rondan las ruinas justo al norte del santuario; los sátiros Haldarr acampan un poco más al norte.",
		["The Thunderhead Hippogryphs fly over the hills just south of {area:1237}."] = "Los Hipogrifos Tronatesta vuelan sobre las colinas justo al sur de {area:1237}.",
		["The blood elves' camp lies just south of {npc:8420}. His four pieces of equipment lie in the crates around the camp."] = "El campamento de los elfos de sangre está justo al sur de {npc:8420}. Sus cuatro piezas de equipo están en las cajas alrededor del campamento.",
		["The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill."] = "Los dragones feéricos revolotean por el bosque justo al oeste del campamento. Usa la vasija en cada uno que mates.",
		["The hippogryph nests are on the hills to the south, around the {area:2522}; each holds an egg for the {object:142071}."] = "Los nidos de hipogrifo están en las colinas al sur, alrededor de {area:2522}; cada uno contiene un huevo para {object:142071}.",
		["The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body."] = "Los hipogrifos anidan en las colinas al suroeste del campamento. Mata uno y usa la Vasija de muisek de hipogrifo sobre su cuerpo.",
		["The treants wander the forest roads between the camp and the middle of {zone:1444}; there are only a few, so look along the paths."] = "Los antárboles deambulan por los caminos del bosque entre el campamento y el centro de {zone:1444}; hay pocos, así que búscalos por los senderos.",
		["The {object:142071}, in the middle of town"] = "{object:142071}, en el centro del pueblo",
		["To {object:3202}"] = "A {object:3202}",
		["Undamaged Hippogryph Feathers"] = "Plumas de hipogrifo sin estropear",
		["Upstairs"] = "Arriba",
		["Wandering Forest Walkers"] = "Caminabosques deambulantes",
		["Xylem's tower stands on the cliff just north of {area:1237}; the path winds up its north side."] = "La torre de Xylem está en el acantilado justo al norte de {area:1237}; el sendero sube serpenteando por su lado norte.",
		["Zeppelin to {zone:1454}"] = "Zepelín a {zone:1454}",
		["{npc:6986}, the Drag"] = "{npc:6986}, calle comercial de Orgrimmar",
		["{npc:7010}, the Drag"] = "{npc:7010}, la Calle Mayor",
		["{npc:7010}, the Drag: if you still carry it"] = "{npc:7010}, la Calle Mayor: si aún lo llevas",
		["{npc:7776}: the bears are in {zone:1448}"] = "{npc:7776}: los osos están en {zone:1448}",
		["{npc:7876}'s tar and Pestlezugg's samples come from {zone:1449}."] = "El alquitrán de {npc:7876} y las muestras de Morterozugg vienen de {zone:1449}.",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, junto al maestro de jinetes del viento",
		["{npc:8395}, at the east edge of the camp: no experience, only a teleport to Azshara Tower"] = "{npc:8395}, en el borde este del campamento: no da experiencia, solo un teletransporte a una torre de Azshara",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}, en {object:172960}",
		["{quest:3761} is gathered in the next guide; {npc:4046}'s payment goes back to {npc:8587} later."] = "{quest:3761} se reúne en la siguiente guía; el pago de {npc:4046} vuelve a {npc:8587} más adelante.",
		["{zone:1454} flight master"] = "Maestro de vuelo de {zone:1454}",
} end)()
t.guides["forever/horde/50-60/01-un-goro-crater"] = (function() return {
		["Back a few steps west to Felstone Farm, the first farm along the road; {npc:10778} waits in the house."] = "Regresa unos pasos al oeste a la Granja Piedramácula, la primera granja del camino; {npc:10778} espera en la casa.",
		["Back north-east to {area:251}."] = "Regresa al noreste a {area:251}.",
		["Below ground"] = "Bajo tierra",
		["Bridge into {area:254}"] = "Puente hacia {area:254}",
		["Cross the south of the crater to the pylon on the western cliffs."] = "Cruza el sur del cráter hasta la torre de cristal de los acantilados del oeste.",
		["Eastern Pylon"] = "Torre de cristal del Este",
		["Fly to {area:272}"] = "Vuela a {area:272}",
		["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "Sigue los acantilados al sur hasta {quest:3821}, la colina de los ogros Pirontraña. Los restos de {npc:9136} están al pie.",
		["From here on pick up every Power Crystal (blue, green, red, yellow) and every {quest:3761} pile you pass: 25 soil in all, 20 for Hamuul and 5 for Pestlezugg."] = "Desde aquí recoge cada Cristal de poder (azul, verde, rojo, amarillo) y cada montón de {quest:3761} que pases: 25 de tierra en total, 20 para Hamuul y 5 para Morterozugg.",
		["From the {area:152}, follow the road east into the {zone:1422}. The Scarlet Crusade's tents stand just past Felstone Farm, between {area:199} and {area:200}. Torch the command tent with the {object:176092} and plant the Scourge banner."] = "Desde {area:152}, sigue el camino al este hacia {zone:1422}. Las tiendas de la Cruzada Escarlata están justo pasando la Granja Piedramácula, entre {area:199} y {area:200}. Quema la tienda de mando con {object:176092} y planta el estandarte de la Plaga.",
		["From the {area:1938} ride west to the long ramp that winds down into {zone:1449}, then follow the crater's north wall to {area:541}, a camp in the cliff caves. Everyone here is neutral."] = "Desde {area:1938} cabalga al oeste hasta la larga rampa que baja serpenteando a {zone:1449}; luego sigue la pared norte del cráter hasta {area:541}, un campamento en las cuevas del acantilado. Aquí todos son neutrales.",
		["Gorillas"] = "Gorilas",
		["Into the {zone:1427}"] = "Hacia {zone:1427}",
		["Into {zone:1449}"] = "Hacia {zone:1449}",
		["Keep the parcel: {npc:10781} is in the {zone:1458}. Keep {quest:5901}: its termite mounds are in {area:2627}, on the next guide's ride to Tirion. The next guide starts with {npc:10739} by the {area:202}, south-east of here."] = "Guarda el paquete: {npc:10781} está en {zone:1458}. Guarda {quest:5901}: sus montículos de termitas están en {area:2627}, en el camino hacia Tirion de la siguiente guía. La siguiente guía empieza con {npc:10739} junto a {area:202}, al sureste de aquí.",
		["Keep {npc:10267}'s letter: {quest:4808} is in {area:2255}, {zone:1452}."] = "Guarda la carta de {npc:10267}: {quest:4808} está en {area:2255}, {zone:1452}.",
		["Keep {npc:9118}'s {quest:4147} and {npc:8737}'s letter for later guides."] = "Guarda {quest:4147} de {npc:9118} y la carta de {npc:8737} para guías posteriores.",
		["Lar'korwi Mates"] = "Compañeras de Lar'korwi ({npc:9683})",
		["Lashers and Threshers"] = "Azotadores y Trilladores",
		["Leave the {zone:1458} and ride east along the road through {zone:1420} to the {area:152}, the Forsaken fort on the border."] = "Sal de {zone:1458} y cabalga al este por el camino a través de {zone:1420} hasta {area:152}, el fuerte de los Renegados en la frontera.",
		["North of Torwa, a dead Threshadon lies by the water."] = "Al norte de Torwa, un trillanodonte muerto yace junto al agua.",
		["Northern Pylon"] = "Torre de cristal del Norte",
		["Out of the refuge"] = "Fuera del refugio",
		["Power Crystals and soil"] = "Cristales de poder y tierra",
		["Pterrordax"] = "Pterrordáctilo",
		["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "Baja por el lado este del cráter hasta la torre de cristal de los acantilados del este.",
		["Ride north along the east side. Bloodpetal Lashers and Threshers fill the jungle."] = "Cabalga al norte por el lado este. Los Azotadores y Trilladores Sangrepétalo llenan la selva.",
		["Ride north back to {area:541}."] = "Cabalga al norte de vuelta a {area:541}.",
		["Scarlet forward camp"] = "Campamento avanzado Escarlata",
		["Stegodons and ravasaurs"] = "Stegodons y ravasaurios",
		["Take a {object:176092} from the crate next to Derrington for {quest:5096}, done on the way back. Equip the {quest:5405}: Scourgestones only drop while you wear it."] = "Toma una {object:176092} del cajón junto a Derrington para {quest:5096}, que se hace al volver. Equípate la {quest:5405}: las Piedras de la Plaga solo caen mientras la llevas.",
		["Take the pass out of {area:340}'s west side into the {zone:1427}, then ride south across the gorge to the long bridge into {area:254}. Inside, follow the chain walkways down and leave through the southern exit; stay off the paths to the dungeon portals."] = "Toma el paso del lado oeste de {area:340} hacia {zone:1427}; luego cabalga al sur cruzando la garganta hasta el largo puente hacia {area:254}. Dentro, baja por las pasarelas de cadenas y sal por la salida sur; evita los caminos a los portales de los calabozos.",
		["The Lar'korwi Mates prowl the jungle north-west of {npc:9619}."] = "Las Compañeras de Lar'korwi ({npc:9683}) merodean la selva al noroeste de {npc:9619}.",
		["The crystal clusters stand all over the crater, many around {area:537}. Take a few extra of each colour for the pylons."] = "Los grupos de cristales están por todo el cráter, muchos alrededor de {area:537}. Toma algunos extra de cada color para las torres de cristal.",
		["The expedition's crate sits at an abandoned camp in the eastern jungle."] = "El cajón de la expedición está en un campamento abandonado en la selva del este.",
		["The expedition's lost equipment lies in the south-west jungle."] = "El equipo perdido de la expedición está en la selva del suroeste.",
		["The gorillas live on the north-east plateau. Stay out of the deepest cave: {npc:9622} lives there."] = "Los gorilas viven en la meseta del noreste. No entres en la cueva más profunda: allí vive {npc:9622}.",
		["The mountain lets you out beside {area:252}, full of 55-57 orcs. Follow the road east along the northern cliffs to the Horde camp at {area:251}."] = "La montaña te deja junto a {area:252}, llena de orcos de nivel 55-57. Sigue el camino al este por los acantilados del norte hasta el campamento de la Horda en {area:251}.",
		["The pylon stands on the slope east of the refuge."] = "La torre de cristal está en la ladera al este del refugio.",
		["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "La balsa está en la orilla del lago del sureste; la mochila pequeña está en el agua a su lado.",
		["The tar pits lie just south of the refuge. Tar Beasts, Lurkers and Creepers drop the {item:11834}."] = "Los pozos de alquitrán están justo al sur del refugio. Las Bestias, los Rondadores y los Trepadores de alquitrán sueltan el {item:11834}.",
		["Theodora's next errand goes to Lotwil east of town and then into {area:1584}: skip it."] = "El siguiente encargo de Theodora va con Lotwil al este del pueblo y luego a {area:1584}: omítelo.",
		["Upstairs"] = "Arriba",
		["Use the Mangled Journal to start it"] = "Usa Un diario destrozado para empezarla",
		["Western Pylon"] = "Torre de cristal del Oeste",
		["{item:11116}, a rare drop"] = "{item:11116}, botín raro",
		["{npc:10879}, the {object:36078}, beside the bat master"] = "{npc:10879}, en {object:36078}, junto al maestro de murciélagos",
		["{npc:6522}, the {object:36073}"] = "{npc:6522}, en {object:36073}",
		["{npc:7825} stands in the {object:36082}."] = "{npc:7825} está en {object:36082}.",
		["{npc:8390}, the Apothecarium: the vials fill in {zone:1447} later"] = "{npc:8390}, la botica real: los viales se llenan después en {zone:1447}",
		["{npc:9618}, just outside"] = "{npc:9618}, justo afuera",
		["{npc:9619} camps in the south-east corner of the crater."] = "{npc:9619} acampa en la esquina sureste del cráter.",
		["{npc:9623} then wants a {item:10561}, an {skill:202} item. Skip it unless you have one."] = "Luego {npc:9623} quiere una {item:10561}, un objeto de {skill:202}. Omítela salvo que tengas una.",
		["{npc:9998}, at the entrance"] = "{npc:9998}, en la entrada",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, en la entrada del refugio",
		["{quest:3822} walks the caves and mine tunnels of {quest:3821}; if he isn't home, clear the ogres around the entrances until he comes back."] = "{quest:3822} recorre las cuevas y túneles de mina de {quest:3821}; si no está, limpia los ogros de las entradas hasta que vuelva.",
		["{zone:1454} flight master"] = "Maestro de vuelo de {zone:1454}",
} end)()
t.guides["forever/horde/50-60/02-felwood"] = (function() return {
		["Back north to {area:1763}. Fill {npc:10922}'s canteen at the corrupted moonwell in the middle of the southern camp."] = "De vuelta al norte a {area:1763}. Llena la cantimplora de {npc:10922} en el pozo de la luna corrupto en medio del campamento sur.",
		["Below ground"] = "Bajo tierra",
		["Class trainer"] = "Instructor de clase",
		["Cross the river east into {area:2627}, the ruined town in the north-west of the {zone:1423}. {npc:12384} sits in a hut at its edge."] = "Cruza el río al este hacia {area:2627}, el pueblo en ruinas del noroeste de {zone:1423}. {npc:12384} está sentado en una choza en su borde.",
		["Derrington's watchtowers, Vandis' cauldron and {npc:11615}'s barrel are done on a later visit: keep them."] = "Las atalayas de Derrington, la caldera de Vandis y la barrica de {npc:11615} se hacen en una visita posterior: guárdalas.",
		["Diseased Grizzlies"] = "Osos pardos malsanos",
		["Diseased Wolves"] = "Lobos malsanos",
		["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "Al este de Puesto del Veneno, la cañada de cráteres donde deambulan las bestias entrópicas ({npc:9878}) y los horrores. Mata dos de cada uno y luego camina hasta cada uno de los tres cráteres de agua vil.",
		["Follow the road north-west. The south of {area:1763}, around its corrupted moonwell, is held by Shadow Council cultists, adepts, guardsmen and their hounds."] = "Sigue el camino al noroeste. El sur de {area:1763}, alrededor de su pozo de la luna corrupto, lo ocupan sectarios, adeptos, guardias y canes del Consejo de la Sombra.",
		["He camps by the {area:202}, south-east of {area:200}."] = "Acampa junto a {area:202}, al sureste de {area:200}.",
		["Keep the branch: {npc:5770} is in {zone:1456}."] = "Guarda la rama: {npc:5770} está en {zone:1456}.",
		["Keep {quest:5158}: {npc:5901} is in the {zone:1413}."] = "Guarda {quest:5158}: {npc:5901} está en {zone:1413}.",
		["Keep {quest:6164}: {npc:12384} takes it back on the {zone:1423} guide's {area:2627} stop."] = "Guarda {quest:6164}: {npc:12384} lo recibe de vuelta en la parada de {area:2627} de la guía de {zone:1423}.",
		["Keep {quest:8465} for {zone:1452}."] = "Guarda {quest:8465} para {zone:1452}.",
		["Knights and magi work the {area:192}; the medics and hunters camp south of it."] = "Los caballeros y magus trabajan en {area:192}; los médicos y cazadores acampan al sur.",
		["Northern crater"] = "Cráter norte",
		["Ride back south past {area:1763} to the corrupted moonwell of the Jadefire satyrs and fill {npc:9996}'s flasket there."] = "Cabalga de vuelta al sur pasando {area:1763} hasta el pozo de la luna corrupto de los sátiros Fuego de Jade y llena allí el frasquito de {npc:9996}.",
		["Ride back west over the river and on to the {area:192}; {npc:11610} hides on the hill north-east of it."] = "Cabalga de vuelta al oeste cruzando el río y sigue hasta {area:192}; {npc:11610} se esconde en la colina al noreste.",
		["Ride north along the eastern hills; {npc:1855} lives in a small house by the {area:2619}, at the border with the {zone:1423}."] = "Cabalga al norte por las colinas del este; {npc:1855} vive en una casita junto a {area:2619}, en la frontera con {zone:1423}.",
		["Ride north up the road again."] = "Cabalga otra vez al norte por el camino.",
		["Ride south-west past Felstone Farm and follow the road west back to the {area:152}."] = "Cabalga al suroeste pasando la granja de Piedramácula y sigue el camino al oeste de vuelta a {area:152}.",
		["Ride the road south through {zone:1448} to the Sanctuary."] = "Cabalga al sur por el camino a través de {zone:1448} hasta el Santuario.",
		["Ror stands at the far south end of {area:1761}."] = "Ror está en el extremo sur de {area:1761}.",
		["Scarlet Crusade"] = "Cruzada Escarlata",
		["Southern crater"] = "Cráter sur",
		["Southern {area:1763}"] = "Sur de {area:1763}",
		["Take the kitten to the same moonwell and release it there with {item:12565}; once it has turned into a {npc:10042}, bring it back to {npc:9996} and click on it to hand it over."] = "Lleva al gatito al mismo pozo de la luna y suéltalo allí con {item:12565}; cuando se haya convertido en un {npc:10042}, llévaselo a {npc:9996} y haz clic en él para entregarlo.",
		["The Deadwood furbolg village just west of the tunnel. {npc:9462} (56) stands among them. {npc:11557}, a friendly furbolg, sits at the north end of the village."] = "La aldea de los fúrbolgs Muertobosque justo al oeste del túnel. {npc:9462} (56) está entre ellos. {npc:11557}, un fúrbolg amistoso, está sentado en el extremo norte de la aldea.",
		["The Horde camp just north of {area:1763}."] = "El campamento de la Horda justo al norte de {area:1763}.",
		["The Jadefire moonwell"] = "El pozo de la luna Fuego de Jade",
		["The book lies in the ruined inn of {area:2627}; the undead in the town are 54-56, so pull them one at a time.\nThe Large Termite Mounds stand all over the hills east of {area:2627}. Use the {item:15042} on each mound you pass."] = "El libro está en la posada en ruinas de {area:2627}; los no-muertos del pueblo son de nivel 54-56, así que atráelos de uno en uno.\nLos Grandes Montículos de Termitas están por todas las colinas al este de {area:2627}. Usa el {item:15042} en cada montículo por el que pases.",
		["The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A {npc:10816} carries the outhouse key; {npc:10836} comes out when you open the outhouse and carries the cabinet key."] = "El diario está en la granja, el armario está dentro y el retrete está detrás. Un {npc:10816} lleva la llave del retrete; {npc:10836} sale cuando abres el retrete y lleva la llave del armario.",
		["The druids' camp is just past the border."] = "El campamento de los druidas está justo pasada la frontera.",
		["The road ends at {npc:15395}, outside the {area:1769} tunnel in the far north-east."] = "El camino termina en {npc:15395}, fuera del túnel de {area:1769}, en el extremo noreste.",
		["The wolves roam the fields between Andorhal, {area:200} and the {area:202}. Finish them on the ride back east."] = "Los lobos deambulan por los campos entre Andorhal, {area:200} y {area:202}. Termínalos en el camino de vuelta al este.",
		["The {area:1763} moonwell"] = "El pozo de la luna de {area:1763}",
		["Upstairs"] = "Arriba",
		["Western crater"] = "Cráter oeste",
		["Zeppelin to {zone:1454}"] = "Zepelín a {zone:1454}",
		["{area:200} farmhouse"] = "Granja de {area:200}",
		["{area:2627}: kill these as you meet them"] = "{area:2627}: mátalos cuando te los encuentres",
		["{item:12565}, at the Jadefire moonwell"] = "{item:12565}, en el pozo de la luna Fuego de Jade",
		["{npc:10306}: the owlbeasts are in {zone:1452}"] = "{npc:10306}: las lechubestias están en {zone:1452}",
		["{npc:11554}, at the south edge of the camp"] = "{npc:11554}, en el borde sur del campamento",
		["{npc:1855}'s hunts are in the {zone:1423}: keep them for later."] = "Las cacerías de {npc:1855} están en {zone:1423}: guárdalas para más adelante.",
		["{npc:8659} takes the ravasaur claws from Un'Goro; he stands in the {object:172960}, a short walk from the middle of the city."] = "{npc:8659} recibe las garras de ravasaurio de Un'Goro; está en {object:172960}, a poca distancia del centro de la ciudad.",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
		["{npc:9529}, on the west side of the Sanctuary"] = "{npc:9529}, en el lado oeste del Santuario",
		["{npc:9529}, on the west side of the camp"] = "{npc:9529}, en el lado oeste del campamento",
		["{npc:9996}'s kitten"] = "El gatito de {npc:9996}",
		["{quest:5408}: the {area:2627} undead drop them while you wear the {item:12846}"] = "{quest:5408}: los no-muertos de {area:2627} las sueltan mientras llevas puesta {item:12846}",
		["{zone:1454} flight master"] = "Maestro de vuelo de {zone:1454}",
} end)()
t.guides["forever/horde/50-60/03-winterspring"] = (function() return {
		["Back south to {npc:7775}. Keep the elixir and don't drink it yet: it kills you, and that is how you meet Gaeriyan by {area:976} later."] = "De vuelta al sur con {npc:7775}. Guarda el elixir y no lo bebas todavía: te mata, y así es como conocerás a Gaeriyan junto a {area:976} más adelante.",
		["Below ground"] = "Bajo tierra",
		["Chillwind chimaeras"] = "Quimeras Viento Gélido",
		["Fly to {area:1099}"] = "Vuela a {area:1099}",
		["Fly to {area:1637}"] = "Vuela a {area:1637}",
		["Fly to {area:1638}"] = "Vuela a {area:1638}",
		["Gregor's quests lead to other zones: keep them."] = "Las misiones de Gregor llevan a otras zonas: guárdalas.",
		["Ice Thistle yetis"] = "Yetis Cardo Nevado",
		["In the {object:172958}."] = "En {object:172958}.",
		["Linken's letter"] = "La carta de Linken",
		["Matriarchs and Patriarchs hit hard: pull them one at a time."] = "Las Matriarcas y Patriarcas pegan duro: atráelos de uno en uno.",
		["Pathfinders, Den Watchers and Totemics share the furbolg camps around the hot springs; Ragged Owlbeasts roam the slopes between them. Kill Totemics first. Save every {item:14047} you loot for Meilosh."] = "Los Abrecaminos, Vigías del cubil y Totémicos comparten los campamentos furbolg alrededor de las aguas termales; las Lechubestias pulgosas ({npc:7450}) recorren las laderas entre ellos. Mata primero a los Totémicos. Guarda todo el {item:14047} que obtengas para Meilosh.",
		["Pristine Yeti Horns"] = "Cuernos prístinos de yeti ({item:12367})",
		["Raging Owlbeasts"] = "Lechubestias enfurecidas ({npc:7451})",
		["The chimaeras roam the snowfields south and west of {area:2255}. Stay clear of {area:2245}'s cave: its blue dragonkin are elite."] = "Las quimeras recorren los campos nevados al sur y oeste de {area:2255}. Aléjate de la cueva de {area:2245}: sus dragonantes azules son élite.",
		["The furbolg village fills the valley north-east of {area:2255}. Kill Shamans first; they heal. {npc:10738} in the cave at the back is elite: stay out."] = "El poblado furbolg llena el valle al noreste de {area:2255}. Mata primero a los Chamanes; curan. {npc:10738}, en la cueva del fondo, es élite: no entres.",
		["The yeti hills start just south-east of {area:2255}. Every yeti drops fur; only Matriarchs and Patriarchs drop horns, so keep those for after the turn-in."] = "Las colinas de los yetis empiezan justo al sureste de {area:2255}. Todos los yetis sueltan pelaje; solo las Matriarcas y Patriarcas sueltan cuernos, así que guárdalos para después de la entrega.",
		["The {item:11242} grows inside a ruined building north of {npc:7775}'s camp, east of the harpies' {area:1114}: climb in through the broken part of its wall."] = "La {item:11242} crece dentro de un edificio en ruinas al norte del campamento de {npc:7775}, al este de {area:1114} de las arpías: entra por la parte rota de su muro.",
		["Umi's third prank targets goblins in {area:976} and Un'Goro: keep it for later."] = "La tercera broma de Umi va contra goblins de {area:976} y Un'Goro: guárdala para después.",
		["{area:2408} flight master"] = "Maestro de vuelo de {area:2408}",
		["{item:11243}, {npc:7775}'s reward"] = "{item:11243}, recompensa de {npc:7775}",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{npc:3033} en {area:1639}; {npc:246344}",
		["{quest:1123} waits in {zone:1450}: keep it for later."] = "{quest:1123} te espera en {zone:1450}: guárdala para después.",
		["{quest:3909} comes from {npc:7775} in {zone:1444}, later in this guide."] = "{quest:3909} viene de {npc:7775} en {zone:1444}, más adelante en esta guía.",
		["{quest:5084} is turned in at the {object:176091} in {zone:1448}, on a later trip."] = "{quest:5084} se entrega en {object:176091}, en {zone:1448}, en un viaje posterior.",
		["{quest:8471}, a rare drop from the Winterfall furbolgs"] = "{quest:8471}, botín raro de los furbolgs Nevada",
} end)()
t.guides["forever/horde/50-60/04-azshara"] = (function() return {
		["Cleansed Water goes to the {area:2479} in {zone:1448}: keep it for later."] = "El agua purificada va a {area:2479}, en {zone:1448}: guárdala para después.",
