		["Fly to {area:1637}"] = "Vuela a {area:1637}",
		["Fly to {area:392}"] = "Vuela a {area:392}",
		["Fly to {zone:1454}; {npc:4485} is in the {object:172958}."] = "Vuela a {zone:1454}; {npc:4485} está en {object:172958}.",
		["Lady Sylvanas holds the {object:36126}."] = "Lady Sylvanas está en {object:36126}.",
		["Liv's workshop is at the north end of {area:392}'s docks; {object:149036} stands inside it."] = "El taller de Liv está en el extremo norte de los muelles de {area:392}; {object:149036} está adentro.",
		["Ride back west to {area:1237}."] = "Regresa cabalgando al oeste a {area:1237}.",
		["Ride east to the ruins on the coast. Fill Cuely's four vials at the tide pools along the shore; Spitelash naga patrol between them."] = "Cabalga al este hasta las ruinas de la costa. Llena los cuatro viales de Cuely en las pozas de marea a lo largo de la orilla; las nagas Látigo de Ira patrullan entre ellas.",
		["The blood elves camp on the cliffs in the north-east, by the {area:1227}."] = "Los elfos de sangre acampan en los acantilados del noreste, junto a {area:1227}.",
		["Upstairs"] = "Arriba",
		["{npc:15188}, {object:172957}: keep it for {zone:1451}"] = "{npc:15188}, {object:172957}: guárdala para {zone:1451}",
		["{npc:256386}'s crates"] = "Las cajas de {npc:256386}",
		["{npc:5901} camps on the shore just north of {area:392}."] = "{npc:5901} acampa en la orilla justo al norte de {area:392}.",
		["{npc:8393}, beside him"] = "{npc:8393}, a su lado",
		["{npc:8403}, nearby"] = "{npc:8403}, cerca",
		["{npc:8578}'s camp"] = "Campamento de {npc:8578}",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
		["{quest:5050} goes back to {npc:10778} in the {zone:1422}: keep it."] = "{quest:5050} regresa con {npc:10778} en {zone:1422}: guárdala.",
		["{zone:1454} flight master"] = "Maestro de vuelo de {zone:1454}",
} end)()
t.guides["forever/horde/50-60/05-eastern-plaguelands"] = (function() return {
		["Back through the tunnel and take the {zone:1452} exit, then ride south to {area:2246}."] = "Regresa por el túnel y toma la salida a {zone:1452}; luego cabalga al sur hasta {area:2246}.",
		["Back to {area:2268}"] = "De vuelta a {area:2268}",
		["Below ground"] = "Bajo tierra",
		["Both quests lead to {zone:1451}: keep them."] = "Ambas misiones llevan a {zone:1451}: guárdalas.",
		["Careful: {npc:10411} goes invisible when out of combat and calls Rockwing Gargoyles once a fight starts. Only 3 exist and they respawn every 15 min."] = "Cuidado: {npc:10411} se vuelve invisible fuera de combate y llama a Gárgolas Alarroca en cuanto empieza una pelea. Solo existen 3 y reaparecen cada 15 min.",
		["Class trainer"] = "Instructor de clase",
		["Drink the {item:11243} at the graveyard just east of {area:976}: it kills you, and only as a ghost can you see {npc:9299}, in a rocky crevice in the hills due north of it. Talk to him there, then run back to your body and resurrect: the Conspicuous Gravestone he sends you to stands in that graveyard."] = "Bebe el {item:11243} en el cementerio justo al este de {area:976}: te mata, y solo como fantasma puedes ver a {npc:9299}, en una grieta rocosa en las colinas justo al norte de allí. Habla con él allí, luego corre de vuelta a tu cuerpo y resucita: la Lápida llamativa a la que te envía está en ese cementerio.",
		["Fly to {area:1638}"] = "Vuela a {area:1638}",
		["Fly to {area:2268}"] = "Vuela a {area:2268}",
		["Fly to {area:272}"] = "Vuela a {area:272}",
		["Fly to {area:976}"] = "Vuela a {area:976}",
		["Follow the road east from the {zone:1422}, over the river and across the whole {zone:1423}, to the {object:92525}'s chapel in the far east."] = "Sigue el camino al este desde {zone:1422}, cruza el río y atraviesa todas {zone:1423} hasta la capilla de {object:92525}, en el extremo este.",
		["Free Darrowshire Spirits: talk to them"] = "Libera a los Espíritus de Darrowshire: habla con ellos",
		["Frenzied Plaguehounds and Monstrous Plaguebats share the fields around {area:2272} and {area:2271}, south of {area:2273}."] = "Los Canes de peste demenciados ({npc:8598}) y los Murcipestes monstruosos ({npc:8602}) comparten los campos alrededor de {area:2272} y {area:2271}, al sur de {area:2273}.",
		["Go through {area:1769} and take the {zone:1450} branch of the tunnel. {npc:11801} is in {area:2361}."] = "Atraviesa {area:1769} y toma el ramal del túnel hacia {zone:1450}. {npc:11801} está en {area:2361}.",
		["Keep {quest:5152}: {npc:10927} lives at {area:197} in the {zone:1422}."] = "Guarda {quest:5152}: {npc:10927} vive en {area:197}, en {zone:1422}.",
		["Moontouched Owlbeasts"] = "Lechubestias lunadón ({npc:7453})",
		["Only if a {quest:8471} dropped for you: {npc:11558} waits at the {zone:1448} entrance of {area:1769}, and speaks to you only at Neutral with the Timbermaw."] = "Solo si te salió un {quest:8471}: {npc:11558} espera en la entrada de {area:1769} del lado de {zone:1448}, y solo te habla si eres Neutral con los Fauces de Madera.",
		["Plaguehound Runts and Plaguebats roam the hills north of the {area:2260}, Carrion Grubs crawl among them; work north toward {area:2627}."] = "Los Cachorros de can de peste ({npc:8596}) y los Murcipestes ({npc:8600}) recorren las colinas al norte de {area:2260}, y las Larvas carroñeras ({npc:8603}) se arrastran entre ellos; avanza al norte hacia {area:2627}.",
		["Ride back south to {area:272} and fly to {area:2268}."] = "Cabalga de vuelta al sur hasta {area:272} y vuela a {area:2268}.",
		["Ride east to {area:2255} and north out of it; the Moontouched Owlbeasts roam the hills of {area:2241}'s southern slopes. Pull them one at a time."] = "Cabalga al este hasta {area:2255} y sal al norte; las Lechubestias lunadón ({npc:7453}) recorren las colinas de las laderas sur de {area:2241}. Atráelas de una en una.",
		["Ride north up the road from {area:272}. {npc:10927}'s house stands by the road at {area:197}, and {npc:10936}'s monument is in the graveyard behind it."] = "Cabalga al norte por el camino desde {area:272}. La casa de {npc:10927} está junto al camino en {area:197}, y el monumento de {npc:10936} está en el cementerio detrás de ella.",
		["Ride north-west into Andorhal. {npc:10667} waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges."] = "Cabalga al noroeste hacia Andorhal. {npc:10667} espera en la posada en ruinas del lado oeste del pueblo; los esqueletos de adentro son de nivel 54-57, así que mantente en las orillas.",
		["Ride south from the lodge to {area:2264}, on the road. {item:15447} spoils within ten minutes: kill the town's Scourge quickly and grind the seven pieces with the {item:15454} at once.\nCareful: Unseen Servants call for help within 25 yd once they drop to 40% health. Out of combat they also turn invisible with {spell:10228}. If a call for help happens inside the town, a large number of mobs can join the fight. Fighting near the outskirts lowers this risk.\nWith {quest:5211} in your log (from {npc:11063} at the start of this guide), the Scourge around the town leave Darrowshire Spirits: talk to each one to free it. Free them before you start on the {item:15447}."] = "Cabalga hacia el sur desde el refugio hasta {area:2264}, por el camino. {item:15447} se echa a perder en diez minutos: mata rápido a la Plaga del pueblo y muele las siete piezas con el {item:15454} de inmediato.\nCuidado: los Sirvientes invisibles piden ayuda en un radio de 25 m cuando bajan al 40% de salud. Fuera de combate también se vuelven invisibles con {spell:10228}. Si piden ayuda dentro del pueblo, muchos enemigos pueden unirse a la pelea. Luchar en las afueras reduce ese riesgo.\nCon {quest:5211} en tu registro (de {npc:11063} al inicio de esta guía), la Plaga alrededor del pueblo deja Espíritus de Darrowshire: habla con cada uno para liberarlo. Libéralos antes de empezar con {item:15447}.",
		["Ride west to the {area:2260}."] = "Cabalga al oeste hasta {area:2260}.",
		["Scare {npc:7583} with {item:12928}"] = "Asusta a {npc:7583} con {item:12928}",
		["The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one."] = "Los Anales están entre los Tomos mohosos del ayuntamiento de Andorhal; ábrelos hasta encontrar el correcto.",
		["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "La cabeza de la muñeca y sus dos lados están en las casas alrededor de {npc:10926}; únelos desde tus bolsas.",
		["The pass from Un'Goro comes out at {area:3077}, the graveyard in north-east {zone:1451}. {npc:13220} stands among the graves."] = "El paso desde Un'Goro sale en {area:3077}, el cementerio del noreste de {zone:1451}. {npc:13220} está entre las tumbas.",
		["To {area:197}"] = "Hacia {area:197}",
		["Upstairs"] = "Arriba",
		["Use {item:12928} on {npc:7583}, the goblin girl in {area:976}. {npc:10977} and {npc:10978} are scared later in the route."] = "Usa {item:12928} en {npc:7583}, la niña goblin de {area:976}. {npc:10977} y {npc:10978} se asustan más adelante en la ruta.",
		["Zaeldarr lurks just west of {area:2262}."] = "Zaeldarr acecha justo al oeste de {area:2262}.",
		["Zeppelin to {zone:1454}"] = "Zepelín a {zone:1454}",
		["a message for {npc:11063} at {area:2268}"] = "un mensaje para {npc:11063} en {area:2268}",
		["{npc:10926}'s ghost stands in the ruins of {area:2262}, in the south-west."] = "El fantasma de {npc:10926} está en las ruinas de {area:2262}, al suroeste.",
		["{npc:10927}, upstairs"] = "{npc:10927}, en el piso de arriba",
		["{npc:11140} the ghost stands by a hut in {area:2627}, in the north-west corner."] = "El fantasma {npc:11140} está junto a una choza en {area:2627}, en la esquina noroeste.",
		["{npc:15193}'s champion holds the {area:2260} farmhouse, north of the {area:2261}."] = "El campeón de {npc:15193} ocupa la granja de {area:2260}, al norte de {area:2261}.",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{npc:3033} en {area:1639}; {npc:246344}",
		["{npc:7771} camps by the {area:1336} road, south of {area:976}."] = "{npc:7771} acampa junto al camino de {area:1336}, al sur de {area:976}.",
		["{quest:3914} goes back to {npc:8737} in Un'Goro: keep it."] = "{quest:3914} regresa con {npc:8737} en Un'Goro: guárdala.",
		["{quest:5168}'s items lie in the later Plaguelands zones: keep it."] = "Los objetos de {quest:5168} están en las siguientes zonas de las Tierras de la Peste: guárdala.",
		["{quest:5211}'s spirits come with the {area:2264} stop later in this guide: keep it."] = "Los espíritus de {quest:5211} llegan con la parada en {area:2264} más adelante en esta guía: guárdala.",
		["{zone:1454} flight master"] = "Maestro de vuelo de {zone:1454}",
} end)()
t.guides["forever/horde/50-60/06-silithus"] = (function() return {
		["A torn scroll lies at the entrance of the {area:2261}, the crypt south of the {area:2260}."] = "Un pergamino roto está en la entrada de {area:2261}, la cripta al sur de {area:2260}.",
		["Andorhal watchtowers and silos"] = "Torres de vigilancia y silos de Andorhal",
		["Back to Southwind and climb the tower. Stirring the hive at the top brings out Hive'Ashi Ambushers; one carries the {item:17346}."] = "Regresa a Aldea Viento del Sur y sube a la torre. Al remover la colmena de la cima salen Emboscadores Colmen'Ashi ({npc:13301}); uno lleva {item:17346}.",
		["Back to {area:3425}"] = "De vuelta a {area:3425}",
		["Below ground"] = "Bajo tierra",
		["Class trainer"] = "Instructor de clase",
		["Dredge Crushers and Pincers"] = "Trituradores deslizantes ({npc:11741}) y Tenazarios",
		["Dredge Strikers, Stonelash Scorpids and Sand Skitterers share the sands just north of the hold."] = "Los Asediadores deslizantes ({npc:11740}), los Escórpidos Latipiedra ({npc:11735}) y los Arácnidos de arena ({npc:11738}) comparten las arenas justo al norte del fuerte.",
		["East along the road, {npc:11077} guards the cauldron at {area:200}."] = "Al este por el camino, {npc:11077} custodia el caldero de {area:200}.",
		["Escort {npc:9999}"] = "Escolta a {npc:9999}",
		["Flayers and Rock Stalkers"] = "Despellejadores y Acecharrocas ({npc:11739})",
		["Fly to {area:1637}"] = "Vuela a {area:1637}",
		["Fly to {area:976}. Still carrying {quest:2741}? The machine stands in the middle of town."] = "Vuela a {area:976}. ¿Todavía llevas {quest:2741}? La máquina está en el centro del pueblo.",
		["Hameya's mound"] = "El montículo de Hameya",
		["Hameya's scroll"] = "El pergamino de Hameya",
		["Head north along the western dunes; Dredge Crushers and Stonelash Pincers range from here back toward the hold."] = "Ve al norte por las dunas del oeste; los Trituradores deslizantes ({npc:11741}) y los Tenazarios Latipiedra ({npc:11736}) están desde aquí hasta el fuerte.",
		["Keep the bait: {npc:9684} is level 56, and the second loop passes his lair."] = "Guarda el cebo: {npc:9684} es de nivel 56 y la segunda vuelta pasa por su guarida.",
		["Keep {quest:3942}: {npc:9116} is at the {area:2479}, on the next guide's way through {zone:1448}."] = "Guarda {quest:3942}: {npc:9116} está en {area:2479}, de camino por {zone:1448} en la siguiente guía.",
		["Lead {npc:9999} north to {area:541}. When he faints, use {item:11804} on him to wake him."] = "Lleva a {npc:9999} al norte hasta {area:541}. Cuando se desmaye, usa {item:11804} en él para despertarlo.",
		["Mark {npc:10902} with the {item:12815}"] = "Marca {npc:10902} con {item:12815}",
		["Mark {npc:10903} with the {item:12815}"] = "Marca {npc:10903} con {item:12815}",
		["Mark {npc:10904} with the {item:12815}"] = "Marca {npc:10904} con {item:12815}",
		["Mark {npc:10905} with the {item:12815}"] = "Marca {npc:10905} con {item:12815}",
		["Radley and Durgen"] = "Radley y Durgen",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vent near the top, then ride back west to {npc:10302}."] = "Cabalga al este hasta {area:537}, súbelo y usa {npc:10541} en la grieta de lava cerca de la cima; luego regresa al oeste con {npc:10302}.",
		["Ride east to {npc:1855}'s hut by the {area:2619} and hear him out."] = "Cabalga al este hasta la choza de {npc:1855} junto a {area:2619} y escúchalo.",
		["Ride north-east to {area:3077}; you leave {zone:1451} through the pass beside it."] = "Cabalga al noreste hasta {area:3077}; sales de {zone:1451} por el paso a su lado.",
		["Ride north-east to {area:3447}."] = "Cabalga al noreste hasta {area:3447}.",
		["Ride north-west to {npc:1855}'s hut."] = "Cabalga al noroeste hasta la choza de {npc:1855}.",
		["Ride south into Andorhal. {npc:10667} waits in the ruined inn on the west side of town. Stand in the doorway of each of the four towers with the {item:12815} to mark it; keep to the edges of town. Use the {item:12627} by the silos in the middle of town to bring out Temporal Parasites."] = "Cabalga al sur hacia Andorhal. {npc:10667} espera en la posada en ruinas del lado oeste del pueblo. Párate en la entrada de cada una de las cuatro torres con {item:12815} para marcarla; no te alejes de las orillas del pueblo. Usa {item:12627} junto a los silos del centro del pueblo para hacer salir a los Parásitos temporales ({npc:10717}).",
		["Ride south-east to {area:3447} under the Un'Goro cliffs."] = "Cabalga al sureste hasta {area:3447}, bajo los acantilados de Un'Goro.",
		["Ride south-west to {npc:10667} in Andorhal."] = "Cabalga al suroeste hasta {npc:10667}, en Andorhal.",
		["Ride west to the Horde camp north of {area:2744}."] = "Cabalga al oeste hasta el campamento de la Horda al norte de {area:2744}.",
		["Scourge Champions"] = "Campeones de la Plaga ({npc:8529})",
		["Scourge Champions roam the {area:2270}, north of the chapel. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants."] = "Los Campeones de la Plaga ({npc:8529}) recorren {area:2270}, al norte de la capilla. Pasa {item:13156} de {npc:11063} sobre cada uno que mates: los cráneos que resuenan son los que él quiere.",
		["Silithyst geysers erupt across the southern desert. Walk into the Silithyst one leaves behind and carry it to the Horde's Silithyst Extractor at Kirika's camp; fighting or mounting drops it."] = "Los géiseres de silitista hacen erupción por el desierto del sur. Camina hacia el silitista que deja uno y llévalo al extractor de silitista de la Horda en el campamento de Kirika; si peleas o montas, lo sueltas.",
		["Stonelash Flayers and Rock Stalkers roam the dunes south-west of Kirika's camp."] = "Los Despellejadores Latipiedra ({npc:11737}) y los Acecharrocas ({npc:11739}) recorren las dunas al suroeste del campamento de Kirika.",
		["The glowing tablet fragments lie around the Twilight camp in the far north-west; the Dust Stormers and Desert Rumblers there drop them too."] = "Los fragmentos de tablilla brillantes están alrededor del campamento Crepuscular del extremo noroeste; los Agitadores sirocosos ({npc:11744}) y los Estruendores del desierto ({npc:11746}) de allí también los sueltan.",
		["The libram lies further north, on the way to {area:190}."] = "El libram está más al norte, de camino a {area:190}.",
		["The satchel lies in the mountains of the far south, past Bronzebeard's Encampment. Deathclasp, an elite scorpid, patrols near it: grab it while he is away."] = "La cartera está en las montañas del extremo sur, pasando el campamento de Barbabronce. Pinzamorten, un escórpido élite, patrulla cerca: tómala mientras esté lejos.",
		["The shield lies at {area:201}, south of {npc:1855}'s hut."] = "El escudo está en {area:201}, al sur de la choza de {npc:1855}.",
		["The spare texts from the cultists"] = "Los textos sobrantes de los sectarios",
		["Twilight Vanguard"] = "Vanguardia Crepuscular",
		["Upstairs"] = "Arriba",
		["Use {npc:10980} on {npc:10977}"] = "Usa {npc:10980} en {npc:10977}",
		["{npc:10302} sends you to {npc:9298} in {zone:1452}: keep it."] = "{npc:10302} te envía con {npc:9298} en {zone:1452}: guárdala.",
		["{npc:10302} the goblin sits at {area:543}, just east of the pylon."] = "El goblin {npc:10302} está en {area:543}, justo al este de la torre de cristal.",
		["{npc:10667}'s Battle of Darrowshire ends against elites. Skip it."] = "La Batalla de Villa Darrow de {npc:10667} termina contra élites. Omítela.",
		["{npc:15200} holds the camp in the west."] = "{npc:15200} ocupa el campamento del oeste.",
		["{npc:15306}, on the west side of the Hold"] = "{npc:15306}, en el lado oeste del fuerte",
		["{npc:9619} now asks for {npc:9622}'s pelt, back in the north-east cave: skip it."] = "Ahora {npc:9619} pide la piel de {npc:9622}, en la cueva del noreste: omítela.",
		["{npc:9684}'s lair is just south of the pylon. Use {npc:9619}'s bait there; {npc:9684} is level 56 and hits hard, so start at full health."] = "La guarida de {npc:9684} está justo al sur de la torre de cristal. Usa allí el cebo de {npc:9619}; {npc:9684} es de nivel 56 y pega fuerte, así que empieza con la salud llena.",
		["{npc:9999} sits on the ridge, lost and exhausted."] = "{npc:9999} está sentado en la cresta, perdido y agotado.",
} end)()
t.guides["forever/horde/50-60/07-felwood"] = (function() return {
		["Any Winterfall furbolg can carry the beads; the camps just south of {npc:11556} are the closest."] = "Cualquier furbolg Nevada puede llevar las cuentas; los campamentos justo al sur de {npc:11556} son los más cercanos.",
		["Back into the Timbermaw tunnel and take the {zone:1452} exit; {npc:9298} camps by the hot springs just outside."] = "Vuelve al túnel de los Fauces de Madera y toma la salida a {zone:1452}; {npc:9298} acampa junto a las fuentes termales justo afuera.",
		["Back south to the Sanctuary, a short ride."] = "Regresa al sur al Santuario, a poca distancia.",
		["Below ground"] = "Bajo tierra",
		["Class trainer"] = "Instructor de clase",
		["Corrupted Soul Shards from the cultists, {quest:5887}"] = "Fragmentos de alma corruptos de los cultistas, {quest:5887}",
		["Dungeon instead of grinding"] = "Calabozo en vez de matar monstruos",
		["Fly to {area:431} and ride north-west along the road out of {zone:1440} into {zone:1448}. The {area:2479} is the druids' camp just past the border."] = "Vuela a {area:431} y cabalga al noroeste por el camino que sale de {zone:1440} hacia {zone:1448}. {area:2479} es el campamento de los druidas justo pasando la frontera.",
		["From Krakle in Un'Goro"] = "De Krakle, en Un'Goro",
		["Frostfire Winterfall camp"] = "Campamento Nevada de los Baños de Fuego de Escarcha",
		["Grind to 60"] = "Sube a nivel 60",
		["In the {object:172961}."] = "En {object:172961}.",
		["In {zone:1454}: fly from {area:2255}"] = "En {zone:1454}: vuela desde {area:2255}",
		["In {zone:1456}: fly from {area:2255}"] = "En {zone:1456}: vuela desde {area:2255}",
		["On the way back south to {npc:10922}, {npc:9529} takes the shards on the west side of the Sanctuary."] = "De regreso al sur hacia {npc:10922}, {npc:9529} recibe los fragmentos en el lado oeste del Santuario.",
		["Optional. Running {area:2279}, {area:2057}, Lower Blackrock Spire or {area:1584} with a group instead of grinding gets you there faster."] = "Opcional. Hacer {area:2279}, {area:2057}, la parte baja de Cumbre de Roca Negra o {area:1584} en grupo en lugar de farmear te lleva allí más rápido.",
		["Optional: with a group, a 55-60 dungeon replaces the grind below."] = "Opcional: en grupo, un calabozo de nivel 55-60 sustituye a la matanza de abajo.",
		["Ride back west to {area:2246}."] = "Regresa cabalgando al oeste a {area:2246}.",
		["Ride east along the road to {area:2255}."] = "Cabalga al este por el camino hasta {area:2255}.",
		["Ride east, then south down {area:2249}. The Frostmaul giants there are elite level 59: keep to the middle and keep moving. The strange source is at the mouth of {area:2256}, at the south end."] = "Cabalga al este y luego al sur por {area:2249}. Los gigantes Machacahielo de allí son élite de nivel 59: mantente en el centro y no te detengas. La fuente extraña está en la entrada de {area:2256}, en el extremo sur.",
		["Ride north along the road, past {area:1763}, to {area:1997}."] = "Cabalga al norte por el camino, pasando {area:1763}, hasta {area:1997}.",
		["South to the Sanctuary once more."] = "Al sur, al Santuario, una vez más.",
		["The quests run out here. Rabid Shardtooths prowl {area:2249} in southern {zone:1452}, south of the road from {area:2255}."] = "Aquí se acaban las misiones. Los Dentoesquirlas rabiosos merodean en {area:2249}, al sur de {zone:1452}, al sur del camino desde {area:2255}.",
		["The {area:2479}"] = "{area:2479}",
		["Through the Timbermaw tunnel to {zone:1450}. {npc:11939} reads in a house in {area:2361}."] = "Cruza el túnel de los Fauces de Madera hasta {zone:1450}. {npc:11939} lee en una casa de {area:2361}.",
		["Zeppelin to {zone:1454}"] = "Zepelín a {zone:1454}",
		["grind on {npc:7446} at {area:2249}, {zone:1452}"] = "mata {npc:7446} en {area:2249}, {zone:1452}",
		["{npc:10306}'s next {quest:4741} would bring you back here from {zone:1452}. Skip it."] = "La siguiente misión de {npc:10306}, {quest:4741}, te haría volver aquí desde {zone:1452}. Omítela.",
		["{npc:11801}'s Shards of the Felvine needs {area:2577}. Skip it."] = "Fragmentos de gangrevid, de {npc:11801}, requiere {area:2577}. Omítela.",
		["{npc:9116}'s Silver Heart needs an {item:11173} from northern {zone:1448} and a ride back here. Skip it."] = "Corazón de plata, de {npc:9116}, requiere un {item:11173} del norte de {zone:1448} y volver aquí. Omítela.",
		["{npc:9298} next sends you after {npc:10738}, an elite in his cave. Skip it."] = "Luego {npc:9298} te envía tras {npc:10738}, un élite en su cueva. Omítela.",
		["{zone:1454} flight master"] = "Maestro de vuelo de {zone:1454}",
} end)()
t.guides["forever/horde/orc/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "Los Escórpidos acorazados ({npc:3126}) se arrastran por las llanuras al oeste de {area:362}. Domestica uno y luego regresa con {npc:3171}.",
		["Back to the Den"] = "De vuelta a la Guarida",
		["Back to {area:362}."] = "De vuelta a {area:362}.",
		["Below ground"] = "Bajo tierra",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}."] = "Los sectarios de Filo Ardiente ocupan las cuevas de {quest:827}; cualquiera suelta un {item:4871}. {npc:3204}, un brujo de nivel 14, está en lo más profundo y suelta {item:4903}.",
		["Class trainer"] = "Instructor de clase",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "Los acechadores viles recorren la ladera bajo la cueva, en el lado norte del valle.",
		["Free {npc:275811} and see her safely out of the crag"] = "Libera a {npc:275811} y acompáñala a salvo fuera del risco",
		["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle."] = "Ve al sur por las islas. Los ídolos loa están por todas las islas del sur; los Trols vudú y los Trols embrujados ({npc:3207}) los guardan y sueltan los Colgantes embrujados ({item:275724}). {quest:826} y la jaula de Minshina están en la isla más al sur.",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "Dentro de la cueva, sigue derecho en la primera bifurcación, luego a la derecha y sigue el arroyo a tu izquierda hasta la cascada: el pico brilla junto al agua, detrás de una columna de roca.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "Dentro de la cueva, sigue la pared derecha todo el camino, pasando sobre el arroyo: {npc:3183} espera al final.",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "La choza de Misha está al sur de los truenagartos. Los crocoliscos a lo largo de {area:814}, al oeste, llevan {item:4891}.",
		["Prickly pears"] = "Higos chumbos",
		["Quilboars and scouts hold the huts west of town; dustrunners and battleguards hold the camps farther west."] = "Los jabaespines y exploradores ocupan las chozas al oeste del pueblo; los polvorosos y guardias de batalla ocupan los campamentos más al oeste.",
		["Spitelash naga"] = "Nagas Látigo de Ira",
		["Tame it with the {item:15908}"] = "Domestícalo con {item:15908}",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}. {npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "El fuerte está en la costa al sureste de {area:362}. El hacha, el arco y el escudo de los asaltantes están en sus afueras. Los marineros y marines sueltan {item:4870}. {npc:3192} espera en lo alto del fuerte; su llave abre el cofre a su lado, que contiene {item:4881}.",
		["The prickly pears grow among the quilboar huts just west of town."] = "Los higos chumbos crecen entre las chozas de los jabaespines, justo al oeste del pueblo.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "Las armas están alrededor de la Guarida y del campo de entrenamiento; los Jabalíes jaspeados ({npc:3098}) recorren todo el fondo del valle.",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "{object:58595} está en {area:817}, entre los sectarios con los que acabas de pelear.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, beside the road north to {zone:1454}; any of them can drop a {item:6486}. {npc:5810} takes it when the next guide passes {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Los Truenagartos ({npc:3130}) y los Lomorrayos ({npc:3131}) pastan en {area:369}, junto al camino al norte hacia {zone:1454}; cualquiera puede soltar {item:6486}. {npc:5810} la recibe cuando la siguiente guía pasa por {area:379}.\nCuidado: Halikor, un élite de nivel 12, recorre {area:369} entre los lagartos: ubícalo antes de atraer.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, just west and south-west of {npc:3293}.\nFizzle holds the Burning Blade camp on {area:369}, north-west of {area:362}. Hunters: tame a {npc:3099} with the {item:15908} on the way.\nCareful: Burning Blade cultists surround Fizzle, some linked so they aggro in pairs, and they respawn quickly.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Los truenagartos y lomorrayos pastan en {area:369}, justo al oeste y suroeste de {npc:3293}.\nFizzle ocupa el campamento del Filo Ardiente en {area:369}, al noroeste de {area:362}. Cazadores: domestica un {npc:3099} con la {item:15908} en el camino.\nCuidado: los cultores del Filo Ardiente rodean a Fizzle, algunos vinculados, así que atacan en parejas, y reaparecen rápido.\nCuidado: Halikor, un élite de nivel 12, recorre {area:369} entre los lagartos: ubícalo antes de atraer.",
		["To {zone:1454}"] = "A {zone:1454}",
		["Training weapons and boars"] = "Armas de entrenamiento y jabalíes",
		["Upstairs"] = "Arriba",
		["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there.\nDurotar Tigers roam the isle as well as the shore south of Sen'jin, and the Taillasher eggs sit in nests on the isles and along the beach."] = "Cruza vadeando hasta la Isla del Eco del norte. La Matriarca acecha entre los raptores de allí.\nLos Tigres de Durotar recorren la isla y también la costa al sur de Sen'jin, y los huevos de Azotacola están en nidos en las islas y a lo largo de la playa.",
		["Wake {quest:5441} with the {item:16114}"] = "Despierta a {quest:5441} con {item:16114}",
		["the {object:654925} on the ground beside her"] = "{object:654925}, en el suelo a su lado",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366} está al oeste de Sen'jin. Los tres planes de ataque están en el suelo entre las tiendas de los centauros. {npc:275811} también está cautiva en el risco.",
		["{area:817}'s mouth"] = "Entrada de {area:817}",
		["{npc:10176}, where you start"] = "{npc:10176}, donde empiezas",
		["{npc:265809} camps just south of {area:362}. Sit by his campfire (/sit) until the {spell:1229451} buff appears. With a profession learned, {npc:265809} also offers its Camping 101, which its trainer takes: in {area:362} or in {zone:1454} at the start of the next guide."] = "{npc:265809} acampa justo al sur de {area:362}. Siéntate junto a su fogata (/sit) hasta que aparezca el beneficio {spell:1229451}. Si aprendiste una profesión, {npc:265809} también ofrece su Campismo 101, que se entrega a su instructor: en {area:362} o en {zone:1454} al inicio de la siguiente guía.",
		["{npc:265809}'s campfire"] = "La fogata de {npc:265809}",
		["{npc:265809}: for {npc:11025}"] = "{npc:265809}: para {npc:11025}",
		["{npc:265809}: for {npc:11046}"] = "{npc:265809}: para {npc:11046}",
		["{npc:265809}: for {npc:11066}"] = "{npc:265809}: para {npc:11066}",
		["{npc:265809}: for {npc:2855}"] = "{npc:265809}: para {npc:2855}",
		["{npc:265809}: for {npc:3175}"] = "{npc:265809}: para {npc:3175}",
		["{npc:265809}: for {npc:3365}"] = "{npc:265809}: para {npc:3365}",
		["{npc:265809}: for {npc:3404}"] = "{npc:265809}: para {npc:3404}",
		["{npc:265809}: for {npc:5943}"] = "{npc:265809}: para {npc:5943}",
		["{npc:265809}: for {npc:7088}"] = "{npc:265809}: para {npc:7088}",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881}: solo encantadores; el residuo se obtiene desencantando Colgantes embrujados ({item:275724})",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657} está en la orilla al este de {area:362}. El tridente, el estandarte y la daga están en la playa a su alrededor.",
		["{npc:3102} hooves"] = "Pezuñas de {npc:3102}",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}, de vuelta en {area:362}",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142}: {npc:275666}, un gigante de mar élite",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143} está justo dentro de la entrada de la cueva; {npc:3159}, al fondo de la cueva, detrás de él.",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143} espera dentro de la Guarida, el edificio justo al oeste de {npc:10176}.",
		["{npc:3147}, in the watchtower"] = "{npc:3147}, en la torre de vigilancia",
		["{npc:3153}, the warrior trainer beside the Den"] = "{npc:3153}, el instructor de guerreros junto a la Guarida",
		["{npc:3154}, the hunter trainer beside the Den"] = "{npc:3154}, el instructor de cazadores junto a la Guarida",
		["{npc:3155}, the rogue trainer in the Den"] = "{npc:3155}, el instructor de pícaros en la Guarida",
		["{npc:3156}, the warlock trainer at the back of the cave"] = "{npc:3156}, el instructor de brujos al fondo de la cueva",
		["{npc:3157}, the shaman trainer beside the Den"] = "{npc:3157}, el instructor de chamanes junto a la Guarida",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287} yace herido al pie de las colinas al noroeste de la Guarida.",
		["{npc:3294}, by the inn"] = "{npc:3294}, junto a la posada",
		["{npc:5875} stands in the {object:172960}, the canyon under the {object:172982}. Hand him the {item:6535}, then use the {item:7464} on the summoning circle beside him and defeat the voidwalker to bind it."] = "{npc:5875} está en {object:172960}, el cañón bajo {object:172982}. Entrégale {item:6535}, luego usa {item:7464} en el círculo de invocación junto a él y derrota al abisario para vincularlo.",
		["{npc:5884}, the mage trainer, at the entrance to the Den"] = "{npc:5884}, la instructora de magos, en la entrada de la Guarida",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887} está afuera de la Guarida. {area:639} es la colina justo al sur: bebe {item:6635} allí para ver a la {npc:5891} y luego llévale {item:6656} a {npc:5887}.",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887}: {npc:5873} y tu {item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}, en {area:639}",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786} está en el camino, en la salida este del valle.",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}, junto al fuego de cocina",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828} acampa en la colina al oeste de la playa de las nagas, al sur de {quest:827}.",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "La puerta principal de {zone:1454} está justo al oeste de {area:817}. {npc:5875} está en {object:172960}, el cañón bajo {object:172982}.",
} end)()
t.guides["forever/horde/skyborne/01-zephras-isle"] = (function() return {
		["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "Usa /sit junto a la fogata de {npc:263664} hasta obtener {spell:1229451}",
		["Aanders and the fallen guards are just south-west of the tower. Take Raani's feather and the Shadowsong signet from the bodies."] = "Aanders y los guardias caídos están justo al suroeste de la torre. Toma la pluma de Raani y el sello Cantosombrío de los cuerpos.",
		["Back at {quest:92529}: Stormcallers and {npc:251662} fill the village, the Supply Caches stand among the houses and {npc:251966} waits at its south-east end."] = "De vuelta en {quest:92529}: clamatormentas y {npc:251662} llenan la aldea, los alijos de suministros ({object:576179}) están entre las casas y {npc:251966} espera en el extremo sureste.",
		["Back to {area:16635}"] = "De vuelta a {area:16635}",
		["Back to {area:16638}"] = "De vuelta a {area:16638}",
		["Back to {npc:268592}. Wait for him to light the {npc:268762}, then carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638} before the timer runs out."] = "Vuelve con {npc:268592}. Espera a que encienda {npc:268762} y luego lleva la llama directo a {npc:268679}, junto a {npc:252382} en {area:16638}, antes de que se acabe el tiempo.",
		["Below ground"] = "Bajo tierra",
		["Cast {spell:1259686} near the {object:460001}"] = "Lanza {spell:1259686} cerca de {object:460001}",
		["Class trainer"] = "Instructor de clase",
		["Find {npc:258130}"] = "Encuentra a {npc:258130}",
		["Follow the road south to {area:16624}, in the middle of the isle. {npc:251523} stands on its east side, {npc:251902} in the middle, {npc:254089} just north-west of her, {npc:263664} by the campfire on the west side. With a profession learned, {npc:263664} also offers its Camping 101: its trainer stands in the village."] = "Sigue el camino al sur hasta {area:16624}, en el centro de la isla. {npc:251523} está en su lado este, {npc:251902} en el centro, {npc:254089} justo al noroeste de ella y {npc:263664} junto a la fogata del lado oeste. Con una profesión aprendida, {npc:263664} también ofrece su Campismo 101: su instructor está en la aldea.",
		["Head north into {area:16631}; {npc:257944} camps at its southern edge."] = "Ve al norte hacia {area:16631}; {npc:257944} acampa en su borde sur.",
		["Head south-west to the {area:17674}. {npc:252155} is at the top; the {item:254871} lies beside him."] = "Ve al suroeste hasta {area:17674}. {npc:252155} está en lo alto; la {item:254871} está a su lado.",
		["Heal the injured druids in the Nightfang Den"] = "Cura a los druidas heridos de la guarida (Nightfang Den)",
		["Listen to {npc:252448}'s story"] = "Escucha la historia de {npc:252448}",
		["Listen to {npc:256083}"] = "Escucha a {npc:256083}",
		["Northern {zone:1412}"] = "Norte de {zone:1412}",
		["Pesky Cirrusflies and {npc:250873} roam the grove just south-east of the village."] = "Los Cirrovuelos molestos y {npc:250873} rondan la arboleda justo al sureste de la aldea.",
		["Raw Windstones"] = "Piedras de viento en bruto ({object:613286})",
		["Skyhoppers"] = "Skyhoppers",
		["Skyhoppers hop about the fields just west of Valennia."] = "Varios {npc:251727} saltan por los campos justo al oeste de Valennia.",
		["Spread the {item:278078} off {area:1641}"] = "Esparce el {item:278078} desde {area:1641}",
		["Stormapples and flutterfly dust lie all over the orchard; Hungry Bandits raid it. Galestriders graze in the fields east of it. The broken construct floats at the orchard's north edge."] = "Hay tormanzanas y polvo de alabatiente por todo el huerto; varios {npc:252802} lo saquean. Los Zancavientos pastan en los campos al este. El ensamblaje roto flota en el borde norte del huerto.",
		["Tell {npc:252800} you're ready"] = "Dile a {npc:252800} que estás listo",
		["The Al'Aketh camp"] = "El campamento Al'Aketh",
		["The Raw Windstones are blue crystals on the slopes around the village."] = "Las Piedras de viento en bruto ({object:613286}) son cristales azules en las laderas alrededor de la aldea.",
		["The orchard"] = "El huerto",
		["The queen hovers at the south-east end of the grove, on your way back from the stones."] = "La reina flota en el extremo sureste de la arboleda, de regreso de las piedras.",
		["The standing stones"] = "Las piedras erguidas",
		["The turncoat"] = "El traidor",
		["The {area:16629}"] = "{area:16629}",
		["The {area:16629} is north of {area:16638}. Fight through the guards up to {npc:253576} at its east side."] = "{area:16629} está al norte de {area:16638}. Ábrete paso entre los guardias hasta {npc:253576}, en su lado este.",
		["The {area:17674}"] = "{area:17674}",
		["The {area:17675}"] = "{area:17675}",
		["The {object:148418}"] = "{object:148418}",
		["To {zone:1454}"] = "A {zone:1454}",
		["Upstairs"] = "Arriba",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "Usa el {item:278078} en la estera ceremonial y el quemador del acantilado sur de {area:1641}.",
		["You leave the isle for good. {npc:259119} waits where the airship lands."] = "Dejas la isla para siempre. {npc:259119} espera donde aterriza la aeronave.",
		["You wake in {area:16635}, in the north of the isle. {npc:251362} stands by the path, {npc:251361} at the village centre."] = "Despiertas en {area:16635}, en el norte de la isla. {npc:251362} está junto al sendero, y {npc:251361} en el centro de la aldea.",
		["search the dead cultist in the house"] = "registra al cultista muerto de la casa",
		["search the wardrobe"] = "registra el ropero",
		["talk to {npc:251684}"] = "habla con {npc:251684}",
		["talk to {npc:251902}"] = "habla con {npc:251902}",
		["talk to {npc:251968}"] = "habla con {npc:251968}",
		["talk to {npc:252155}"] = "habla con {npc:252155}",
		["talk to {npc:252476}"] = "habla con {npc:252476}",
		["talk to {npc:253844}"] = "habla con {npc:253844}",
		["talk to {npc:257554}"] = "habla con {npc:257554}",
		["the bounty board"] = "el tablón de recompensas",
		["{area:16624} turn-ins"] = "Entregas en {area:16624}",
		["{area:16635} turn-ins"] = "Entregas en {area:16635}",
		["{area:16663} is west of {area:16638} along the coast road."] = "{area:16663} está al oeste de {area:16638}, por el camino de la costa.",
		["{item:265105} grows around {npc:257944}'s camp and Shriekings fly over it. The Al'Aketh camp east of her holds the {item:265141}."] = "{item:265105} crece alrededor del campamento de {npc:257944}, y criaturas chillonas vuelan sobre él. El campamento Al'Aketh al este de ella guarda la {item:265141}.",
		["{item:278079}, from {npc:3014}"] = "{item:278079}, de {npc:3014}",
		["{item:278080}, from {npc:3012}"] = "{item:278080}, de {npc:3012}",
		["{item:278081}, from {npc:3005}"] = "{item:278081}, de {npc:3005}",
		["{item:278083}, from {npc:3027}"] = "{item:278083}, de {npc:3027}",
		["{npc:249363} stands at the {area:17678}, east of the village. {npc:251143} and Al'Aketh Converts gather just north of her. The {object:460001} is just north-east of her: cast your {spell:1259686} racial ability next to it."] = "{npc:249363} está en {area:17678}, al este de la aldea. {npc:251143} y los Conversos Al'Aketh ({npc:251160}) se reúnen justo al norte de ella. {object:460001} está justo al noreste: usa tu habilidad racial {spell:1259686} a su lado.",
		["{npc:251361}'s errands"] = "Los encargos de {npc:251361}",
		["{npc:251361}: a note from your trainer"] = "{npc:251361}: una nota de tu instructor",
		["{npc:251361}: examine the {item:282418}"] = "{npc:251361}: examina el {item:282418}",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361}: lee la {item:9547}",
		["{npc:251361}: the {item:4100}"] = "{npc:251361}: la {item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "{npc:251373}, el instructor de druidas, en la planta baja del árbol detrás de {npc:251361}",
		["{npc:251374}: {npc:5873} and your {item:5175}"] = "{npc:251374}: {npc:5873} y tu {item:5175}",
		["{npc:251389}, in the watchtower"] = "{npc:251389}, en la atalaya",
		["{npc:251964}, in the watchtower"] = "{npc:251964}, en la atalaya",
		["{npc:252382}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:252382}: {npc:2523}, tu {item:5176} y el {item:263412}",
		["{npc:252448} and {npc:256083}"] = "{npc:252448} y {npc:256083}",
		["{npc:253622}, {npc:258130} and {npc:258134} are in the cult camp east of {npc:257944}. {npc:254151} stands at its edge. Haalien also drops a {quest:94490}: read it to start the next quest. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "{npc:253622}, {npc:258130} y {npc:258134} están en el campamento del culto al este de {npc:257944}. {npc:254151} está en su borde. Haalien también suelta una {quest:94490}: léela para empezar la siguiente misión. Para {quest:94489}, entra en la guarida (Nightfang Den), cura a 7 druidas heridos y encuentra a {npc:258130}.",
		["{npc:254589} lurks south of the village, among the Prideclaws. {npc:254589} is elite: grouping up is advised."] = "{npc:254589} acecha al sur de la aldea, entre los Leozarpas. {npc:254589} es élite: se recomienda ir en grupo.",
		["{npc:256083} stands in the {area:16626} just north-west of town."] = "{npc:256083} está en {area:16626}, justo al noroeste del pueblo.",
		["{npc:256247} waits on the road north of {area:16638}, towards the {area:16629}."] = "{npc:256247} espera en el camino al norte de {area:16638}, hacia {area:16629}.",
		["{npc:257196} holds the {item:263993} on the west side of the shrine."] = "{npc:257196} tiene el {item:263993} en el lado oeste del santuario.",
		["{npc:257944} again"] = "{npc:257944} otra vez",
		["{npc:257944}, last time"] = "{npc:257944}, por última vez",
		["{npc:259118}, by the landing: for {npc:3033} in {zone:1456}"] = "{npc:259118}, junto al aterrizaje: para {npc:3033} en {zone:1456}",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068} quiere incienso tauren: compra sus cuatro partes a {npc:3014}, la herborista; a {npc:3012}, proveedora de encantamiento; a {npc:3005}, proveedor de peletería, y a {npc:3027}, proveedor de cocina; luego combínalas en {item:278078}.",
		["{quest:92529} lies south of Shen'dar. {npc:257065} meets you at its edge; search the wardrobe in the house behind him."] = "{quest:92529} está al sur de Shen'dar. {npc:257065} te espera en las afueras; registra el ropero de la casa detrás de él.",
} end)()
t.guides["forever/horde/tauren/01-mulgore"] = (function() return {
		["/sit by Kaga's campfire until you get {spell:1229451}"] = "Usa /sentarse junto a la fogata de Kaga hasta obtener {spell:1229451}",
		["Back east to {area:358}: the Bristleback Shamans stand among the quilboar there."] = "De vuelta al este a {area:358}: los Chamanes Erizapúas ({npc:2953}) están entre los jabaespines de allí.",
		["Back north-west up to {area:221}."] = "Regresa al noroeste, subiendo hasta {area:221}.",
		["Back south-east to the {area:396}."] = "De vuelta al sureste a {area:396}.",
		["Back to {npc:5888} in the camp. The {npc:5891} waits on the mesa east of the camp: drink the {item:6635} there to see it, then take the {item:6656} back to the Seer."] = "De vuelta con {npc:5888} en el campamento. La {npc:5891} espera en la meseta al este del campamento: bebe {item:6635} allí para verla y luego llévale {item:6656} al Vidente.",
		["Back west to the camp."] = "De vuelta al oeste al campamento.",
		["Battleboars graze north of the shrine; the Bristleback quilboar hold the ravine to the north-east. {npc:8554} stands at its eastern end, and the {object:3076} lies on the ground in the camp."] = "Los jabaguerreros pastan al norte del santuario; los jabaespines Erizapúas ocupan el barranco al noreste. {npc:8554} está en su extremo este y {object:3076} está en el suelo del campamento.",
		["Below ground"] = "Bajo tierra",
		["Class trainer"] = "Instructor de clase",
		["Cross north-west past {zone:1456} to the {area:398} in the far north of {zone:1412}."] = "Cruza al noroeste pasando {zone:1456} hasta {area:398}, en el extremo norte de {zone:1412}.",
		["Follow the road north out of {area:220}. {npc:265810} waits on the road just south of {area:222}; /sit by her campfire until you get {spell:1229451}. With a profession learned, Kaga also offers its Camping 101, which its trainer takes: in Bloodhoof or on the {zone:1456} stop."] = "Sigue el camino al norte fuera de {area:220}. {npc:265810} espera en el camino justo al sur de {area:222}; usa /sentarse junto a su fogata hasta obtener {spell:1229451}. Con una profesión aprendida, Kaga también ofrece su Campamento 101, que recibe su instructor: en Poblado Pezuña de Sangre o en la parada de {zone:1456}.",
		["Galak centaurs"] = "Centauros Galak",
		["Head north to {area:225}, east of {zone:1456}. {npc:3233} stands at the foot of the rocks; the Bristleback Interlopers dig at the burial ground and the {npc:2994} waits on top."] = "Ve al norte hasta {area:225}, al este de {zone:1456}. {npc:3233} está al pie de las rocas; los Intrusos Erizapúas ({npc:3232}) excavan en el cementerio y el {npc:2994} espera en la cima.",
		["Prairie Wolf Alphas roam among the wolves on the plains around {npc:275789} and the Galak camp to the east."] = "Los Lobos alfa de pradera recorren la zona entre los lobos de las llanuras alrededor de {npc:275789} y del campamento Galak al este.",
		["Prairie Wolves and Adult Plainstriders roam the plains around the village."] = "Los lobos de pradera y los Zancudos de llanura adultos ({npc:2956}) deambulan por las llanuras alrededor del poblado.",
		["Ride a lift up to the mesas. {npc:2995} keeps the wind riders on the central rise; {npc:3057} stands in the great tent there."] = "Sube en un elevador a las mesetas. {npc:2995} cuida a los jinetes del viento en la elevación central; {npc:3057} está en la gran tienda de allí.",
		["Spread the {item:278078} off {area:1641}"] = "Esparce {item:278078} desde {area:1641}",
		["Tame it with the {item:15908}"] = "Domestícalo con {item:15908}",
		["The Palemane gnolls hold {area:818}, south of the digsite and west of Bloodhoof. {npc:272203} is held in their camp: lead him out."] = "Los gnolls Crines Pálidas ocupan {area:818}, al sur de la excavación y al oeste de Poblado Pezuña de Sangre. {npc:272203} está cautivo en su campamento: guíalo afuera.",
		["The Seer's tent stands at the foot of the cougars' hills."] = "La tienda del Vidente está al pie de las colinas de los pumas.",
		["The Windfury harpies hold {area:819}, north and west of the well."] = "Las arpías Viento Furioso ocupan {area:819}, al norte y al oeste del pozo.",
		["The dwarves of the {area:404} carry the Prospector's Picks. Smash them at the dwarves' forge in the digsite."] = "Los enanos de {area:404} llevan los Picos de prospector. Destrúyelos en la forja de los enanos de la excavación.",
		["The goblins work the mine in the hills north-east of the well. {quest:765} stands in the back of the mine; his {item:281031} start {quest:98424}, and the other pages lie inside the mine."] = "Los goblins trabajan la mina en las colinas al noreste del pozo. {quest:765} está al fondo de la mina; sus {item:281031} inician {quest:98424}, y las otras páginas están dentro de la mina.",
		["The incense burns out in ten minutes: run straight east along the southern hills to the {object:660739}."] = "El incienso se consume en diez minutos: corre directo al este por las colinas del sur hasta {object:660739}.",
		["The shrine of An'she and Mu'sha"] = "El santuario de An'she y Mu'sha",
		["The stone stands in the pass out of {zone:1412}, on your way east. Use the {item:15710} there and defeat Lunaclaw."] = "La piedra está en el paso que sale de {zone:1412}, de camino al este. Usa {item:15710} allí y derrota a Garraluna.",
		["The wrecked caravan lies north-west of the centaurs, east of the road to {zone:1456}."] = "La caravana destrozada está al noroeste de los centauros, al este del camino a {zone:1456}.",
		["The {object:177525}"] = "{object:177525}",
		["To {zone:1454}"] = "A {zone:1454}",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "Usa {item:278078} en la estera ceremonial y el quemador del acantilado sur de {area:1641}.",
		["You start on the mesa of {area:221}. {npc:2980} and the chief stand by the big tent in the middle."] = "Empiezas en la meseta de {area:221}. {npc:2980} y el jefe están junto a la gran tienda del centro.",
		["{item:278079}, from {npc:3014}"] = "{item:278079}, de {npc:3014}",
		["{item:278080}, from {npc:3012}"] = "{item:278080}, de {npc:3012}",
		["{item:278081}, from {npc:3005}"] = "{item:278081}, de {npc:3005}",
		["{item:278083}, from {npc:3027}"] = "{item:278083}, de {npc:3027}",
		["{item:4703}, at the digsite forge"] = "{item:4703}, en la forja de la excavación",
		["{item:5203}: Flatland Prowlers roam the plains around {area:225}"] = "{item:5203}: los merodeadores de las estepas recorren las llanuras alrededor de {area:225}",
		["{npc:10378}, beside {npc:3418}"] = "{npc:10378}, junto a {npc:3418}",
		["{npc:265810}: for {npc:10278}"] = "{npc:265810}: para {npc:10278}",
		["{npc:265810}: for {npc:11047}"] = "{npc:265810}: para {npc:11047}",
		["{npc:265810}: for {npc:11051}"] = "{npc:265810}: para {npc:11051}",
		["{npc:265810}: for {npc:11071}"] = "{npc:265810}: para {npc:11071}",
		["{npc:265810}: for {npc:3001}"] = "{npc:265810}: para {npc:3001}",
		["{npc:265810}: for {npc:3013}"] = "{npc:265810}: para {npc:3013}",
		["{npc:265810}: for {npc:3069}"] = "{npc:265810}: para {npc:3069}",
		["{npc:265810}: for {npc:5938}"] = "{npc:265810}: para {npc:5938}",
		["{npc:265810}: for {npc:5939}"] = "{npc:265810}: para {npc:5939}",
		["{npc:265810}: for {npc:6290}"] = "{npc:265810}: para {npc:6290}",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068} quiere incienso tauren: compra sus cuatro partes a {npc:3014} la herbolaria, a {npc:3012} la proveedora de encantamiento, a {npc:3005} la proveedora de peletería y a {npc:3027} el proveedor de cocina; luego combínalas en {item:278078}.",
		["{npc:277182} stands at the north edge of the village. Kyle wants {item:287505} from plainstriders."] = "{npc:277182} está en el borde norte del poblado. Kyle quiere {item:287505} de los zancudos de llanura.",
		["{npc:277182}, at the north end of the village"] = "{npc:277182}, en el extremo norte del poblado",
		["{npc:2948}, for Hamuul in {zone:1456}"] = "{npc:2948}, para Hamuul en {zone:1456}",
		["{npc:2984} stands at the edge of the {area:404}, south of the well."] = "{npc:2984} está al borde de {area:404}, al sur del pozo.",
		["{npc:2991} sits by the tent on the camp's eastern edge; the {object:2907} stands next to her."] = "{npc:2991} está sentada junto a la tienda del borde este del campamento; {object:2907} está a su lado.",
		["{npc:2993}, for {npc:3057} in {zone:1456}"] = "{npc:2993}, para {npc:3057} en {zone:1456}",
		["{npc:3060}, the druid trainer beside him"] = "{npc:3060}, el instructor de druidas a su lado",
		["{npc:3061}, the hunter trainer"] = "{npc:3061}, la instructora de cazadores",
		["{npc:3062}, the shaman trainer in camp"] = "{npc:3062}, la instructora de chamanes del campamento",
		["{npc:3063}'s quest: beat three Novice Warriors (or players in duels) next to him."] = "Misión de {npc:3063}: vence a tres Guerreros novicios ({npc:10721}) (o a jugadores en duelos) a su lado.",
		["{npc:3069}, beside {npc:3067}: {quest:97934}"] = "{npc:3069}, junto a {npc:3067}: {quest:97934}",
		["{npc:3418} stands at {area:378}, where the road from {zone:1412} meets the {area:458} north to the Crossroads."] = "{npc:3418} está en {area:378}, donde el camino de {zone:1412} se une a {area:458}, que va al norte hacia El Cruce.",
		["{npc:3418}: for {npc:3429} at the Crossroads"] = "{npc:3418}: para {npc:3429} en El Cruce",
		["{npc:3429}, by the wind rider tower"] = "{npc:3429}, junto a la torre de jinetes del viento",
		["{npc:3615}, the wind rider master"] = "{npc:3615}, el maestro de jinetes del viento",
		["{npc:5888} stands in {area:221}. {quest:1516} needs level 4, which you reach with the turn-ins here."] = "{npc:5888} está en {area:221}. {quest:1516} necesita nivel 4, que alcanzas con las entregas de aquí.",
		["{npc:5888}: {npc:5873} and your {item:5175}"] = "{npc:5888}: {npc:5873} y tu {item:5175}",
		["{npc:6290}, beside {npc:3067}: {quest:97936}"] = "{npc:6290}, junto a {npc:3067}: {quest:97936}",
		["{npc:6775} stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, then hunt the cougars south through the hills towards the Seer's tent at their foot."] = "{npc:6775} está en el extremo oeste del campamento, en la esquina noroeste de las colinas donde merodean los Pumas monteses ({npc:2961}): toma su misión y luego caza los pumas hacia el sur por las colinas, rumbo a la tienda del Vidente, al pie de ellas.",
		["{quest:96130}, a lone wolf, prowls the plains west of the village. Prairie Stalkers and Flatland Cougars roam the plains north and west of it."] = "{quest:96130}, un lobo solitario, merodea las llanuras al oeste del poblado. Los Acechadores de pradera ({npc:2959}) y los Pumas de las estepas ({npc:3035}) recorren las llanuras al norte y al oeste.",
} end)()
t.guides["forever/horde/troll/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "Los Escórpidos acorazados ({npc:3126}) se arrastran por las llanuras al oeste de {area:362}. Domestica uno y luego regresa con {npc:3171}.",
		["Back to the Den"] = "De vuelta a la Guarida",
		["Back to {area:362}."] = "De vuelta a {area:362}.",
		["Below ground"] = "Bajo tierra",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}."] = "Los sectarios de Filo Ardiente ocupan las cuevas de {quest:827}; cualquiera suelta un {item:4871}. {npc:3204}, un brujo de nivel 14, está en lo más profundo y suelta {item:4903}.",
		["Class trainer"] = "Instructor de clase",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "Los acechadores viles recorren la ladera bajo la cueva, en el lado norte del valle.",
		["Follow the road east out of the valley to {area:367} on the coast."] = "Sigue el camino al este fuera del valle hasta {area:367}, en la costa.",
		["Free {npc:275811} and see her safely out of the crag"] = "Libera a {npc:275811} y acompáñala a salvo fuera del risco",
		["Heal and fortify {npc:12430}"] = "Sana y fortalece a {npc:12430}",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "Dentro de la cueva, sigue derecho en la primera bifurcación, luego a la derecha y sigue el arroyo a tu izquierda hasta la cascada: el pico brilla junto al agua, detrás de una columna de roca.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "Dentro de la cueva, sigue la pared derecha todo el camino, pasando sobre el arroyo: {npc:3183} espera al final.",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "La choza de Misha está al sur de los truenagartos. Los crocoliscos a lo largo de {area:814}, al oeste, llevan {item:4891}.",
		["Prickly pears"] = "Higos chumbos",
		["Quilboars and scouts hold the huts west of town; dustrunners and battleguards hold the camps farther west."] = "Los jabaespines y exploradores ocupan las chozas al oeste del pueblo; los polvorosos y guardias de batalla ocupan los campamentos más al oeste.",
		["Spitelash naga"] = "Nagas Látigo de Ira",
		["Tame it with the {item:15908}"] = "Domestícalo con {item:15908}",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}. {npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "El fuerte está en la costa al sureste de {area:362}. El hacha, el arco y el escudo de los asaltantes están en sus afueras. Los marineros y marines sueltan {item:4870}. {npc:3192} espera en lo alto del fuerte; su llave abre el cofre a su lado, que contiene {item:4881}.",
		["The prickly pears grow among the quilboar huts just west of town."] = "Los higos chumbos crecen entre las chozas de los jabaespines, justo al oeste del pueblo.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "Las armas están alrededor de la Guarida y del campo de entrenamiento; los Jabalíes jaspeados ({npc:3098}) recorren todo el fondo del valle.",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "{object:58595} está en {area:817}, entre los sectarios con los que acabas de pelear.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, beside the road north to {zone:1454}; any of them can drop a {item:6486}. {npc:5810} takes it when the next guide passes {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Los Truenagartos ({npc:3130}) y los Lomorrayos ({npc:3131}) pastan en {area:369}, junto al camino al norte hacia {zone:1454}; cualquiera puede soltar {item:6486}. {npc:5810} la recibe cuando la siguiente guía pasa por {area:379}.\nCuidado: Halikor, un élite de nivel 12, recorre {area:369} entre los lagartos: ubícalo antes de atraer.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, just west and south-west of {npc:3293}.\nFizzle holds the Burning Blade camp on {area:369}, north-west of {area:362}. Hunters: tame a {npc:3099} with the {item:15908} on the way.\nCareful: Burning Blade cultists surround Fizzle, some linked so they aggro in pairs, and they respawn quickly.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Los truenagartos y lomorrayos pastan en {area:369}, justo al oeste y suroeste de {npc:3293}.\nFizzle ocupa el campamento del Filo Ardiente en {area:369}, al noroeste de {area:362}. Cazadores: domestica un {npc:3099} con la {item:15908} en el camino.\nCuidado: los cultores del Filo Ardiente rodean a Fizzle, algunos vinculados, así que atacan en parejas, y reaparecen rápido.\nCuidado: Halikor, un élite de nivel 12, recorre {area:369} entre los lagartos: ubícalo antes de atraer.",
		["To {zone:1454}"] = "A {zone:1454}",
		["Training weapons and boars"] = "Armas de entrenamiento y jabalíes",
		["Upstairs"] = "Arriba",
		["Wake {quest:5441} with the {item:16114}"] = "Despierta a {quest:5441} con {item:16114}",
		["the {object:654925} on the ground beside her"] = "{object:654925}, en el suelo a su lado",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366} está al oeste de Sen'jin. Los tres planes de ataque están en el suelo entre las tiendas de los centauros. {npc:275811} también está cautiva en el risco.",
		["{area:817}'s mouth"] = "Entrada de {area:817}",
		["{npc:10176}, where you start"] = "{npc:10176}, donde empiezas",
		["{npc:12430} kneels behind the rocks just off the road south of {area:362}, on your way to the keep. Cast {spell:613} (Rank 2) on her, then {spell:1243}: Rank 1 of {spell:613} does not count."] = "{npc:12430} está arrodillada detrás de las rocas, junto al camino al sur de {area:362}, de camino al fuerte. Lánzale {spell:613} (rango 2) y luego {spell:1243}: el rango 1 de {spell:613} no cuenta.",
		["{npc:265809} camps just south of {area:362}. Sit by his campfire (/sit) until the {spell:1229451} buff appears. With a profession learned, {npc:265809} also offers its Camping 101, which its trainer takes: in {area:362} or in {zone:1454} at the start of the next guide."] = "{npc:265809} acampa justo al sur de {area:362}. Siéntate junto a su fogata (/sit) hasta que aparezca el beneficio {spell:1229451}. Si aprendiste una profesión, {npc:265809} también ofrece su Camping 101, que recibe su instructor: en {area:362} o en {zone:1454}, al inicio de la siguiente guía.",
		["{npc:265809}'s campfire"] = "La fogata de {npc:265809}",
